window.COURS_JSON = {"meta": {"cours": "UC1 \u2014 Anatomie", "auteur": "ADJ Robichon", "source": "ANATOMIE _230831_213333.pdf", "slides": 328}, "chapitres": [{"num": 1, "titre": "Terminologie anatomique", "slides": [7, 43], "sections": [{"titre": "La position anatomique", "slide": 9, "points": ["D\u00e9finition de convention internationale : \u00ab Corps humain, vivant, debout, les membres sup\u00e9rieurs allong\u00e9s le long du corps, la paume des mains tourn\u00e9e en avant, le regard droit et horizontal. \u00bb", "Toutes les descriptions anatomiques se r\u00e9f\u00e8rent \u00e0 cette position."]}, {"titre": "L'axe du corps", "slide": 11, "points": ["Verticale partant d'un point situ\u00e9 au sommet du cr\u00e2ne (vertex).", "Elle passe par le centre de gravit\u00e9 du corps, situ\u00e9 dans le pelvis (bassin osseux)."]}, {"titre": "L'axe de la main et l'axe du pied", "slide": 13, "points": ["Axe de la main : axe longitudinal passant par le 3e doigt.", "Axe du pied : axe longitudinal passant par le 2e orteil."]}, {"titre": "Les trois plans anatomiques", "slide": 15, "points": ["Trois plans se coupent sur la silhouette : le plan frontal, le plan sagittal et le plan transversal.", "Trois axes leur r\u00e9pondent sur la figure : l'axe vertical, l'axe sagittal et l'axe transversal."]}, {"titre": "Le plan frontal", "slide": 17, "points": ["Plan dans lequel se font les mouvements visibles de face.", "Il divise le corps en 2 faces : une ant\u00e9rieure (ventrale) et une post\u00e9rieure (dorsale).", "Mouvements observ\u00e9s : abduction et adduction ; inclinaison lat\u00e9rale, droite ou gauche.", "L'abduction \u00e9carte un membre de l'axe du corps, l'adduction l'en rapproche.", "L'inclinaison lat\u00e9rale concerne la t\u00eate et le tronc."]}, {"titre": "Le plan sagittal", "slide": 22, "points": ["Plan dans lequel se font les mouvements visibles de profil.", "Il divise le corps en 2 parties : droite et gauche.", "Quand le plan sagittal est situ\u00e9 sur la ligne m\u00e9diane et que les parties sont sym\u00e9triques et \u00e9gales, on parle de plan (sagittal) m\u00e9dian.", "Mouvements observ\u00e9s : flexion / extension, ant\u00e9pulsion / r\u00e9tropulsion, ant\u00e9version / r\u00e9troversion, flexion dorsale / flexion plantaire.", "Trois articulations portent ces mouvements nomm\u00e9s : scapulo-hum\u00e9rale, coxo-f\u00e9morale, talo-crurale."]}, {"titre": "Le plan transversal", "slide": 30, "points": ["Plan dans lequel les mouvements sont visibles d'en haut ou d'en bas.", "Il divise le corps en 2 parties : une inf\u00e9rieure et une sup\u00e9rieure.", "Mouvements observ\u00e9s : rotation (droite / gauche, ou lat\u00e9rale / m\u00e9diale) ; pronation et supination.", "Pronation et supination ne d\u00e9signent que des mouvements du radius autour de l'ulna."]}, {"titre": "Un mouvement particulier : la circumduction", "slide": 35, "points": ["Mouvement au cours duquel le membre d\u00e9crit un c\u00f4ne dans l'espace.", "Exemple : circumduction du bras.", "Le cours la pr\u00e9sente \u00e0 part, apr\u00e8s les trois plans, et ne la range dans aucun d'eux."]}, {"titre": "Termes de localisation", "slide": 37, "points": ["Cinq couples : cr\u00e2nial et caudal ; proximal et distal ; m\u00e9dial et lat\u00e9ral ; superficiel et profond ; ant\u00e9rieur et post\u00e9rieur.", "Chaque couple a son propre rep\u00e8re : l'extr\u00e9mit\u00e9 du tronc, le tronc, le plan m\u00e9dian, la surface du corps, l'avant et l'arri\u00e8re."]}], "planches": [{"id": "plan-frontal", "titre": "Le plan frontal", "vb": "0 0 240 360", "dessin": "<defs><marker id='fleche' viewBox='0 0 10 10' refX='9' refY='5' markerWidth='6' markerHeight='6' orient='auto'><path d='M0 0 L10 5 L0 10 Z' fill='currentColor'/></marker></defs><g class='corps' fill='none' stroke='currentColor' stroke-width='2'><circle cx='120' cy='40' r='20'/><path d='M120 60 L120 160'/><path d='M120 78 L82 122 M120 78 L158 122'/><path d='M120 160 L90 248 M120 160 L150 248'/></g><g class='plan plan--frontal' fill='none' stroke='currentColor'><path d='M75 15 L165 15 L165 255 L75 255 Z' stroke-dasharray='5 4' stroke-width='1.5'/><path d='M158 122 Q186 96 180 74' stroke-width='2' marker-end='url(#fleche)'/></g>", "pastilles": [{"n": 1, "x": 120, "y": 268, "t": "Plan frontal", "ancre": "middle", "plan": "frontal", "indice": "nom du plan"}, {"n": 2, "x": 120, "y": 308, "t": "Abduction, adduction", "ancre": "middle", "plan": "frontal", "indice": "mouvements de ce plan"}], "slide": 15}, {"id": "plan-sagittal", "titre": "Le plan sagittal", "vb": "0 0 240 360", "dessin": "<defs><marker id='fleche' viewBox='0 0 10 10' refX='9' refY='5' markerWidth='6' markerHeight='6' orient='auto'><path d='M0 0 L10 5 L0 10 Z' fill='currentColor'/></marker></defs><g class='corps' fill='none' stroke='currentColor' stroke-width='2'><circle cx='120' cy='40' r='18'/><path d='M120 58 L120 150'/><path d='M120 80 L148 118'/><path d='M120 150 L132 205 L105 232'/></g><g class='plan plan--sagittal' fill='none' stroke='currentColor'><path d='M95 15 L162 15 L162 255 L95 255 Z' stroke-dasharray='5 4' stroke-width='1.5'/><path d='M140 197 Q158 215 134 233' stroke-width='2' marker-end='url(#fleche)'/></g>", "pastilles": [{"n": 1, "x": 120, "y": 268, "t": "Plan sagittal", "ancre": "middle", "plan": "sagittal", "indice": "nom du plan"}, {"n": 2, "x": 120, "y": 308, "t": "Flexion, extension", "ancre": "middle", "plan": "sagittal", "indice": "mouvements de ce plan"}], "slide": 15}, {"id": "plan-transversal", "titre": "Le plan transversal", "vb": "0 0 240 360", "dessin": "<defs><marker id='fleche' viewBox='0 0 10 10' refX='9' refY='5' markerWidth='6' markerHeight='6' orient='auto'><path d='M0 0 L10 5 L0 10 Z' fill='currentColor'/></marker></defs><g class='corps' fill='none' stroke='currentColor' stroke-width='2'><circle cx='120' cy='40' r='20'/><path d='M120 60 L120 160'/><path d='M120 78 L82 122 M120 78 L158 122'/><path d='M120 160 L90 248 M120 160 L150 248'/></g><g class='plan plan--transversal' fill='none' stroke='currentColor'><ellipse cx='120' cy='112' rx='55' ry='16' stroke-dasharray='5 4' stroke-width='1.5'/><path d='M160 106 A44 15 0 0 1 80 106' stroke-width='2' marker-end='url(#fleche)'/></g>", "pastilles": [{"n": 1, "x": 120, "y": 268, "t": "Plan transversal", "ancre": "middle", "plan": "transversal", "indice": "nom du plan"}, {"n": 2, "x": 120, "y": 308, "t": "Rotation, pronation, supination", "ancre": "middle", "plan": "transversal", "indice": "mouvements de ce plan"}], "slide": 15}, {"id": "termes-localisation", "titre": "Les termes de localisation", "vb": "0 0 320 340", "dessin": "<defs><marker id='fleche' viewBox='0 0 10 10' refX='9' refY='5' markerWidth='6' markerHeight='6' orient='auto'><path d='M0 0 L10 5 L0 10 Z' fill='currentColor'/></marker></defs><g class='corps' fill='none' stroke='currentColor' stroke-width='2'><circle cx='160' cy='48' r='26'/><path d='M160 74 L160 196'/><path d='M160 96 L104 150 M160 96 L216 150'/><path d='M160 196 L128 292 M160 196 L192 292'/></g><g class='reperes' fill='none' stroke='currentColor' stroke-width='1.5'><path d='M112 90 L112 34' marker-end='url(#fleche)'/><path d='M112 250 L112 304' marker-end='url(#fleche)'/><path d='M193 244 L180 205' marker-end='url(#fleche)'/><path d='M194 249 L206 282' marker-end='url(#fleche)'/><path d='M120 158 L152 158' marker-end='url(#fleche)'/><path d='M170 183 L202 183' marker-end='url(#fleche)'/></g>", "pastilles": [{"n": 1, "x": 108, "y": 24, "t": "Cr\u00e2nial", "ancre": "end"}, {"n": 2, "x": 108, "y": 316, "t": "Caudal", "ancre": "end"}, {"n": 3, "x": 196, "y": 215, "t": "Proximal", "ancre": "start"}, {"n": 4, "x": 214, "y": 270, "t": "Distal", "ancre": "start"}, {"n": 5, "x": 150, "y": 178, "t": "M\u00e9dial", "ancre": "end"}, {"n": 6, "x": 204, "y": 167, "t": "Lat\u00e9ral", "ancre": "start"}], "slide": 37}], "cartes": [{"id": "c1-01", "q": "\u00c9nonce la d\u00e9finition conventionnelle de la position anatomique.", "r": "Corps humain, vivant, debout, les membres sup\u00e9rieurs allong\u00e9s le long du corps, la paume des mains tourn\u00e9e en avant, le regard droit et horizontal. Toutes les descriptions anatomiques se r\u00e9f\u00e8rent \u00e0 cette position.", "slide": 9}, {"id": "c1-02", "q": "Par quels points passe l'axe du corps ?", "r": "C'est la verticale partant d'un point situ\u00e9 au sommet du cr\u00e2ne (vertex) et passant par le centre de gravit\u00e9 du corps, situ\u00e9 dans le pelvis (bassin osseux).", "slide": 11}, {"id": "c1-03", "q": "Quel doigt porte l'axe de la main ? Quel orteil porte l'axe du pied ?", "r": "L'axe de la main est l'axe longitudinal passant par le 3e doigt. L'axe du pied est l'axe longitudinal passant par le 2e orteil.", "slide": 13}, {"id": "c1-04", "q": "Le plan frontal : quels mouvements y sont visibles, et en quoi divise-t-il le corps ?", "r": "C'est le plan des mouvements visibles de face. Il divise le corps en 2 faces : une ant\u00e9rieure (ventrale) et une post\u00e9rieure (dorsale).", "slide": 17, "plan": "frontal"}, {"id": "c1-05", "q": "Cite les mouvements observ\u00e9s dans le plan frontal.", "r": "Abduction et adduction ; inclinaison lat\u00e9rale, droite ou gauche.", "slide": 18, "plan": "frontal"}, {"id": "c1-06", "q": "Abduction ou adduction : lequel \u00e9carte le membre de l'axe du corps ?", "r": "L'abduction \u00e9carte un membre de l'axe du corps (exemple : abduction d'\u00e9paule). L'adduction rapproche un membre de l'axe du corps (exemple : adduction de hanche).", "slide": 19, "plan": "frontal"}, {"id": "c1-07", "q": "L'inclinaison lat\u00e9rale concerne quelles parties du corps, et comment la nomme-t-on ?", "r": "Elle concerne les mouvements de la t\u00eate et du tronc, dans le plan frontal. On parle d'inclinaison lat\u00e9rale gauche ou droite (exemple : inclinaison lat\u00e9rale droite du tronc).", "slide": 20, "plan": "frontal"}, {"id": "c1-08", "q": "Le plan sagittal : quels mouvements y sont visibles, en quoi divise-t-il le corps, et quand parle-t-on de plan m\u00e9dian ?", "r": "C'est le plan des mouvements visibles de profil. Il divise le corps en 2 parties, droite et gauche. Quand il est situ\u00e9 sur la ligne m\u00e9diane et que les parties sont sym\u00e9triques et \u00e9gales, on parle de plan (sagittal) m\u00e9dian.", "slide": 22, "plan": "sagittal"}, {"id": "c1-09", "q": "Cite les quatre couples de mouvements observ\u00e9s dans le plan sagittal.", "r": "Flexion / extension ; ant\u00e9pulsion / r\u00e9tropulsion ; ant\u00e9version / r\u00e9troversion ; flexion dorsale / flexion plantaire.", "slide": 23, "plan": "sagittal"}, {"id": "c1-10", "q": "D\u00e9finis la flexion en termes d'angle articulaire.", "r": "Mouvement de repli qui diminue l'angle de l'articulation et rapproche deux segments osseux l'un de l'autre (exemples : flexion du poignet, flexion de hanche).", "slide": 24, "plan": "sagittal"}, {"id": "c1-11", "q": "D\u00e9finis l'extension en termes d'angle articulaire.", "r": "C'est le mouvement inverse de la flexion : il augmente l'angle de l'articulation et \u00e9loigne deux segments osseux l'un de l'autre (exemple : extension de la hanche).", "slide": 25, "plan": "sagittal"}, {"id": "c1-12", "q": "Ant\u00e9pulsion et r\u00e9tropulsion : de quelle articulation s'agit-il, et que font-elles ?", "r": "L'articulation scapulo-hum\u00e9rale. L'ant\u00e9pulsion est une ouverture bras-tronc, la r\u00e9tropulsion une fermeture bras-tronc.", "slide": 26, "plan": "sagittal"}, {"id": "c1-13", "q": "Ant\u00e9version et r\u00e9troversion : quelle articulation, et quel effet sur le dos ?", "r": "L'articulation coxo-f\u00e9morale. L'ant\u00e9version am\u00e8ne le bassin vers l'avant (\u00ab dos creux \u00bb), la r\u00e9troversion am\u00e8ne le bassin vers l'arri\u00e8re (\u00ab dos plat \u00bb).", "slide": 27, "plan": "sagittal"}, {"id": "c1-14", "q": "Flexion dorsale et flexion plantaire : quelle articulation, et \u00e0 quel mouvement chacune correspond-elle ?", "r": "L'articulation talo-crurale. La flexion dorsale est l'action d'effectuer une flexion du pied ; la flexion plantaire est l'action d'effectuer une extension du pied.", "slide": 28, "plan": "sagittal"}, {"id": "c1-15", "q": "Le plan transversal : d'o\u00f9 les mouvements y sont-ils visibles, et en quoi divise-t-il le corps ?", "r": "Les mouvements y sont visibles d'en haut ou d'en bas. Il divise le corps en 2 parties : une inf\u00e9rieure et une sup\u00e9rieure.", "slide": 30, "plan": "transversal"}, {"id": "c1-16", "q": "Cite les mouvements observ\u00e9s dans le plan transversal.", "r": "La rotation (droite / gauche, ou lat\u00e9rale / m\u00e9diale) ; la pronation et la supination.", "slide": 31, "plan": "transversal"}, {"id": "c1-17", "q": "D\u00e9finis la rotation, puis dis quel vocabulaire s'applique \u00e0 la t\u00eate et au tronc, et lequel s'applique aux membres.", "r": "La rotation est le mouvement d'un segment sur un axe. Pour la t\u00eate et le tronc : rotation droite ou gauche. Pour les membres : rotation lat\u00e9rale (externe) ou m\u00e9diale (interne).", "slide": 32, "plan": "transversal"}, {"id": "c1-18", "q": "Pronation et supination : d\u00e9finis-les, et dis o\u00f9 se trouve le radius dans chaque cas.", "r": "Pronation : rotation m\u00e9diale de l'avant-bras, le radius croise l'ulna. Supination : rotation lat\u00e9rale de l'avant-bras, le radius est parall\u00e8le \u00e0 l'ulna.", "slide": 33, "plan": "transversal"}, {"id": "c1-19", "q": "Quels os la pronation et la supination mettent-elles en jeu ?", "r": "Elles ne d\u00e9signent que des mouvements du radius autour de l'ulna.", "slide": 34, "plan": "transversal"}, {"id": "c1-20", "q": "Qu'est-ce que la circumduction ?", "r": "Le mouvement au cours duquel le membre d\u00e9crit un c\u00f4ne dans l'espace (exemple : circumduction du bras). Le cours la pr\u00e9sente comme un mouvement particulier, \u00e0 part des trois plans.", "slide": 35}, {"id": "c1-21", "q": "Cr\u00e2nial et caudal : quelle r\u00e9gion du corps concernent-ils, et que signifient-ils ?", "r": "Ces termes concernent essentiellement le tronc. Une partie est cr\u00e2niale lorsqu'elle est plus proche de l'extr\u00e9mit\u00e9 sup\u00e9rieure du tronc, caudale lorsqu'elle est plus proche de l'extr\u00e9mit\u00e9 inf\u00e9rieure. On utilise \u00e9galement sup\u00e9rieur et inf\u00e9rieur. Exemple sur le sternum : le manubrium est cr\u00e2nial, le processus xypho\u00efde est caudal.", "slide": 38}, {"id": "c1-22", "q": "Proximal et distal : quelle r\u00e9gion du corps concernent-ils, et quel est le rep\u00e8re ?", "r": "Ces termes concernent essentiellement les membres, et le rep\u00e8re est le tronc : une partie est proximale lorsqu'elle est plus proche du tronc, distale lorsqu'elle en est plus distante. Exemple sur l'hum\u00e9rus : \u00e9piphyse proximale et \u00e9piphyse distale.", "slide": 39}, {"id": "c1-23", "q": "M\u00e9dial et lat\u00e9ral : quel est le rep\u00e8re, et quels sont leurs synonymes ?", "r": "Le rep\u00e8re est le plan m\u00e9dian. Un \u00e9l\u00e9ment est m\u00e9dial (interne) lorsqu'il est situ\u00e9 plus pr\u00e8s du plan m\u00e9dian, lat\u00e9ral (externe) lorsqu'il en est plus loin. Exemple \u00e0 la jambe : le tibia est l'os m\u00e9dial, la fibula l'os lat\u00e9ral.", "slide": 40}, {"id": "c1-24", "q": "Superficiel et profond : que signifient-ils ?", "r": "Un \u00e9l\u00e9ment est superficiel lorsqu'il est plus proche de la surface externe du corps, profond lorsqu'il est situ\u00e9 vers l'int\u00e9rieur du corps. Exemple : la peau est superficielle, le muscle est profond.", "slide": 41}, {"id": "c1-25", "q": "Ant\u00e9rieur / post\u00e9rieur, ventral / dorsal, palmaire, plantaire : \u00e0 quoi chaque terme s'applique-t-il ?", "r": "Ant\u00e9rieur (ventral) : situ\u00e9 en avant. Post\u00e9rieur (dorsal) : situ\u00e9 en arri\u00e8re. Ant\u00e9rieur et post\u00e9rieur sont plus sp\u00e9cifiques pour la t\u00eate et les membres, ventral et dorsal pour le tronc. Pour la main, palmaire signifie ant\u00e9rieur, le dos de la main \u00e9tant la face post\u00e9rieure. Pour le pied, on utilise les termes plantaire et dorsal.", "slide": 42}], "quiz": [{"id": "q1-01", "q": "Dans quel plan s'effectue une inclinaison lat\u00e9rale du tronc ?", "choix": ["Le plan sagittal", "Le plan frontal", "Le plan transversal"], "bonne": 1, "expl": "L'inclinaison lat\u00e9rale concerne la t\u00eate et le tronc, dans le plan frontal : c'est un mouvement visible de face. Le plan sagittal tente parce que c'est lui qui s\u00e9pare la droite de la gauche \u2014 mais s\u00e9parer droite et gauche n'est pas porter les mouvements qui vont vers la droite ou vers la gauche : le sagittal porte ce qui se voit de profil (flexion, extension). Le plan transversal porte lui aussi un mouvement du tronc vers la droite ou vers la gauche, mais c'est la rotation, pas l'inclinaison.", "slide": 20, "plan": "frontal"}, {"id": "q1-02", "q": "Dans la position anatomique, comment sont plac\u00e9s les membres sup\u00e9rieurs et les mains ?", "choix": ["Allong\u00e9s le long du corps, la paume tourn\u00e9e vers la cuisse", "En abduction d'\u00e9paule \u00e0 90\u00b0, la paume tourn\u00e9e en avant", "Allong\u00e9s le long du corps, la paume tourn\u00e9e en avant", "Allong\u00e9s le long du corps, la paume tourn\u00e9e en arri\u00e8re"], "bonne": 2, "expl": "La convention impose la paume tourn\u00e9e en avant. \u00ab Paume vers la cuisse \u00bb est la posture debout spontan\u00e9e, celle qu'on se repr\u00e9sente d\u00e8s qu'on cesse de r\u00e9citer la d\u00e9finition ; \u00ab paume en arri\u00e8re \u00bb en est la version pouss\u00e9e d'un cran. Les bras \u00e9cart\u00e9s rel\u00e8vent de l'homme de Vitruve, pas de la position anatomique. L'erreur n'est pas cosm\u00e9tique : le cours pr\u00e9cise que toutes les descriptions se r\u00e9f\u00e8rent \u00e0 cette position, donc une main mal orient\u00e9e fausse ensuite tout ce qui est dit d'ant\u00e9rieur, de post\u00e9rieur, de m\u00e9dial et de lat\u00e9ral.", "slide": 9}, {"id": "q1-03", "q": "\u00c0 quelle condition un plan sagittal est-il un plan m\u00e9dian ?", "choix": ["D\u00e8s qu'il s\u00e9pare une partie droite d'une partie gauche", "Quand il s\u00e9pare une partie sup\u00e9rieure d'une partie inf\u00e9rieure", "Quand il s\u00e9pare une face ant\u00e9rieure d'une face post\u00e9rieure", "Quand il est situ\u00e9 sur la ligne m\u00e9diane et que les deux parties sont sym\u00e9triques et \u00e9gales"], "bonne": 3, "expl": "Le cours r\u00e9serve \u00ab m\u00e9dian \u00bb \u00e0 un cas particulier : sur la ligne m\u00e9diane, avec deux parties sym\u00e9triques et \u00e9gales. La premi\u00e8re option d\u00e9crit n'importe quel plan sagittal \u2014 et c'est exactement la confusion vis\u00e9e : tout plan sagittal s\u00e9pare une droite d'une gauche, sans que les deux moiti\u00e9s soient \u00e9gales. Les deux autres options ne sont pas des inventions : ce sont les divisions des plans voisins, sup\u00e9rieure / inf\u00e9rieure pour le transversal, ant\u00e9rieure / post\u00e9rieure pour le frontal.", "slide": 22, "plan": "sagittal"}, {"id": "q1-04", "q": "Par rapport \u00e0 quel rep\u00e8re le cours d\u00e9finit-il l'abduction et l'adduction ?", "choix": ["Par rapport \u00e0 l'axe du corps", "Par rapport au plan m\u00e9dian", "Par rapport au tronc", "Par rapport \u00e0 l'axe de la main ou du pied"], "bonne": 0, "expl": "Le cours \u00e9crit : mouvement qui \u00e9carte (abduction) ou rapproche (adduction) un membre de l'axe du corps. Les trois autres rep\u00e8res figurent bien dans ce chapitre, mais servent \u00e0 autre chose : le plan m\u00e9dian d\u00e9finit m\u00e9dial et lat\u00e9ral (slide 40), le tronc d\u00e9finit proximal et distal (slide 39), et l'axe de la main (3e doigt) ou du pied (2e orteil) est un rep\u00e8re longitudinal d\u00e9fini pour lui-m\u00eame (slide 13). Savoir lequel s'applique est ce qui s\u00e9pare une d\u00e9finition r\u00e9cit\u00e9e d'une d\u00e9finition comprise.", "slide": 19, "plan": "frontal"}, {"id": "q1-05", "q": "Le bassin part vers l'avant, le dos se creuse. De quel mouvement s'agit-il, et \u00e0 quelle articulation ?", "choix": ["Une ant\u00e9pulsion, \u00e0 l'articulation scapulo-hum\u00e9rale", "Une ant\u00e9version, \u00e0 l'articulation coxo-f\u00e9morale", "Une r\u00e9troversion, \u00e0 l'articulation coxo-f\u00e9morale", "Une ant\u00e9version, \u00e0 l'articulation talo-crurale"], "bonne": 1, "expl": "C'est l'ant\u00e9version, \u00e0 la coxo-f\u00e9morale : le cours associe explicitement \u00ab dos creux \u00bb \u00e0 ce mouvement. L'ant\u00e9pulsion n'en est pas un synonyme malgr\u00e9 la ressemblance des mots : elle se situe \u00e0 la scapulo-hum\u00e9rale et ouvre l'angle bras-tronc \u2014 la proposition est vraie en elle-m\u00eame, elle ne parle simplement pas du bassin. La r\u00e9troversion est le mouvement antagoniste \u00e0 la bonne articulation : elle am\u00e8ne le bassin vers l'arri\u00e8re, \u00ab dos plat \u00bb. La talo-crurale est la cheville, et elle ne porte que la flexion dorsale et la flexion plantaire.", "slide": 27, "plan": "sagittal"}, {"id": "q1-06", "q": "Des deux mouvements de la talo-crurale d\u00e9crits par le cours, lequel correspond \u00e0 une extension du pied ?", "choix": ["La flexion dorsale", "Aucun des deux : ce sont deux flexions, l'une vers le dos du pied, l'autre vers la plante", "La flexion plantaire", "Les deux : au pied, \u00ab flexion \u00bb d\u00e9signe un sens de mouvement et non une fermeture d'angle"], "bonne": 2, "expl": "Le cours est litt\u00e9ral : la flexion plantaire est l'action d'effectuer une extension du pied, la flexion dorsale l'action d'effectuer une flexion. Le pi\u00e8ge tient au nom, qui contient le mot flexion alors que le mouvement ouvre l'angle. \u00ab Aucun des deux \u00bb est la lecture na\u00efve des deux intitul\u00e9s, pr\u00e9cis\u00e9ment celle que la slide contredit ; \u00ab les deux \u00bb est la tentative de sauver cette lecture en red\u00e9finissant le mot flexion, ce que le cours ne fait pas ; \u00ab la flexion dorsale \u00bb est la simple inversion du couple.", "slide": 28, "plan": "sagittal"}, {"id": "q1-07", "q": "Un patient tourne la t\u00eate vers la droite. Quel terme le cours impose-t-il ?", "choix": ["Rotation lat\u00e9rale", "Inclinaison lat\u00e9rale droite", "Rotation m\u00e9diale", "Rotation droite"], "bonne": 3, "expl": "Le cours r\u00e9serve rotation droite et rotation gauche \u00e0 la t\u00eate et au tronc, rotation lat\u00e9rale (externe) et m\u00e9diale (interne) aux membres. \u00ab Rotation lat\u00e9rale \u00bb et \u00ab rotation m\u00e9diale \u00bb sont donc du vocabulaire juste appliqu\u00e9 \u00e0 la mauvaise r\u00e9gion du corps \u2014 et non des termes faux. \u00ab Inclinaison lat\u00e9rale droite \u00bb est l'autre fa\u00e7on de porter la t\u00eate vers la droite, mais elle la penche sur le c\u00f4t\u00e9 dans le plan frontal, alors que la rotation la fait pivoter sur son axe dans le plan transversal.", "slide": 32, "plan": "transversal"}, {"id": "q1-08", "q": "Pendant une supination, quelle est la position du radius ?", "choix": ["Parall\u00e8le \u00e0 l'ulna", "Crois\u00e9 sur l'ulna", "Immobile : c'est l'ulna qui tourne autour de lui"], "bonne": 0, "expl": "En supination \u2014 rotation lat\u00e9rale de l'avant-bras \u2014 le radius est parall\u00e8le \u00e0 l'ulna. Le radius crois\u00e9 sur l'ulna d\u00e9crit la pronation : l'erreur consiste \u00e0 inverser le couple, ce qui est la faute la plus fr\u00e9quente sur cette slide. La troisi\u00e8me option est plus retorse, car elle garde la bonne image du croisement mais attribue le mouvement au mauvais os ; le cours consacre une slide enti\u00e8re \u00e0 l'\u00e9carter (slide 34) : pronation et supination ne d\u00e9signent que des mouvements du radius autour de l'ulna.", "slide": 33, "plan": "transversal"}, {"id": "q1-09", "q": "L'\u00e9piphyse de l'hum\u00e9rus la plus proche de l'\u00e9paule est dite\u2026", "choix": ["Cr\u00e2niale", "Proximale", "Sup\u00e9rieure", "Distale"], "bonne": 1, "expl": "Proximale : sur un membre, le rep\u00e8re est le tronc, et proximal d\u00e9signe ce qui en est le plus proche. \u00ab Cr\u00e2niale \u00bb et \u00ab sup\u00e9rieure \u00bb disent bien l'id\u00e9e \u00ab vers le haut \u00bb \u2014 le cours les donne d'ailleurs comme \u00e9quivalents l'un de l'autre \u2014 mais ce couple concerne essentiellement le tronc, pas les membres. \u00ab Distale \u00bb est l'antonyme exact : c'est l'\u00e9piphyse du c\u00f4t\u00e9 du coude. Le partage \u00e0 retenir : cr\u00e2nial et caudal pour le tronc, proximal et distal pour les membres.", "slide": 39}, {"id": "q1-10", "q": "Dans la jambe, le tibia est l'os m\u00e9dial et la fibula l'os lat\u00e9ral. Sur quel crit\u00e8re ?", "choix": ["Le tibia est plus pr\u00e8s du tronc que la fibula", "Le tibia est plus pr\u00e8s de la surface du corps que la fibula", "Le tibia est plus pr\u00e8s du plan m\u00e9dian que la fibula", "Le tibia est plus pr\u00e8s de l'axe du pied que la fibula"], "bonne": 2, "expl": "M\u00e9dial et lat\u00e9ral se mesurent par rapport au plan m\u00e9dian, et par rapport \u00e0 rien d'autre. Les trois autres crit\u00e8res sont ceux des autres couples du chapitre, appliqu\u00e9s au mauvais endroit : la distance au tronc d\u00e9finit proximal et distal, la distance \u00e0 la surface d\u00e9finit superficiel et profond, et l'axe du pied (2e orteil) est un rep\u00e8re longitudinal du pied. Tibia et fibula \u00e9tant c\u00f4te \u00e0 c\u00f4te sur la m\u00eame portion de membre, seule leur position par rapport au plan m\u00e9dian peut les d\u00e9partager.", "slide": 40}, {"id": "q1-11", "q": "Pour qualifier la face avant du sternum, quel terme le cours privil\u00e9gie-t-il ?", "choix": ["Ventral", "Ant\u00e9rieur", "Palmaire", "Cr\u00e2nial"], "bonne": 0, "expl": "Le sternum appartient au tronc, et le cours pr\u00e9cise que ventral et dorsal sont plus sp\u00e9cifiques pour le tronc, ant\u00e9rieur et post\u00e9rieur pour la t\u00eate et les membres. \u00ab Ant\u00e9rieur \u00bb n'est donc pas faux sur le fond \u2014 le cours donne ant\u00e9rieur et ventral comme \u00e9quivalents \u2014 mais c'est le terme moins sp\u00e9cifique ici, et la slide suivante tranche en l\u00e9gendant \u00ab sternum : os ventral du thorax \u00bb. \u00ab Palmaire \u00bb est bien un synonyme d'ant\u00e9rieur, mais r\u00e9serv\u00e9 \u00e0 la main. \u00ab Cr\u00e2nial \u00bb concerne lui aussi le tronc, mais sur l'autre axe : haut et bas, pas avant et arri\u00e8re.", "slide": 42}, {"id": "q1-12", "q": "Comment le cours situe-t-il la circumduction par rapport aux trois plans ?", "choix": ["Dans le plan transversal, avec la rotation", "Dans le plan frontal, avec l'abduction et l'adduction", "Il ne la range dans aucun des trois : il la pr\u00e9sente \u00e0 part, comme mouvement particulier", "Dans le plan sagittal, avec la flexion et l'extension"], "bonne": 2, "expl": "Le cours ouvre une rubrique distincte, \u00ab mouvement particulier \u00bb, pour la circumduction : le membre y d\u00e9crit un c\u00f4ne dans l'espace. Le plan transversal est le distracteur le plus tentant, parce qu'un c\u00f4ne se trace en tournant et qu'on pense aussit\u00f4t \u00e0 la rotation \u2014 mais la rotation est d\u00e9finie comme le mouvement d'un segment sur un axe, pas comme la description d'un c\u00f4ne. Les deux autres plans tentent pour la raison inverse : chacun porte une paire de mouvements du membre, et on cherche spontan\u00e9ment \u00e0 y caser celui-ci ; le cours, lui, le laisse hors des trois plans.", "slide": 35}], "muscles": [], "pieges": [{"titre": "Le plan sagittal ne coupe pas toujours au milieu", "texte": "Un plan sagittal s\u00e9pare une partie droite d'une partie gauche, sans qu'elles soient forc\u00e9ment \u00e9gales. Ce n'est que lorsqu'il passe par la ligne m\u00e9diane, avec deux parties sym\u00e9triques, qu'on parle de plan sagittal m\u00e9dian.", "slide": 22}, {"titre": "Flexion plantaire est une extension", "texte": "La flexion plantaire du pied correspond anatomiquement \u00e0 une extension. Le mot \u00ab flexion \u00bb dans son nom d\u00e9signe le mouvement vers la plante, pas la fermeture d'un angle.", "slide": 28}, {"titre": "Rotation droite/gauche contre lat\u00e9rale/m\u00e9diale", "texte": "Pour la t\u00eate et le tronc, on dit rotation droite ou gauche. Pour les membres, on dit rotation lat\u00e9rale (externe) ou m\u00e9diale (interne). Employer l'un pour l'autre est une faute de vocabulaire, pas une approximation.", "slide": 32}, {"titre": "Ant\u00e9pulsion n'est pas ant\u00e9version", "texte": "Quatre mots se ressemblent, et deux articulations seulement les portent. Ant\u00e9pulsion et r\u00e9tropulsion se situent \u00e0 la scapulo-hum\u00e9rale : elles ouvrent ou ferment l'angle bras-tronc. Ant\u00e9version et r\u00e9troversion se situent \u00e0 la coxo-f\u00e9morale : elles am\u00e8nent le bassin vers l'avant (\u00ab dos creux \u00bb) ou vers l'arri\u00e8re (\u00ab dos plat \u00bb). Le pr\u00e9fixe ant\u00e9- ou r\u00e9tro- ne dit rien de l'articulation : seule la racine tranche, -pulsion pour l'\u00e9paule, -version pour le bassin.", "slide": 26}, {"titre": "Cr\u00e2nial et proximal ne s'emploient pas sur la m\u00eame r\u00e9gion", "texte": "Les deux couples disent \u00ab vers le haut \u00bb et \u00ab vers le bas \u00bb, mais pas sur la m\u00eame r\u00e9gion du corps. Cr\u00e2nial et caudal concernent essentiellement le tronc, et se rep\u00e8rent sur ses extr\u00e9mit\u00e9s. Proximal et distal concernent essentiellement les membres, et se rep\u00e8rent par rapport au tronc. On ne dit donc pas qu'une \u00e9piphyse d'hum\u00e9rus est cr\u00e2niale, ni qu'un manubrium est proximal. Note le mot \u00ab essentiellement \u00bb employ\u00e9 par le cours : il laisse la porte ouverte \u00e0 des exceptions qu'il ne nomme pas, donc \u00e0 l'examen tiens-t'en au partage tronc / membres.", "slide": 39}, {"titre": "Le support n'accentue pas ces termes de la m\u00eame fa\u00e7on partout", "texte": "Le support n'accentue pas ces termes de la m\u00eame fa\u00e7on d'une slide \u00e0 l'autre : slides 31 et 33, il \u00e9crit \u00ab LATERALE \u00bb et \u00ab MEDIALE \u00bb sans accent ; slides 32 et 40, \u00ab LAT\u00c9RALE \u00bb et \u00ab M\u00c9DIAL \u00bb avec leurs accents ; slide 38, \u00ab CR\u00c2NIAL et CAUDAL \u00bb. La graphie de r\u00e9f\u00e9rence est celle des slides d\u00e9finitionnelles, 38 et 40 : m\u00e9dial, lat\u00e9ral, cr\u00e2nial, caudal. Deux d\u00e9tails co\u00fbtent des points \u00e0 l'\u00e9crit : cr\u00e2nial prend un accent circonflexe, et caudal n'en prend aucun. Les graphies sans accent recopi\u00e9es des slides 31 et 33 sont des coquilles du support, pas des variantes admises.", "slide": 40}]}, {"num": 2, "titre": "Le syst\u00e8me squelettique", "slides": [45, 70], "sections": [{"titre": "Le squelette : deux parties", "slide": 45, "points": ["Le syst\u00e8me squelettique constitue l'ensemble des structures rigides du corps.", "C'est une armature mobile, dont les pi\u00e8ces (les os) servent de leviers pour les tractions des muscles.", "Le squelette est compos\u00e9 de 2 parties : une partie cartilagineuse et une partie osseuse."]}, {"titre": "Pr\u00e9sentation du cartilage", "slide": 48, "points": ["La partie cartilagineuse du squelette est constitu\u00e9e d'un tissu r\u00e9sistant mais \u00e9lastique : le cartilage."]}, {"titre": "Structure et classification du cartilage", "slide": 50, "points": ["Structure : le cartilage est un tissu conjonctif fait de chondrocytes (cellules) et de fibres de collag\u00e8ne, qui donnent aux tissus leur forme et leur \u00e9lasticit\u00e9.", "Il est recouvert d'une membrane conjonctive, le p\u00e9richondre.", "Cartilage hyalin : cartilage articulaire, nacr\u00e9, translucide et \u00e9lastique.", "Cartilage \u00e9lastique : semblable au cartilage hyalin mais renferme plus de fibres \u00e9lastiques.", "Cartilage fibreux (fibro-cartilage) : constitue les disques intervert\u00e9braux et les m\u00e9nisques articulaires ; de couleur blanch\u00e2tre.", "Le cartilage n'est pas vascularis\u00e9."]}, {"titre": "Anatomie fonctionnelle du cartilage", "slide": 52, "points": ["Le cartilage a un r\u00f4le essentiellement m\u00e9canique.", "Il permet le glissement entre 2 pi\u00e8ces osseuses.", "Il prot\u00e8ge de l'usure les surfaces articulaires."]}, {"titre": "L'os : rigidit\u00e9 et \u00e9lasticit\u00e9", "slide": 54, "points": ["La partie osseuse est constitu\u00e9e d'organes vivants et r\u00e9sistants : les os.", "L'os doit sa rigidit\u00e9 \u00e0 ses composants min\u00e9raux (environ 2/3) ; il poss\u00e8de aussi une certaine \u00e9lasticit\u00e9, gr\u00e2ce \u00e0 ses composants organiques (1/3).", "Ces 2 propri\u00e9t\u00e9s sont indispensables \u00e0 la solidit\u00e9 de l'os : si l'os \u00e9tait trop rigide, il serait cassant ; s'il \u00e9tait trop souple, il serait d\u00e9formable."]}, {"titre": "Constitution du squelette : axial et appendiculaire", "slide": 56, "points": ["Le squelette est form\u00e9 du squelette axial, sur lequel se fixe le squelette appendiculaire.", "Le squelette axial comprend : les os de la t\u00eate (cr\u00e2ne et face), la colonne vert\u00e9brale (mobile et fixe), le squelette thoracique (c\u00f4tes et sternum)."]}, {"titre": "Les os de la t\u00eate", "slide": 57, "points": ["Les os de la t\u00eate (21, ou t\u00eate osseuse) sont regroup\u00e9s en os du cr\u00e2ne et os de la face.", "Les os du cr\u00e2ne (8) sont soud\u00e9s entre eux et d\u00e9limitent la bo\u00eete cr\u00e2nienne.", "Les os de la face (13) sont soud\u00e9s entre eux et au cr\u00e2ne, au niveau de la m\u00e2choire sup\u00e9rieure.", "La m\u00e2choire inf\u00e9rieure (mandibule) est le seul os mobile de la t\u00eate."]}, {"titre": "La colonne vert\u00e9brale", "slide": 58, "points": ["La colonne vert\u00e9brale (rachis) est form\u00e9e de 2 parties : la colonne mobile et la colonne fixe.", "La colonne mobile est constitu\u00e9e de 24 vert\u00e8bres ind\u00e9pendantes (\u00ab vraies \u00bb) : 7 cervicales, 12 thoraciques (dorsales), 5 lombaires.", "La colonne fixe est form\u00e9e de vert\u00e8bres soud\u00e9es (\u00ab fausses \u00bb) chez l'adulte, sous forme de deux os : le sacrum et le coccyx."]}, {"titre": "Le squelette thoracique", "slide": 59, "points": ["Le squelette thoracique est constitu\u00e9 de 12 paires de c\u00f4tes + le sternum."]}, {"titre": "Le squelette appendiculaire : membre sup\u00e9rieur", "slide": 60, "points": ["Le squelette appendiculaire comprend les os du membre sup\u00e9rieur et les os du membre inf\u00e9rieur.", "Ceinture scapulaire (en y ajoutant le sternum) : clavicule, scapula (omoplate).", "Partie libre : hum\u00e9rus, radius, ulna (cubitus), les os du carpe, les m\u00e9tacarpes, les phalanges de la main."]}, {"titre": "Le squelette appendiculaire : membre inf\u00e9rieur", "slide": 61, "points": ["Ceinture pelvienne (bassin, pelvis, en y ajoutant le sacrum et le coccyx) : les deux os coxaux.", "Partie libre : f\u00e9mur, tibia, fibula, patella, les os du tarse, les m\u00e9tatarses, les phalanges du pied.", "Fibula : anciennement p\u00e9ron\u00e9. Patella : anciennement rotule."]}, {"titre": "Les types d'os", "slide": 63, "points": ["Le squelette de l'homme adulte comprend 206 os.", "Quatre types d'os : longs, courts, plats, irr\u00e9guliers."]}, {"titre": "L'os long en coupe", "slide": 65, "points": ["Os long : os dont la longueur pr\u00e9domine sur la largeur et l'\u00e9paisseur.", "Une partie centrale : la diaphyse (le canal m\u00e9dullaire se situe \u00e0 l'int\u00e9rieur).", "Deux extr\u00e9mit\u00e9s, les \u00e9piphyses proximale et distale, recouvertes de cartilage hyalin sur les surfaces articulaires.", "La m\u00e9taphyse (cartilage de conjugaison) est la jonction entre diaphyse et \u00e9piphyse.", "L'os est recouvert d'une membrane, le p\u00e9rioste (fibres de collag\u00e8ne, nerfs, vaisseaux sanguins) ; il sert aussi \u00e0 l'insertion des muscles.", "Sous le p\u00e9rioste : l'os compact (tr\u00e8s r\u00e9sistant). Sous l'os compact, au niveau des \u00e9piphyses : l'os spongieux (moins r\u00e9sistant mais plus \u00e9lastique)."]}, {"titre": "Moelle rouge et moelle jaune", "slide": 66, "points": ["Au niveau des tissus spongieux, on trouve la moelle rouge, productrice de sang.", "Chez l'enfant, le canal m\u00e9dullaire contient de l'os spongieux, qui est progressivement remplac\u00e9, avec l'\u00e2ge, par la moelle jaune, form\u00e9e de cellules adipeuses (r\u00e9serve adipeuse pour l'organisme)."]}, {"titre": "Os courts, plats et irr\u00e9guliers", "slide": 67, "points": ["Os courts : les trois dimensions sont presque \u00e9gales (os de la main et du pied).", "Os plats : l'\u00e9paisseur est nettement inf\u00e9rieure aux autres dimensions (ceinture scapulaire et pelvienne, cr\u00e2ne).", "Os irr\u00e9guliers : dimensions irr\u00e9guli\u00e8res (vert\u00e8bres).", "Ces 3 derniers types sont constitu\u00e9s d'une fine couche d'os compact recouverte de p\u00e9rioste, et d'os spongieux \u00e0 l'int\u00e9rieur."]}, {"titre": "Fonctions de l'os", "slide": 69, "points": ["Le maintien du corps lors de la station debout et lors des mouvements (armature mobile).", "La protection de certains organes vitaux : cr\u00e2ne (bo\u00eete cr\u00e2nienne), moelle \u00e9pini\u00e8re (colonne), poumons et c\u0153ur (cage thoracique).", "Le mouvement, en association avec le syst\u00e8me musculaire : l'association des 2 syst\u00e8mes (squelettique et musculaire) forme l'appareil locomoteur.", "C'est \u00e9galement un r\u00e9servoir min\u00e9ral en calcium et phosphore : \u00e9change entre tissus osseux et sang.", "Sa composition et sa forme \u00e9voluent sous l'effet des contraintes r\u00e9p\u00e9t\u00e9es (travail manuel, entra\u00eenement\u2026) et sous l'effet de l'\u00e2ge."]}], "planches": [{"id": "os-long-coupe", "titre": "L'os long en coupe", "vb": "0 0 420 460", "dessin": "<defs><marker id='fleche' viewBox='0 0 10 10' refX='9' refY='5' markerWidth='6' markerHeight='6' orient='auto'><path d='M0 0 L10 5 L0 10 Z' fill='currentColor'/></marker></defs><g class='os-long' fill='none' stroke='currentColor' stroke-width='2'><ellipse cx='170' cy='65' rx='42' ry='32'/><path d='M143 42 Q170 24 197 42' stroke-width='4'/><path d='M138 92 L202 92 L188 122 L152 122 Z'/><path d='M144 124 L144 330' stroke-dasharray='4 3'/><path d='M196 124 L196 330' stroke-dasharray='4 3'/><rect x='150' y='122' width='40' height='210'/><path d='M160 132 L160 322'/><path d='M180 132 L180 322'/><path d='M152 332 L188 332 L202 362 L138 362 Z'/><ellipse cx='170' cy='395' rx='42' ry='32'/><path d='M143 418 Q170 436 197 418' stroke-width='4'/></g><g class='os-spongieux' fill='currentColor' stroke='none'><circle cx='145' cy='55' r='2.2'/><circle cx='155' cy='45' r='2.2'/><circle cx='170' cy='40' r='2.2'/><circle cx='185' cy='45' r='2.2'/><circle cx='195' cy='55' r='2.2'/><circle cx='150' cy='75' r='2.2'/><circle cx='165' cy='80' r='2.2'/><circle cx='175' cy='80' r='2.2'/><circle cx='190' cy='75' r='2.2'/><circle cx='145' cy='385' r='2.2'/><circle cx='155' cy='375' r='2.2'/><circle cx='170' cy='370' r='2.2'/><circle cx='185' cy='375' r='2.2'/><circle cx='195' cy='385' r='2.2'/><circle cx='150' cy='405' r='2.2'/><circle cx='165' cy='410' r='2.2'/><circle cx='175' cy='410' r='2.2'/><circle cx='190' cy='405' r='2.2'/></g><g class='reperes' fill='none' stroke='currentColor' stroke-width='1.5'><path d='M197 42 L222 24' marker-end='url(#fleche)'/><path d='M212 65 L222 73' marker-end='url(#fleche)'/><path d='M144 150 L118 115' marker-end='url(#fleche)'/><path d='M197 107 L222 124' marker-end='url(#fleche)'/><path d='M155 205 L118 205' marker-end='url(#fleche)'/><path d='M170 200 L222 200' marker-end='url(#fleche)'/><path d='M148 390 L118 392' marker-end='url(#fleche)'/><path d='M212 395 L222 393' marker-end='url(#fleche)'/></g>", "pastilles": [{"n": 1, "x": 235, "y": 20, "t": "Cartilage articulaire", "ancre": "start", "indice": "au bout de chaque \u00e9piphyse"}, {"n": 2, "x": 235, "y": 75, "t": "\u00c9piphyse proximale", "ancre": "start", "indice": "extr\u00e9mit\u00e9 proche du tronc"}, {"n": 3, "x": 110, "y": 110, "t": "P\u00e9rioste", "ancre": "end", "indice": "membrane qui enveloppe l'os"}, {"n": 4, "x": 235, "y": 130, "t": "M\u00e9taphyse", "ancre": "start", "indice": "jonction diaphyse / \u00e9piphyse"}, {"n": 5, "x": 110, "y": 200, "t": "Os compact", "ancre": "end", "indice": "juste sous le p\u00e9rioste"}, {"n": 6, "x": 235, "y": 200, "t": "Canal m\u00e9dullaire", "ancre": "start", "indice": "cavit\u00e9 centrale de la diaphyse"}, {"n": 7, "x": 110, "y": 390, "t": "Os spongieux", "ancre": "end", "indice": "sous l'os compact, aux \u00e9piphyses"}, {"n": 8, "x": 235, "y": 395, "t": "\u00c9piphyse distale", "ancre": "start", "indice": "extr\u00e9mit\u00e9 distale, loin du tronc"}], "slide": 66}, {"id": "squelette-axial-appendiculaire", "titre": "Squelette axial et squelette appendiculaire", "vb": "0 0 600 420", "dessin": "<defs><marker id='fleche' viewBox='0 0 10 10' refX='9' refY='5' markerWidth='6' markerHeight='6' orient='auto'><path d='M0 0 L10 5 L0 10 Z' fill='currentColor'/></marker></defs><g class='axial' fill='none' stroke='currentColor' stroke-width='2'><circle cx='300' cy='45' r='22'/><path d='M300 67 L300 90'/><ellipse cx='300' cy='140' rx='40' ry='50'/><path d='M300 95 L300 175' stroke-width='6'/><path d='M300 190 L300 265'/></g><g class='appendiculaire' fill='none' stroke='currentColor' stroke-width='2' stroke-dasharray='5 4'><path d='M265 265 L335 265 L348 298 L252 298 Z'/><path d='M340 95 L385 175'/><path d='M260 95 L215 175'/><path d='M335 298 L375 383'/><path d='M265 298 L225 383'/></g><g class='reperes' fill='none' stroke='currentColor' stroke-width='1.5'><path d='M322 40 L385 26' marker-end='url(#fleche)'/><path d='M340 140 L385 138' marker-end='url(#fleche)'/><path d='M237 135 L210 138' marker-end='url(#fleche)'/><path d='M300 238 L210 240' marker-end='url(#fleche)'/><path d='M245 340 L210 345' marker-end='url(#fleche)'/></g>", "pastilles": [{"n": 1, "x": 405, "y": 25, "t": "Os de la t\u00eate", "ancre": "start", "indice": "cr\u00e2ne + face"}, {"n": 2, "x": 405, "y": 138, "t": "Squelette thoracique", "ancre": "start", "indice": "c\u00f4tes + sternum"}, {"n": 3, "x": 195, "y": 138, "t": "Membre sup\u00e9rieur", "ancre": "end", "indice": "ceinture scapulaire + partie libre"}, {"n": 4, "x": 195, "y": 240, "t": "Colonne vert\u00e9brale", "ancre": "end", "indice": "vert\u00e8bres mobiles puis soud\u00e9es"}, {"n": 5, "x": 195, "y": 345, "t": "Membre inf\u00e9rieur", "ancre": "end", "indice": "ceinture pelvienne + partie libre"}], "slide": 56}], "cartes": [{"id": "c2-01", "q": "Qu'est-ce que le syst\u00e8me squelettique, et en quelles deux parties se divise-t-il ?", "r": "L'ensemble des structures rigides du corps : une armature mobile dont les pi\u00e8ces (les os) servent de leviers pour les tractions des muscles. Il se compose de 2 parties : une partie cartilagineuse et une partie osseuse.", "slide": 45}, {"id": "c2-02", "q": "De quoi le cartilage est-il constitu\u00e9, et par quelle membrane est-il recouvert ?", "r": "Un tissu conjonctif fait de chondrocytes (cellules) et de fibres de collag\u00e8ne (qui donnent aux tissus leur forme et leur \u00e9lasticit\u00e9). Il est recouvert d'une membrane conjonctive, le p\u00e9richondre.", "slide": 50}, {"id": "c2-03", "q": "D\u00e9cris le cartilage hyalin.", "r": "C'est le cartilage articulaire : il est nacr\u00e9, translucide et \u00e9lastique.", "slide": 50}, {"id": "c2-04", "q": "En quoi le cartilage \u00e9lastique diff\u00e8re-t-il du cartilage hyalin ?", "r": "Il lui est semblable, mais renferme plus de fibres \u00e9lastiques.", "slide": 50}, {"id": "c2-05", "q": "O\u00f9 trouve-t-on le cartilage fibreux (fibro-cartilage), et de quelle couleur est-il ?", "r": "Il constitue les disques intervert\u00e9braux et les m\u00e9nisques articulaires. Il est de couleur blanch\u00e2tre.", "slide": 50}, {"id": "c2-06", "q": "Le cartilage est-il vascularis\u00e9 ?", "r": "Non : le cartilage n'est pas vascularis\u00e9.", "slide": 50}, {"id": "c2-07", "q": "Quel est le r\u00f4le du cartilage, et par quels deux effets se manifeste-t-il ?", "r": "Un r\u00f4le essentiellement m\u00e9canique : il permet le glissement entre 2 pi\u00e8ces osseuses et prot\u00e8ge de l'usure les surfaces articulaires.", "slide": 52}, {"id": "c2-08", "q": "\u00c0 quoi l'os doit-il sa rigidit\u00e9, et \u00e0 quoi doit-il son \u00e9lasticit\u00e9 ?", "r": "Sa rigidit\u00e9 \u00e0 ses composants min\u00e9raux (environ 2/3) ; son \u00e9lasticit\u00e9 \u00e0 ses composants organiques (1/3).", "slide": 54}, {"id": "c2-09", "q": "Pourquoi ces deux propri\u00e9t\u00e9s, rigidit\u00e9 et \u00e9lasticit\u00e9, sont-elles indispensables \u00e0 la solidit\u00e9 de l'os ?", "r": "Si l'os \u00e9tait trop rigide, il serait cassant ; s'il \u00e9tait trop souple, il serait d\u00e9formable.", "slide": 54}, {"id": "c2-10", "q": "Sur quoi se fixe le squelette appendiculaire, et que comprend ce dernier ?", "r": "Le squelette appendiculaire se fixe sur le squelette axial. Le squelette axial comprend les os de la t\u00eate (cr\u00e2ne et face), la colonne vert\u00e9brale (mobile et fixe), et le squelette thoracique (c\u00f4tes et sternum).", "slide": 56}, {"id": "c2-11", "q": "Combien d'os comptent la t\u00eate, et comment se r\u00e9partissent-ils entre cr\u00e2ne et face ?", "r": "21 os, regroup\u00e9s en os du cr\u00e2ne (8, soud\u00e9s entre eux, qui d\u00e9limitent la bo\u00eete cr\u00e2nienne) et os de la face (13, soud\u00e9s entre eux et au cr\u00e2ne, au niveau de la m\u00e2choire sup\u00e9rieure).", "slide": 57}, {"id": "c2-12", "q": "Quel est le seul os mobile de la t\u00eate ?", "r": "La m\u00e2choire inf\u00e9rieure, ou mandibule.", "slide": 57}, {"id": "c2-13", "q": "La colonne mobile compte combien de vert\u00e8bres, et comment se r\u00e9partissent-elles ?", "r": "24 vert\u00e8bres ind\u00e9pendantes (\u00ab vraies \u00bb) : 7 cervicales, 12 thoraciques (dorsales), 5 lombaires.", "slide": 58}, {"id": "c2-14", "q": "De quoi la colonne fixe est-elle form\u00e9e chez l'adulte ?", "r": "De vert\u00e8bres soud\u00e9es (\u00ab fausses \u00bb), regroup\u00e9es sous forme de deux os : le sacrum et le coccyx.", "slide": 58}, {"id": "c2-15", "q": "De quoi le squelette thoracique est-il constitu\u00e9 ?", "r": "De 12 paires de c\u00f4tes et du sternum.", "slide": 59}, {"id": "c2-16", "q": "Que comprennent la ceinture scapulaire, puis la partie libre du membre sup\u00e9rieur ?", "r": "Ceinture scapulaire (en y ajoutant le sternum) : clavicule, scapula (omoplate). Partie libre : hum\u00e9rus, radius, ulna (cubitus), les os du carpe, les m\u00e9tacarpes, les phalanges de la main.", "slide": 60}, {"id": "c2-17", "q": "Que comprennent la ceinture pelvienne, puis la partie libre du membre inf\u00e9rieur ?", "r": "Ceinture pelvienne, bassin ou pelvis (en y ajoutant le sacrum et le coccyx) : les deux os coxaux. Partie libre : f\u00e9mur, tibia, fibula, patella, les os du tarse, les m\u00e9tatarses, les phalanges du pied.", "slide": 61}, {"id": "c2-18", "q": "Fibula et patella : quels sont leurs anciens noms ?", "r": "La fibula s'appelait anciennement le p\u00e9ron\u00e9 ; la patella, la rotule.", "slide": 61}, {"id": "c2-19", "q": "Combien d'os compte le squelette de l'homme adulte, et quels sont les quatre types d'os ?", "r": "206 os, r\u00e9partis en quatre types : longs, courts, plats et irr\u00e9guliers.", "slide": 63}, {"id": "c2-20", "q": "D\u00e9cris la constitution d'un os long : partie centrale, extr\u00e9mit\u00e9s, jonction.", "r": "Une partie centrale, la diaphyse (le canal m\u00e9dullaire se situe \u00e0 l'int\u00e9rieur) ; deux extr\u00e9mit\u00e9s, les \u00e9piphyses proximale et distale (recouvertes de cartilage hyalin sur les surfaces articulaires) ; la m\u00e9taphyse (cartilage de conjugaison), jonction entre diaphyse et \u00e9piphyse.", "slide": 65}, {"id": "c2-21", "q": "Que sert aussi le p\u00e9rioste, et que trouve-t-on sous lui, puis sous l'os compact au niveau des \u00e9piphyses ?", "r": "Le p\u00e9rioste est la membrane (fibres de collag\u00e8ne, nerfs, vaisseaux sanguins) qui recouvre l'os ; il sert aussi \u00e0 l'insertion des muscles. Sous le p\u00e9rioste : l'os compact (tr\u00e8s r\u00e9sistant). Sous l'os compact, au niveau des \u00e9piphyses : l'os spongieux (moins r\u00e9sistant mais plus \u00e9lastique).", "slide": 65}, {"id": "c2-22", "q": "Que trouve-t-on au niveau des tissus spongieux, et que devient l'os spongieux du canal m\u00e9dullaire chez l'enfant, avec l'\u00e2ge ?", "r": "La moelle rouge, productrice de sang. Chez l'enfant, l'os spongieux du canal m\u00e9dullaire est progressivement remplac\u00e9, avec l'\u00e2ge, par la moelle jaune, form\u00e9e de cellules adipeuses (r\u00e9serve adipeuse pour l'organisme).", "slide": 66}, {"id": "c2-23", "q": "Caract\u00e9rise les os courts, les os plats et les os irr\u00e9guliers, et dis comment ces trois types sont constitu\u00e9s.", "r": "Os courts : trois dimensions presque \u00e9gales (os de la main et du pied). Os plats : \u00e9paisseur nettement inf\u00e9rieure aux autres dimensions (ceinture scapulaire et pelvienne, cr\u00e2ne). Os irr\u00e9guliers : dimensions irr\u00e9guli\u00e8res (vert\u00e8bres). Ces trois types sont constitu\u00e9s d'une fine couche d'os compact recouverte de p\u00e9rioste, avec de l'os spongieux \u00e0 l'int\u00e9rieur.", "slide": 67}, {"id": "c2-24", "q": "Cite les quatre fonctions de l'os donn\u00e9es par le cours.", "r": "Le maintien du corps (armature mobile) ; la protection d'organes vitaux (cr\u00e2ne, moelle \u00e9pini\u00e8re, poumons et c\u0153ur) ; le mouvement, en association avec le syst\u00e8me musculaire (ensemble : l'appareil locomoteur) ; un r\u00e9servoir min\u00e9ral en calcium et phosphore, \u00e9chang\u00e9 avec le sang.", "slide": 69}], "quiz": [{"id": "q2-01", "q": "Quel type de cartilage est le cartilage articulaire, nacr\u00e9 et translucide ?", "choix": ["Le cartilage hyalin", "Le cartilage \u00e9lastique", "Le cartilage fibreux (fibro-cartilage)"], "bonne": 0, "expl": "Le cartilage hyalin est explicitement d\u00e9fini comme le cartilage articulaire, nacr\u00e9, translucide et \u00e9lastique. Le cartilage \u00e9lastique est tentant : son nom contient \u00ab \u00e9lastique \u00bb et le cours le d\u00e9crit comme \u00ab semblable au cartilage hyalin \u00bb \u2014 mais il s'en distingue justement en renfermant PLUS de fibres \u00e9lastiques, sans \u00eatre qualifi\u00e9 de nacr\u00e9 ni de translucide. Le cartilage fibreux est \u00e9cart\u00e9 par sa couleur (blanch\u00e2tre, pas nacr\u00e9e) et sa localisation (disques intervert\u00e9braux, m\u00e9nisques), qui n'a rien \u00e0 voir avec les surfaces articulaires en g\u00e9n\u00e9ral.", "slide": 50}, {"id": "q2-02", "q": "Quel cartilage constitue les disques intervert\u00e9braux et les m\u00e9nisques articulaires ?", "choix": ["Le cartilage hyalin", "Le cartilage \u00e9lastique", "Le cartilage fibreux (fibro-cartilage)"], "bonne": 2, "expl": "Le fibro-cartilage est d\u00e9fini par cette localisation pr\u00e9cise et sa couleur blanch\u00e2tre. Le cartilage hyalin est le distracteur le plus proche : lui aussi est dit \u00ab articulaire \u00bb, mais ce mot d\u00e9signe chez lui le rev\u00eatement des surfaces des \u00e9piphyses, pas les disques ou les m\u00e9nisques. Le cartilage \u00e9lastique est \u00e9cart\u00e9 car le cours ne lui attribue aucune localisation pr\u00e9cise : il est seulement d\u00e9crit comme \u00ab semblable au hyalin, avec plus de fibres \u00e9lastiques \u00bb.", "slide": 50}, {"id": "q2-03", "q": "L'os doit sa rigidit\u00e9 \u00e0 quels composants, et son \u00e9lasticit\u00e9 \u00e0 quels autres ?", "choix": ["Rigidit\u00e9 aux composants organiques, \u00e9lasticit\u00e9 aux composants min\u00e9raux", "Rigidit\u00e9 aux composants min\u00e9raux, \u00e9lasticit\u00e9 aux composants organiques", "Rigidit\u00e9 et \u00e9lasticit\u00e9 proviennent toutes deux des composants min\u00e9raux"], "bonne": 1, "expl": "Le cours est explicite : rigidit\u00e9 par les composants min\u00e9raux (environ 2/3), \u00e9lasticit\u00e9 par les composants organiques (1/3). La premi\u00e8re option inverse exactement ce couple \u2014 l'erreur la plus fr\u00e9quente sur cette slide. La troisi\u00e8me option nie la dualit\u00e9 que le cours souligne lui-m\u00eame en expliquant pourquoi les deux propri\u00e9t\u00e9s, venant de deux composants diff\u00e9rents, sont n\u00e9cessaires (sinon l'os serait cassant ou d\u00e9formable).", "slide": 54}, {"id": "q2-04", "q": "Combien d'os composent le cr\u00e2ne (au sens strict, hors face), et que d\u00e9limitent-ils ?", "choix": ["8 os, qui d\u00e9limitent la bo\u00eete cr\u00e2nienne", "13 os, qui d\u00e9limitent la bo\u00eete cr\u00e2nienne", "21 os, qui d\u00e9limitent la bo\u00eete cr\u00e2nienne", "8 os, qui forment la m\u00e2choire sup\u00e9rieure"], "bonne": 0, "expl": "Les 8 os du cr\u00e2ne, soud\u00e9s entre eux, d\u00e9limitent la bo\u00eete cr\u00e2nienne. 13 est le nombre des os de la FACE, pas du cr\u00e2ne : c'est la confusion cr\u00e2ne/face que cette slide invite \u00e0 faire. 21 est le total de la t\u00eate osseuse (cr\u00e2ne + face), pas le cr\u00e2ne seul. \u00ab Former la m\u00e2choire sup\u00e9rieure \u00bb est une fonction des os de la face (soud\u00e9s au cr\u00e2ne \u00e0 ce niveau), pas des os du cr\u00e2ne.", "slide": 57}, {"id": "q2-05", "q": "Quel est le seul os mobile de la t\u00eate ?", "choix": ["Un os du cr\u00e2ne, au niveau d'une suture", "La mandibule (m\u00e2choire inf\u00e9rieure)", "Le maxillaire (m\u00e2choire sup\u00e9rieure)", "Aucun : tous les os de la t\u00eate sont soud\u00e9s"], "bonne": 1, "expl": "Le cours l'affirme sans d\u00e9tour : la mandibule est le seul os mobile de la t\u00eate. Le maxillaire (m\u00e2choire sup\u00e9rieure) est le distracteur le plus tentant par confusion m\u00e2choire haute / m\u00e2choire basse \u2014 mais c'est un os de la face, soud\u00e9 aux autres et au cr\u00e2ne. \u00ab Aucun \u00bb g\u00e9n\u00e9ralise \u00e0 l'exc\u00e8s la soudure des os du cr\u00e2ne et de la face \u00e0 la t\u00eate enti\u00e8re, alors que la mandibule est l'exception nomm\u00e9e. Une suture cr\u00e2nienne est une vraie articulation du cr\u00e2ne, mais elle est fixe, pas mobile.", "slide": 57}, {"id": "q2-06", "q": "Combien de vert\u00e8bres compte la colonne mobile, et comment se r\u00e9partissent-elles ?", "choix": ["24 : 7 cervicales, 12 thoraciques, 5 lombaires", "26 : 7 cervicales, 12 thoraciques, 5 lombaires, sacrum et coccyx compt\u00e9s s\u00e9par\u00e9ment", "33 : l'ensemble des vert\u00e8bres de la colonne, mobiles et fixes confondues", "24 : 12 cervicales, 7 thoraciques, 5 lombaires"], "bonne": 0, "expl": "24 vert\u00e8bres \u00ab vraies \u00bb, ind\u00e9pendantes : 7 cervicales, 12 thoraciques, 5 lombaires. 33 est le pi\u00e8ge classique : il recompte la colonne fixe comme si elle ajoutait des vert\u00e8bres ind\u00e9pendantes, alors qu'elle est faite de vert\u00e8bres SOUD\u00c9ES en 2 os (sacrum, coccyx), plus des vert\u00e8bres \u00e0 part enti\u00e8re. 26 fait la m\u00eame erreur \u00e0 plus petite \u00e9chelle. L'inversion cervicales/thoraciques (12 contre 7) teste seulement la m\u00e9morisation exacte des chiffres.", "slide": 58}, {"id": "q2-07", "q": "Un os du carpe appartient \u00e0 quel type d'os ?", "choix": ["Os long", "Os court", "Os plat", "Os irr\u00e9gulier"], "bonne": 1, "expl": "Le cours donne explicitement les os courts en exemple : les os de la main (dont le carpe) et du pied, dont les trois dimensions sont presque \u00e9gales. Os long est le distracteur le plus tentant, car c'est le type le plus connu \u2014 mais rien dans un os du carpe n'est longiligne. Os plat (exemple donn\u00e9 : le pari\u00e9tal) et os irr\u00e9gulier (exemple donn\u00e9 : la vert\u00e8bre) sont les deux autres types nomm\u00e9ment illustr\u00e9s par d'autres os du cours, pas par le carpe.", "slide": 64}, {"id": "q2-08", "q": "Dans un os long, quelle structure assure la jonction entre la diaphyse et l'\u00e9piphyse ?", "choix": ["Le p\u00e9rioste", "La m\u00e9taphyse", "Le canal m\u00e9dullaire", "L'os spongieux"], "bonne": 1, "expl": "La m\u00e9taphyse (cartilage de conjugaison) est d\u00e9finie par le cours comme la jonction entre diaphyse et \u00e9piphyse. Le p\u00e9rioste est la membrane qui recouvre TOUT l'os, pas une jonction interne. Le canal m\u00e9dullaire est la cavit\u00e9 int\u00e9rieure de la diaphyse, pas une zone de transition. L'os spongieux est le tissu situ\u00e9 sous l'os compact, au niveau des \u00e9piphyses. Les trois distracteurs sont les voisins imm\u00e9diats de la m\u00e9taphyse sur la m\u00eame figure \u2014 choisis pour leur proximit\u00e9 anatomique r\u00e9elle, pas invent\u00e9s.", "slide": 65}, {"id": "q2-09", "q": "Sous l'os compact, au niveau des \u00e9piphyses d'un os long, quel tissu trouve-t-on ?", "choix": ["Le p\u00e9rioste", "La m\u00e9taphyse", "L'os spongieux", "Le canal m\u00e9dullaire"], "bonne": 2, "expl": "Le cours l'\u00e9nonce directement : sous l'os compact, au niveau des \u00e9piphyses, on trouve l'os spongieux. Le p\u00e9rioste est au contraire la couche la plus externe, au-dessus de l'os compact, pas dessous. La m\u00e9taphyse est une zone de jonction diaphyse/\u00e9piphyse, pas un tissu sous-jacent \u00e0 l'os compact. Le canal m\u00e9dullaire est la cavit\u00e9 de la diaphyse, pas des \u00e9piphyses.", "slide": 65}, {"id": "q2-10", "q": "Chez l'enfant, l'os spongieux du canal m\u00e9dullaire est progressivement remplac\u00e9, avec l'\u00e2ge, par quoi ?", "choix": ["La moelle rouge, productrice de sang", "La moelle jaune, form\u00e9e de cellules adipeuses", "Du cartilage hyalin", "De l'os compact"], "bonne": 1, "expl": "Le cours l'affirme directement : remplacement progressif par la moelle jaune, form\u00e9e de cellules adipeuses. La moelle rouge est le distracteur le plus proche : elle est bien nomm\u00e9e dans le m\u00eame paragraphe, mais elle est d\u00e9j\u00e0 pr\u00e9sente DANS le tissu spongieux, ce n'est pas ce qui le remplace \u2014 c'est l'inverse qui se produit avec l'\u00e2ge. Le cartilage hyalin et l'os compact sont des tissus r\u00e9els du cours, mais situ\u00e9s ailleurs (surfaces articulaires ; paroi de la diaphyse), sans lien avec cette transformation li\u00e9e \u00e0 l'\u00e2ge.", "slide": 66}, {"id": "q2-11", "q": "Fibula et patella sont les noms actuels de quels anciens termes ?", "choix": ["Fibula = radius ancien ; patella = rotule ancienne", "Fibula = p\u00e9ron\u00e9 ancien ; patella = rotule ancienne", "Fibula = tibia ancien ; patella = m\u00e9nisque ancien", "Fibula = p\u00e9ron\u00e9 ancien ; patella = m\u00e9nisque ancien"], "bonne": 1, "expl": "Le cours l'\u00e9nonce sans ambigu\u00eft\u00e9 : fibula, anciennement p\u00e9ron\u00e9 ; patella, anciennement rotule. Le tibia et le radius sont des os bien r\u00e9els et voisins de la fibula ou de la main/avant-bras, mais ce ne sont pas d'anciens noms de la fibula. Le m\u00e9nisque est une structure r\u00e9elle du cours (le fibro-cartilage en forme les m\u00e9nisques articulaires), mais ce n'est pas un ancien nom de la patella : c'est une pi\u00e8ce anatomiquement distincte, log\u00e9e dans l'articulation du genou \u00e0 c\u00f4t\u00e9 d'elle.", "slide": 61}], "muscles": [], "pieges": [{"titre": "Le cartilage n'est pas vascularis\u00e9", "texte": "Le cours l'affirme sans nuance, juste apr\u00e8s avoir d\u00e9crit les trois types de cartilage. Contrairement \u00e0 l'os, qui est un organe vivant travers\u00e9 de vaisseaux sanguins (p\u00e9rioste, canal m\u00e9dullaire), le cartilage ne l'est pas : c'est pourquoi il cicatrise mal et se r\u00e9pare lentement.", "slide": 50}, {"titre": "La mandibule est le SEUL os mobile de la t\u00eate", "texte": "Les os du cr\u00e2ne sont soud\u00e9s entre eux ; les os de la face sont soud\u00e9s entre eux et au cr\u00e2ne, au niveau de la m\u00e2choire sup\u00e9rieure. Sur les 21 os de la t\u00eate, un seul \u00e9chappe \u00e0 cette r\u00e8gle : la mandibule (m\u00e2choire inf\u00e9rieure). Le maxillaire (m\u00e2choire sup\u00e9rieure), lui, est soud\u00e9 comme les autres os de la face.", "slide": 57}, {"titre": "La colonne \u00ab fixe \u00bb est quand m\u00eame faite de vert\u00e8bres", "texte": "\u00ab Fixe \u00bb ne veut pas dire \u00ab sans vert\u00e8bres \u00bb : la colonne fixe est form\u00e9e de vert\u00e8bres, mais soud\u00e9es (\u00ab fausses \u00bb), regroup\u00e9es chez l'adulte en deux os, le sacrum et le coccyx. Seule la colonne mobile compte des vert\u00e8bres ind\u00e9pendantes (\u00ab vraies \u00bb), au nombre de 24.", "slide": 58}, {"titre": "Rigidit\u00e9 vient du min\u00e9ral, \u00e9lasticit\u00e9 vient de l'organique", "texte": "Le couple se retient dans ce sens pr\u00e9cis et se confond facilement \u00e0 l'envers : l'os doit sa rigidit\u00e9 \u00e0 ses composants MIN\u00c9RAUX (environ 2/3), et son \u00e9lasticit\u00e9 \u00e0 ses composants ORGANIQUES (1/3). Les deux sont indispensables : un os trop rigide serait cassant, un os trop souple serait d\u00e9formable.", "slide": 54}]}, {"num": 3, "titre": "Le syst\u00e8me articulaire", "slides": [72, 109], "sections": [{"titre": "L'articulation : d\u00e9finition et r\u00f4le", "slide": 73, "points": ["Une articulation est le moyen d'union entre 2 ou plusieurs pi\u00e8ces du squelette entre elles. Les os s'unissent entre eux par ces zones, plus ou moins mobiles.", "En raison de leur r\u00f4le important en biom\u00e9canique, l'atteinte pathologique (arthrite, arthrose) ou traumatique (luxation, entorse) d'une articulation peut compromettre les postures et les mouvements, donc la performance.", "L'\u00e9tude des articulations est l'arthrologie."]}, {"titre": "Classification g\u00e9n\u00e9rale : simples/compos\u00e9es, fibreuses, cartilagineuses", "slide": 75, "points": ["Les articulations simples unissent deux \u00e9l\u00e9ments ; les articulations compos\u00e9es en unissent plus de deux.", "Les articulations fibreuses (synarthroses) : l'interzone articulaire est occup\u00e9e par du tissu fibreux. Sans mobilit\u00e9 et sans cartilage articulaire (ex : la suture des os de la t\u00eate).", "Les articulations cartilagineuses (amphiarthroses) : l'interzone est occup\u00e9e par du fibrocartilage. Mobilit\u00e9 r\u00e9duite, un cartilage articulaire, mais d\u00e9pourvues de cavit\u00e9 articulaire (ex : la symphyse pubienne)."]}, {"titre": "Les articulations synoviales (diarthroses)", "slide": 77, "points": ["Elles pr\u00e9sentent des surfaces articulaires de forme variable, encro\u00fbt\u00e9es de cartilage hyalin ; une cavit\u00e9 articulaire ; une capsule articulaire constitu\u00e9e de deux membranes (une fibreuse, une synoviale).", "Elles sont particuli\u00e8rement mobiles."]}, {"titre": "Les 7 types de diarthroses", "slide": 79, "points": ["Il existe 7 types de diarthroses, class\u00e9s en fonction de la forme de leurs surfaces articulaires."]}, {"titre": "A. Les sph\u00e9ro\u00efdes (\u00e9narthroses)", "slide": 81, "points": ["Une sph\u00e8re pleine (convexe) s'embo\u00eete dans une sph\u00e8re creuse (concave).", "Ces articulations permettent des mouvements dans toutes les directions (3 axes).", "Exemple : la hanche."]}, {"titre": "B. Les ellipso\u00efdes (condyliennes)", "slide": 84, "points": ["Une ellipse convexe s'embo\u00eete dans une ellipse concave.", "Elles poss\u00e8dent 2 axes principaux de mouvement : flexion/extension, abduction/adduction."]}, {"titre": "C. Les articulations en selle", "slide": 86, "points": ["Une surface \u00ab en selle \u00bb, concave dans un sens et convexe dans l'autre, correspond \u00e0 une surface inversement conform\u00e9e.", "Elles poss\u00e8dent 2 axes principaux de mouvement : flexion/extension, abduction/adduction.", "Exemple : l'articulation sterno-claviculaire."]}, {"titre": "D. La ginglyme (trochl\u00e9enne)", "slide": 88, "points": ["Une trochl\u00e9e s'embo\u00eete dans une cochl\u00e9e, formant ainsi une charni\u00e8re.", "Elle poss\u00e8de 1 axe principal de mouvement : flexion-extension.", "Exemple : l'articulation hum\u00e9ro-ulnaire."]}, {"titre": "E. Les trocho\u00efdes", "slide": 90, "points": ["Un cylindre convexe s'embo\u00eete dans un cylindre concave.", "Elle poss\u00e8de 1 axe de mouvement : pronation-supination (mouvement de rotation).", "Exemple : l'articulation radio-ulnaire proximale."]}, {"titre": "F. La bicondylienne", "slide": 92, "points": ["Une paire de condyles convexes vient s'opposer \u00e0 une paire de condyles quasi plane.", "1 axe principal de mouvement : flexion/extension.", "Exemple : l'articulation tibio-f\u00e9morale."]}, {"titre": "G. Les articulations planes (arthrodies)", "slide": 94, "points": ["Deux surfaces planes s'opposent.", "Mouvement de glissement uniquement.", "Exemple : le carpe."]}, {"titre": "Structures de protection : la capsule articulaire", "slide": 97, "points": ["La capsule articulaire est compos\u00e9e de deux membranes.", "La membrane fibreuse : un manchon fibreux tr\u00e8s r\u00e9sistant et peu \u00e9lastique, prolongement du p\u00e9rioste.", "La membrane synoviale : une membrane conjonctive mince et transparente, qui adh\u00e8re \u00e0 la face profonde de la membrane fibreuse. Elle recouvre les parties osseuses, les tendons et les ligaments intracapsulaires, et s\u00e9cr\u00e8te le liquide synovial."]}, {"titre": "Structures d'amortissement des pressions : cartilage et synovie", "slide": 99, "points": ["Le cartilage articulaire est un cartilage hyalin qui prot\u00e8ge les surfaces articulaires contre l'usure. Son \u00e9paisseur est proportionnelle \u00e0 la pression subie ; il est d\u00e9formable (jusqu'\u00e0 50 %) et augmente d'\u00e9paisseur avec la mobilisation dynamique.", "Il se nourrit par imbibition du liquide synovial (pompage favoris\u00e9 par le mouvement). Une fois d\u00e9truit, le cartilage ne se r\u00e9g\u00e9n\u00e8re pas (pas de nerf ni de vaisseau).", "La synovie est un liquide transparent et visqueux. Elle lubrifie et absorbe les chocs de l'articulation ; elle nourrit le cartilage (O2 et nutriments) et \u00e9limine les d\u00e9chets.", "\u00c0 froid ou \u00e0 l'immobilit\u00e9, la synovie reste tr\u00e8s visqueuse ; sa s\u00e9cr\u00e9tion est stimul\u00e9e par le mouvement."]}, {"titre": "Structures d'adaptation des surfaces : le m\u00e9nisque", "slide": 102, "points": ["Le m\u00e9nisque est un anneau de fibrocartilage, avec deux faces libres et une face adh\u00e9rente \u00e0 la capsule articulaire.", "Il assure la stabilit\u00e9 des surfaces articulaires en pr\u00e9sence."]}, {"titre": "Structures de maintien", "slide": 104, "points": ["Elles s'opposent \u00e0 la dislocation de l'articulation. Leurs \u00e9longations et leurs ruptures sont responsables des entorses.", "La membrane fibreuse de la capsule articulaire constitue un des moyens d'union les plus importants.", "Les ligaments sont des lames fibreuses unissant les pi\u00e8ces constitutives d'une articulation. On distingue les ligaments intracapsulaires (ex : les crois\u00e9s du genou) des ligaments extracapsulaires (ex : les lat\u00e9raux du genou).", "Les tendons musculaires jouent aussi un r\u00f4le de contention tr\u00e8s important. L'atrophie des structures de maintien favorise les instabilit\u00e9s et les blessures."]}, {"titre": "Structures de glissement", "slide": 106, "points": ["Le cartilage articulaire, gr\u00e2ce \u00e0 sa surface exceptionnellement lisse, r\u00e9duit le coefficient de friction articulaire.", "La synovie joue le r\u00f4le d'un lubrifiant, qui gomme les asp\u00e9rit\u00e9s des cartilages."]}, {"titre": "Adaptation fonctionnelle des articulations", "slide": 108, "points": ["Les articulations s'adaptent aux conditions m\u00e9caniques impos\u00e9es par l'activit\u00e9 musculaire : l'absence d'activit\u00e9 musculaire entra\u00eene le blocage progressif de l'articulation.", "Une mobilisation pouss\u00e9e jusqu'aux limites physiologiques cr\u00e9e une hyperlaxit\u00e9 articulaire, voire une luxation.", "La mobilit\u00e9 articulaire varie en fonction de l'\u00e2ge, du sexe (la femme et l'enfant ont une souplesse plus grande que l'homme) et de la pratique sportive.", "L'\u00e9chauffement sportif des articulations concern\u00e9es par l'activit\u00e9 est indispensable."]}], "planches": [{"id": "articulation-synoviale-coupe", "titre": "L'articulation synoviale type, en coupe", "vb": "0 0 620 460", "dessin": "<rect x='260' y='20' width='40' height='150' fill='none' stroke='currentColor' stroke-width='2'/><path d='M248,178 Q280,215 312,178' fill='none' stroke='currentColor' stroke-width='4'/><rect x='260' y='290' width='40' height='150' fill='none' stroke='currentColor' stroke-width='2'/><path d='M248,282 Q280,245 312,282' fill='none' stroke='currentColor' stroke-width='4'/><path d='M230,196 Q223,230 230,264 Q250,240 262,230 Q250,220 230,196 Z' fill='none' stroke='currentColor' stroke-width='2'/><path d='M260,150 Q205,225 260,300' fill='none' stroke='currentColor' stroke-width='1.6' stroke-dasharray='6 4'/><path d='M300,150 Q355,225 300,300' fill='none' stroke='currentColor' stroke-width='1.6' stroke-dasharray='6 4'/><path d='M260,158 Q222,225 260,292' fill='none' stroke='currentColor' stroke-width='1.2' stroke-dasharray='3 3'/><path d='M300,158 Q338,225 300,292' fill='none' stroke='currentColor' stroke-width='1.2' stroke-dasharray='3 3'/><path d='M300,120 Q385,225 300,330' fill='none' stroke='currentColor' stroke-width='3'/><defs><marker id='fleche' viewBox='0 0 10 10' refX='9' refY='5' markerWidth='6' markerHeight='6' orient='auto'><path d='M0 0 L10 5 L0 10 Z' fill='currentColor'/></marker></defs><g class='reperes' fill='none' stroke='currentColor' stroke-width='1.2'><path d='M245,165 L188,150' marker-end='url(#fleche)'/><path d='M234,230 L188,230' marker-end='url(#fleche)'/><path d='M254,268 L188,318' marker-end='url(#fleche)'/><path d='M303,182 L372,150' marker-end='url(#fleche)'/><path d='M290,228 L372,230' marker-end='url(#fleche)'/><path d='M328,232 L372,318' marker-end='url(#fleche)'/></g>", "pastilles": [{"n": 1, "x": 170, "y": 150, "t": "Membrane fibreuse", "ancre": "end", "indice": "couche externe de la capsule, r\u00e9sistante, peu \u00e9lastique"}, {"n": 2, "x": 170, "y": 230, "t": "M\u00e9nisque", "ancre": "end", "indice": "coin de fibrocartilage, adh\u00e9rent \u00e0 la capsule"}, {"n": 3, "x": 170, "y": 320, "t": "Membrane synoviale", "ancre": "end", "indice": "couche interne de la capsule, s\u00e9cr\u00e8te le liquide synovial"}, {"n": 4, "x": 390, "y": 150, "t": "Cartilage articulaire", "ancre": "start", "indice": "coiffe l'extr\u00e9mit\u00e9 de chaque os"}, {"n": 5, "x": 390, "y": 230, "t": "Cavit\u00e9 articulaire", "ancre": "start", "indice": "espace entre les deux surfaces, o\u00f9 loge le liquide synovial"}, {"n": 6, "x": 390, "y": 320, "t": "Ligament", "ancre": "start", "indice": "hors de la capsule, relie les deux os"}], "slide": 102}, {"id": "diarthrose-spheroide", "titre": "La sph\u00e9ro\u00efde (\u00e9narthrose)", "vb": "0 0 220 345", "dessin": "<path d='M88.8,91.7 A62,62 0 1,0 131.2,91.7' fill='none' stroke='currentColor' stroke-width='2.2'/><circle cx='110' cy='150' r='40' fill='none' stroke='currentColor' stroke-width='2.2'/><path d='M110,110 L110,55' fill='none' stroke='currentColor' stroke-width='2.2'/><path d='M90,35 L130,35 L130,55 L90,55 Z' fill='none' stroke='currentColor' stroke-width='2.2'/>", "pastilles": [{"n": 1, "x": 110, "y": 245, "t": "Sph\u00e9ro\u00efde (\u00e9narthrose)", "ancre": "middle", "indice": "sph\u00e8re pleine dans une sph\u00e8re creuse"}, {"n": 2, "x": 110, "y": 278, "t": "3 axes : tous les mouvements", "ancre": "middle"}, {"n": 3, "x": 110, "y": 311, "t": "Ex : la hanche", "ancre": "middle"}], "slide": 81}, {"id": "diarthrose-ellipsoide", "titre": "L'ellipso\u00efde (condylienne)", "vb": "0 0 220 345", "dessin": "<path d='M85.4,101.1 A72,52 0 1,0 134.6,101.1' fill='none' stroke='currentColor' stroke-width='2.2'/><ellipse cx='110' cy='150' rx='46' ry='30' fill='none' stroke='currentColor' stroke-width='2.2'/><path d='M110,120 L110,55' fill='none' stroke='currentColor' stroke-width='2.2'/><path d='M90,35 L130,35 L130,55 L90,55 Z' fill='none' stroke='currentColor' stroke-width='2.2'/>", "pastilles": [{"n": 1, "x": 110, "y": 245, "t": "Ellipso\u00efde (condylienne)", "ancre": "middle", "indice": "ellipse convexe dans une ellipse concave"}, {"n": 2, "x": 110, "y": 278, "t": "Flexion, extension", "ancre": "middle"}, {"n": 3, "x": 110, "y": 311, "t": "Abduction, adduction", "ancre": "middle"}], "slide": 84}, {"id": "diarthrose-selle", "titre": "L'articulation en selle", "vb": "0 0 220 380", "dessin": "<path d='M50,120 Q80,90 110,120 Q140,150 170,120' fill='none' stroke='currentColor' stroke-width='2.2'/><path d='M50,132 Q80,102 110,132 Q140,162 170,132' fill='none' stroke='currentColor' stroke-width='2.2'/><path d='M80,90 L80,45' fill='none' stroke='currentColor' stroke-width='2.2'/><path d='M60,25 L100,25 L100,45 L60,45 Z' fill='none' stroke='currentColor' stroke-width='2.2'/><path d='M140,162 L140,205' fill='none' stroke='currentColor' stroke-width='2.2'/><path d='M120,205 L160,205 L160,225 L120,225 Z' fill='none' stroke='currentColor' stroke-width='2.2'/>", "pastilles": [{"n": 1, "x": 110, "y": 235, "t": "Articulation en selle", "ancre": "middle", "indice": "surface concave dans un sens, convexe dans l'autre"}, {"n": 2, "x": 110, "y": 268, "t": "Flexion, extension", "ancre": "middle"}, {"n": 3, "x": 110, "y": 301, "t": "Abduction, adduction", "ancre": "middle"}, {"n": 4, "x": 110, "y": 334, "t": "Ex : sterno-claviculaire", "ancre": "middle"}], "slide": 86}, {"id": "diarthrose-ginglyme", "titre": "La ginglyme (trochl\u00e9enne)", "vb": "0 0 220 345", "dessin": "<defs><marker id='fleche' viewBox='0 0 10 10' refX='9' refY='5' markerWidth='6' markerHeight='6' orient='auto'><path d='M0 0 L10 5 L0 10 Z' fill='currentColor'/></marker></defs><path d='M95,35 L95,92' fill='none' stroke='currentColor' stroke-width='2.2'/><path d='M55,92 L135,92' fill='none' stroke='currentColor' stroke-width='2.2'/><circle cx='95' cy='100' r='9' fill='none' stroke='currentColor' stroke-width='2.2'/><path d='M55,108 L135,108' fill='none' stroke='currentColor' stroke-width='2.2'/><path d='M95,108 L95,195' fill='none' stroke='currentColor' stroke-width='2.2'/><path d='M187.5,120.6 A32,32 0 1,1 138.5,120.6' fill='none' stroke='currentColor' stroke-width='1.8' marker-end='url(#fleche)'/>", "pastilles": [{"n": 1, "x": 110, "y": 245, "t": "Ginglyme (trochl\u00e9enne)", "ancre": "middle", "indice": "une trochl\u00e9e s'embo\u00eete dans une cochl\u00e9e : une charni\u00e8re"}, {"n": 2, "x": 110, "y": 278, "t": "1 axe : flexion-extension", "ancre": "middle"}, {"n": 3, "x": 110, "y": 311, "t": "Ex : hum\u00e9ro-ulnaire", "ancre": "middle"}], "slide": 88}, {"id": "diarthrose-trochoide", "titre": "La trocho\u00efde", "vb": "0 0 220 345", "dessin": "<defs><marker id='fleche' viewBox='0 0 10 10' refX='9' refY='5' markerWidth='6' markerHeight='6' orient='auto'><path d='M0 0 L10 5 L0 10 Z' fill='currentColor'/></marker></defs><path d='M110,30 L110,210' fill='none' stroke='currentColor' stroke-width='2.6'/><ellipse cx='110' cy='115' rx='46' ry='20' fill='none' stroke='currentColor' stroke-width='2.2'/><path d='M157.5,97.0 A62,28 0 0,1 157.5,133.0' fill='none' stroke='currentColor' stroke-width='1.8' marker-end='url(#fleche)'/><path d='M62.5,97.0 A62,28 0 0,0 62.5,133.0' fill='none' stroke='currentColor' stroke-width='1.8' marker-end='url(#fleche)'/>", "pastilles": [{"n": 1, "x": 110, "y": 245, "t": "Trocho\u00efde", "ancre": "middle", "indice": "cylindre convexe dans un cylindre concave"}, {"n": 2, "x": 110, "y": 278, "t": "1 axe : pronation-supination", "ancre": "middle"}, {"n": 3, "x": 110, "y": 311, "t": "Ex : radio-ulnaire proximale", "ancre": "middle"}], "slide": 90}, {"id": "diarthrose-bicondylienne", "titre": "La bicondylienne", "vb": "0 0 220 345", "dessin": "<path d='M110,25 L110,70' fill='none' stroke='currentColor' stroke-width='2.2'/><path d='M110,70 L78,95' fill='none' stroke='currentColor' stroke-width='2.2'/><path d='M110,70 L142,95' fill='none' stroke='currentColor' stroke-width='2.2'/><circle cx='78' cy='120' r='26' fill='none' stroke='currentColor' stroke-width='2.2'/><circle cx='142' cy='120' r='26' fill='none' stroke='currentColor' stroke-width='2.2'/><path d='M40,168 A300,300 0 0,0 180,168' fill='none' stroke='currentColor' stroke-width='2.2'/><path d='M110,168 L110,210' fill='none' stroke='currentColor' stroke-width='2.2'/>", "pastilles": [{"n": 1, "x": 110, "y": 245, "t": "Bicondylienne", "ancre": "middle", "indice": "une paire de condyles convexes sur une surface plane"}, {"n": 2, "x": 110, "y": 278, "t": "1 axe : flexion/extension", "ancre": "middle"}, {"n": 3, "x": 110, "y": 311, "t": "Ex : tibio-f\u00e9morale", "ancre": "middle"}], "slide": 92}, {"id": "diarthrose-plane", "titre": "L'articulation plane (arthrodie)", "vb": "0 0 220 345", "dessin": "<defs><marker id='fleche' viewBox='0 0 10 10' refX='9' refY='5' markerWidth='6' markerHeight='6' orient='auto'><path d='M0 0 L10 5 L0 10 Z' fill='currentColor'/></marker></defs><path d='M110,30 L110,92' fill='none' stroke='currentColor' stroke-width='2.2'/><path d='M50,92 L170,92' fill='none' stroke='currentColor' stroke-width='2.4'/><path d='M50,112 L170,112' fill='none' stroke='currentColor' stroke-width='2.4'/><path d='M110,112 L110,205' fill='none' stroke='currentColor' stroke-width='2.2'/><path d='M45,102 L175,102' fill='none' stroke='currentColor' stroke-width='1.8' marker-start='url(#fleche)' marker-end='url(#fleche)'/>", "pastilles": [{"n": 1, "x": 110, "y": 245, "t": "Articulation plane (arthrodie)", "ancre": "middle", "indice": "deux surfaces planes qui s'opposent"}, {"n": 2, "x": 110, "y": 278, "t": "Glissement uniquement", "ancre": "middle"}, {"n": 3, "x": 110, "y": 311, "t": "Ex : le carpe", "ancre": "middle"}], "slide": 94}], "cartes": [{"id": "c3-01", "q": "Qu'est-ce qu'une articulation, quel est le nom de la discipline qui les \u00e9tudie, et pourquoi leur atteinte peut-elle compromettre la performance ?", "r": "Le moyen d'union entre 2 ou plusieurs pi\u00e8ces du squelette entre elles, plus ou moins mobile selon les cas ; leur \u00e9tude est l'arthrologie. En raison de leur r\u00f4le en biom\u00e9canique, une atteinte pathologique (arthrite, arthrose) ou traumatique (luxation, entorse) peut compromettre les postures et les mouvements, donc la performance.", "slide": 73}, {"id": "c3-02", "q": "Quelle diff\u00e9rence s\u00e9pare une articulation simple d'une articulation compos\u00e9e ?", "r": "Une articulation simple unit deux \u00e9l\u00e9ments ; une articulation compos\u00e9e en unit plus de deux.", "slide": 75}, {"id": "c3-03", "q": "Qu'est-ce qu'une synarthrose (articulation fibreuse), et quel exemple le cours en donne-t-il ?", "r": "Une articulation dont l'interzone est occup\u00e9e par du tissu fibreux : sans mobilit\u00e9 et sans cartilage articulaire. Exemple : la suture des os de la t\u00eate.", "slide": 75}, {"id": "c3-04", "q": "Qu'est-ce qu'une amphiarthrose (articulation cartilagineuse), et quel exemple le cours en donne-t-il ?", "r": "Une articulation dont l'interzone est occup\u00e9e par du fibrocartilage : mobilit\u00e9 r\u00e9duite, un cartilage articulaire, mais aucune cavit\u00e9 articulaire. Exemple : la symphyse pubienne.", "slide": 75}, {"id": "c3-05", "q": "Quelles sont les trois caract\u00e9ristiques communes aux articulations synoviales (diarthroses) ?", "r": "Des surfaces articulaires de forme variable, encro\u00fbt\u00e9es de cartilage hyalin ; une cavit\u00e9 articulaire ; une capsule articulaire faite de deux membranes (une fibreuse, une synoviale). Elles sont particuli\u00e8rement mobiles.", "slide": 77}, {"id": "c3-06", "q": "Selon quel crit\u00e8re les 7 types de diarthroses sont-ils class\u00e9s ?", "r": "Selon la forme de leurs surfaces articulaires.", "slide": 79}, {"id": "c3-07", "q": "D\u00e9cris la sph\u00e9ro\u00efde (\u00e9narthrose) : forme des surfaces, mouvements permis et exemple.", "r": "Une sph\u00e8re pleine (convexe) s'embo\u00eete dans une sph\u00e8re creuse (concave). Elle permet des mouvements dans toutes les directions (3 axes). Exemple : la hanche.", "slide": 81}, {"id": "c3-08", "q": "D\u00e9cris l'ellipso\u00efde (condylienne) : forme des surfaces et mouvements permis.", "r": "Une ellipse convexe s'embo\u00eete dans une ellipse concave. Elle poss\u00e8de 2 axes principaux de mouvement : flexion/extension, abduction/adduction.", "slide": 84}, {"id": "c3-09", "q": "D\u00e9cris l'articulation en selle : forme des surfaces, mouvements permis et exemple.", "r": "Une surface \u00ab en selle \u00bb, concave dans un sens et convexe dans l'autre, correspond \u00e0 une surface inversement conform\u00e9e. Elle poss\u00e8de 2 axes : flexion/extension, abduction/adduction. Exemple : l'articulation sterno-claviculaire.", "slide": 86}, {"id": "c3-10", "q": "D\u00e9cris la ginglyme (trochl\u00e9enne) : forme des surfaces, mouvement permis et exemple.", "r": "Une trochl\u00e9e s'embo\u00eete dans une cochl\u00e9e, formant une charni\u00e8re. Elle poss\u00e8de 1 axe : flexion-extension. Exemple : l'articulation hum\u00e9ro-ulnaire.", "slide": 88, "plan": "sagittal"}, {"id": "c3-11", "q": "D\u00e9cris la trocho\u00efde : forme des surfaces, mouvement permis et exemple.", "r": "Un cylindre convexe s'embo\u00eete dans un cylindre concave. Elle poss\u00e8de 1 axe de mouvement : pronation-supination (rotation). Exemple : l'articulation radio-ulnaire proximale.", "slide": 90, "plan": "transversal"}, {"id": "c3-12", "q": "D\u00e9cris la bicondylienne : forme des surfaces, mouvement permis et exemple.", "r": "Une paire de condyles convexes s'oppose \u00e0 une paire de condyles quasi plane. 1 axe principal : flexion/extension. Exemple : l'articulation tibio-f\u00e9morale.", "slide": 92, "plan": "sagittal"}, {"id": "c3-13", "q": "D\u00e9cris l'articulation plane (arthrodie) : forme des surfaces, mouvement permis et exemple.", "r": "Deux surfaces planes s'opposent. Le seul mouvement possible est un glissement. Exemple : le carpe.", "slide": 94}, {"id": "c3-14", "q": "De quoi est compos\u00e9e la capsule articulaire, et que d\u00e9crivent respectivement sa membrane fibreuse et sa membrane synoviale ?", "r": "De deux membranes. La membrane fibreuse : un manchon fibreux tr\u00e8s r\u00e9sistant et peu \u00e9lastique, prolongement du p\u00e9rioste. La membrane synoviale : mince et transparente, elle adh\u00e8re \u00e0 la face profonde de la fibreuse, recouvre les parties osseuses, tendons et ligaments intracapsulaires, et s\u00e9cr\u00e8te le liquide synovial.", "slide": 97}, {"id": "c3-15", "q": "Quel est le r\u00f4le m\u00e9canique du cartilage articulaire, et comment varie son \u00e9paisseur ?", "r": "C'est un cartilage hyalin qui prot\u00e8ge les surfaces articulaires contre l'usure. Son \u00e9paisseur est proportionnelle \u00e0 la pression subie ; il est d\u00e9formable (jusqu'\u00e0 50 %) et augmente d'\u00e9paisseur avec la mobilisation dynamique.", "slide": 99}, {"id": "c3-16", "q": "Comment le cartilage articulaire se nourrit-il, et que se passe-t-il une fois qu'il est d\u00e9truit ?", "r": "Il se nourrit par imbibition du liquide synovial (un pompage favoris\u00e9 par le mouvement). Une fois d\u00e9truit, il ne se r\u00e9g\u00e9n\u00e8re pas : il n'a ni nerf ni vaisseau.", "slide": 99}, {"id": "c3-17", "q": "Quelles sont les propri\u00e9t\u00e9s physiques de la synovie, et comment varie sa viscosit\u00e9 ?", "r": "Un liquide transparent et visqueux. \u00c0 froid ou \u00e0 l'immobilit\u00e9, elle reste tr\u00e8s visqueuse ; sa s\u00e9cr\u00e9tion est stimul\u00e9e par le mouvement.", "slide": 99}, {"id": "c3-18", "q": "Quels sont les r\u00f4les de la synovie envers l'articulation et le cartilage ?", "r": "Elle lubrifie et absorbe les chocs de l'articulation. Elle nourrit le cartilage (O2 et nutriments) et \u00e9limine les d\u00e9chets.", "slide": 99}, {"id": "c3-19", "q": "Outre nourrir le cartilage et \u00e9liminer les d\u00e9chets, quel r\u00f4le suppl\u00e9mentaire joue le liquide synovial contre les micro-organismes ?", "r": "Le liquide synovial contient aussi des phagocytes, qui d\u00e9barrassent la cavit\u00e9 articulaire des micro-organismes et des d\u00e9bris cellulaires.", "slide": 109}, {"id": "c3-20", "q": "D\u00e9cris le m\u00e9nisque : structure et r\u00f4le.", "r": "Un anneau de fibrocartilage, avec deux faces libres et une face adh\u00e9rente \u00e0 la capsule articulaire. Il assure la stabilit\u00e9 des surfaces articulaires en pr\u00e9sence.", "slide": 102}, {"id": "c3-21", "q": "\u00c0 quoi s'opposent les structures de maintien de l'articulation, de quoi sont-elles responsables en cas d'atteinte, et lesquelles le cours nomme-t-il ?", "r": "Elles s'opposent \u00e0 la dislocation de l'articulation ; leurs \u00e9longations et leurs ruptures sont responsables des entorses. Le cours en nomme trois : la membrane fibreuse de la capsule articulaire, les ligaments, et les tendons musculaires.", "slide": 104}, {"id": "c3-22", "q": "Quelle diff\u00e9rence s\u00e9pare un ligament intracapsulaire d'un ligament extracapsulaire, et quel exemple le cours donne-t-il de chacun au genou ?", "r": "Les ligaments intracapsulaires sont \u00e0 l'int\u00e9rieur de la capsule articulaire (ex : les ligaments crois\u00e9s du genou) ; les ligaments extracapsulaires sont \u00e0 l'ext\u00e9rieur (ex : les ligaments lat\u00e9raux du genou).", "slide": 104}, {"id": "c3-23", "q": "Quel r\u00f4le jouent les tendons musculaires dans le maintien de l'articulation, et que favorise l'atrophie des structures de maintien ?", "r": "Ils jouent un r\u00f4le de contention tr\u00e8s important. L'atrophie des structures de maintien favorise les instabilit\u00e9s et les blessures.", "slide": 104}, {"id": "c3-24", "q": "Par quels m\u00e9canismes le cartilage articulaire et la synovie r\u00e9duisent-ils la friction dans l'articulation ?", "r": "Le cartilage, gr\u00e2ce \u00e0 sa surface exceptionnellement lisse, r\u00e9duit le coefficient de friction articulaire. La synovie joue le r\u00f4le d'un lubrifiant qui gomme les asp\u00e9rit\u00e9s des cartilages.", "slide": 106}, {"id": "c3-25", "q": "Que provoquent, respectivement, l'absence d'activit\u00e9 musculaire et une mobilisation pouss\u00e9e jusqu'aux limites physiologiques sur une articulation ? De quels facteurs d\u00e9pend par ailleurs la mobilit\u00e9 articulaire ?", "r": "L'absence d'activit\u00e9 musculaire entra\u00eene le blocage progressif de l'articulation ; une mobilisation pouss\u00e9e jusqu'aux limites physiologiques cr\u00e9e au contraire une hyperlaxit\u00e9 articulaire, voire une luxation. La mobilit\u00e9 varie selon l'\u00e2ge, le sexe (la femme et l'enfant ont une souplesse plus grande que l'homme) et la pratique sportive : l'\u00e9chauffement des articulations concern\u00e9es par l'activit\u00e9 est indispensable.", "slide": 108}, {"id": "c3-26", "q": "Dans l'articulation, que sont les coussinets adipeux et quel est leur r\u00f4le ?", "r": "Le cours les d\u00e9finit par leur seul r\u00f4le : ils amortissent les chocs.", "slide": 109}, {"id": "c3-27", "q": "La bourse s\u00e9reuse : qu'est-ce que c'est, et \u00e0 quoi le cours la compare-t-il ?", "r": "De petits sacs fibreux qui contiennent une mince pellicule de liquide synovial. Le cours les compare \u00e0 des \u00ab roulements \u00e0 billes \u00bb : ils emp\u00eachent l'articulation de frotter, dans ses mouvements, contre les structures qui l'entourent.", "slide": 109}], "quiz": [{"id": "q3-01", "q": "Une sph\u00e8re pleine s'embo\u00eete dans une sph\u00e8re creuse, permettant des mouvements dans toutes les directions (3 axes). De quel type de diarthrose s'agit-il ?", "choix": ["La sph\u00e9ro\u00efde (\u00e9narthrose)", "L'ellipso\u00efde (condylienne)", "L'articulation en selle", "La bicondylienne"], "bonne": 0, "expl": "La sph\u00e9ro\u00efde est la seule diarthrose \u00e0 3 axes, d\u00e9finie par une sph\u00e8re pleine dans une sph\u00e8re creuse (ex : la hanche). L'ellipso\u00efde est le distracteur le plus proche : elle aussi embo\u00eete une forme convexe dans une forme concave, mais c'est une ELLIPSE (pas une sph\u00e8re) et elle n'a que 2 axes, pas 3. L'articulation en selle et la bicondylienne ont elles aussi 2 axes ou moins, et des surfaces de formes diff\u00e9rentes (en selle, ou en paire de condyles).", "slide": 81}, {"id": "q3-02", "q": "Quelle diarthrose permet la pronation-supination, par la rotation d'un cylindre convexe dans un cylindre concave ?", "choix": ["La ginglyme (trochl\u00e9enne)", "La trocho\u00efde", "La bicondylienne", "L'articulation plane (arthrodie)"], "bonne": 1, "expl": "La trocho\u00efde (ex : l'articulation radio-ulnaire proximale) est d\u00e9finie par un cylindre convexe qui s'embo\u00eete dans un cylindre concave, avec 1 axe de rotation (pronation-supination). La ginglyme est le distracteur le plus proche : elle a aussi 1 seul axe, mais c'est une charni\u00e8re (trochl\u00e9e dans cochl\u00e9e) qui ne fait que de la flexion-extension, pas de rotation. La bicondylienne (flexion/extension) et l'articulation plane (glissement seul) n'ont ni cylindre ni rotation.", "slide": 90, "plan": "transversal"}, {"id": "q3-03", "q": "Quelle famille d'articulations poss\u00e8de un cartilage articulaire mais est d\u00e9pourvue de cavit\u00e9 articulaire ?", "choix": ["Les synarthroses (fibreuses)", "Les amphiarthroses (cartilagineuses)", "Les diarthroses (synoviales)"], "bonne": 1, "expl": "Les amphiarthroses poss\u00e8dent un cartilage articulaire (l'interzone est du fibrocartilage) mais aucune cavit\u00e9 articulaire \u2014 c'est leur d\u00e9finition exacte (ex : la symphyse pubienne). Les synarthroses sont \u00e9cart\u00e9es par exc\u00e8s : elles n'ont NI cartilage NI mobilit\u00e9 (interzone fibreuse, ex : les sutures du cr\u00e2ne). Les diarthroses sont \u00e9cart\u00e9es par manque : elles ont justement une cavit\u00e9 articulaire, en plus du cartilage \u2014 c'est ce qui les rend particuli\u00e8rement mobiles, contrairement aux amphiarthroses.", "slide": 75}, {"id": "q3-04", "q": "Au genou, les ligaments crois\u00e9s et les ligaments lat\u00e9raux sont-ils intracapsulaires ou extracapsulaires ?", "choix": ["Les crois\u00e9s sont intracapsulaires, les lat\u00e9raux sont extracapsulaires", "Les crois\u00e9s sont extracapsulaires, les lat\u00e9raux sont intracapsulaires", "Les crois\u00e9s et les lat\u00e9raux sont tous deux intracapsulaires", "Les crois\u00e9s et les lat\u00e9raux sont tous deux extracapsulaires"], "bonne": 0, "expl": "Le cours donne exactement ces deux exemples : les ligaments crois\u00e9s du genou pour les ligaments intracapsulaires (\u00e0 l'int\u00e9rieur de la capsule), les ligaments lat\u00e9raux du genou pour les extracapsulaires (\u00e0 l'ext\u00e9rieur). Les trois autres options confondent ou inversent ce couple ; retenir que \u00ab crois\u00e9 \u00bb et \u00ab intracapsulaire \u00bb vont ensemble \u00e9vite l'inversion la plus fr\u00e9quente.", "slide": 104}, {"id": "q3-05", "q": "Quelle membrane de la capsule articulaire s\u00e9cr\u00e8te le liquide synovial ?", "choix": ["La membrane fibreuse", "La membrane synoviale", "Le p\u00e9rioste", "Le p\u00e9richondre"], "bonne": 1, "expl": "La membrane synoviale, mince et transparente, adh\u00e8re \u00e0 la face profonde de la membrane fibreuse et s\u00e9cr\u00e8te le liquide synovial. La membrane fibreuse est le distracteur le plus proche : c'est l'autre moiti\u00e9 de la m\u00eame capsule, mais son r\u00f4le est m\u00e9canique (manchon r\u00e9sistant, peu \u00e9lastique, prolongement du p\u00e9rioste), pas s\u00e9cr\u00e9toire. Le p\u00e9rioste et le p\u00e9richondre sont des membranes r\u00e9elles du cours (chapitre 2), mais elles enveloppent respectivement l'os et le cartilage en g\u00e9n\u00e9ral \u2014 ni l'une ni l'autre n'appartient \u00e0 la capsule articulaire.", "slide": 97}, {"id": "q3-06", "q": "Une fois d\u00e9truit, le cartilage articulaire peut-il se r\u00e9g\u00e9n\u00e9rer ?", "choix": ["Non, il n'a ni nerf ni vaisseau", "Oui, lentement, gr\u00e2ce \u00e0 sa vascularisation", "Oui, rapidement, gr\u00e2ce \u00e0 la synovie qui le r\u00e9g\u00e9n\u00e8re", "Oui, mais seulement chez l'enfant"], "bonne": 0, "expl": "Le cours l'affirme sans nuance : une fois d\u00e9truit, le cartilage articulaire ne se r\u00e9g\u00e9n\u00e8re pas, faute de nerf et de vaisseau. La synovie le NOURRIT par imbibition (elle favorise son entretien pendant qu'il est intact), mais rien dans le cours ne dit qu'elle le r\u00e9g\u00e9n\u00e8re une fois d\u00e9truit \u2014 c'est la confusion entre \u00ab se nourrir \u00bb et \u00ab se r\u00e9g\u00e9n\u00e9rer \u00bb que ce distracteur exploite. Aucune vascularisation, \u00e0 aucun \u00e2ge, n'est mentionn\u00e9e pour ce cartilage.", "slide": 99}, {"id": "q3-07", "q": "Que devient la synovie \u00e0 froid ou \u00e0 l'immobilit\u00e9, et qu'est-ce qui stimule sa s\u00e9cr\u00e9tion ?", "choix": ["Elle reste tr\u00e8s visqueuse ; sa s\u00e9cr\u00e9tion est stimul\u00e9e par le mouvement", "Elle devient fluide ; sa s\u00e9cr\u00e9tion est stimul\u00e9e par le repos", "Elle se solidifie ; sa s\u00e9cr\u00e9tion est constante, ind\u00e9pendante du mouvement", "Elle s'\u00e9vapore ; sa s\u00e9cr\u00e9tion est stimul\u00e9e par la chaleur"], "bonne": 0, "expl": "Le cours l'\u00e9nonce dans cet ordre pr\u00e9cis : \u00e0 froid ou \u00e0 l'immobilit\u00e9, la synovie reste tr\u00e8s visqueuse, et c'est le MOUVEMENT qui stimule sa s\u00e9cr\u00e9tion \u2014 d'o\u00f9 l'int\u00e9r\u00eat de l'\u00e9chauffement. Les trois autres options inversent soit l'effet du froid (fluide au lieu de visqueuse), soit le d\u00e9clencheur de la s\u00e9cr\u00e9tion (repos ou chaleur au lieu du mouvement).", "slide": 99}, {"id": "q3-08", "q": "Que provoque l'absence d'activit\u00e9 musculaire sur une articulation ?", "choix": ["Le blocage progressif de l'articulation", "Une hyperlaxit\u00e9 articulaire", "Une luxation imm\u00e9diate", "Aucun effet mesurable"], "bonne": 0, "expl": "Le cours l'affirme directement : l'absence d'activit\u00e9 musculaire entra\u00eene le blocage progressif de l'articulation. L'hyperlaxit\u00e9 et la luxation sont le distracteur le plus pi\u00e9geur : elles sont r\u00e9elles, mais caus\u00e9es par le m\u00e9canisme INVERSE \u2014 une mobilisation pouss\u00e9e jusqu'aux limites physiologiques, pas son absence. \u00ab Aucun effet \u00bb contredit l'id\u00e9e m\u00eame d'adaptation fonctionnelle que ce paragraphe d\u00e9veloppe.", "slide": 108}, {"id": "q3-09", "q": "L'atteinte des structures de maintien (ligaments, tendons, membrane fibreuse) est responsable de quel type de traumatisme ?", "choix": ["Des entorses", "De l'arthrose", "D'une luxation cong\u00e9nitale", "De l'arthrite"], "bonne": 0, "expl": "Le cours le dit explicitement : les \u00e9longations et ruptures des structures de maintien sont responsables des entorses. L'arthrose et l'arthrite sont des pathologies r\u00e9elles nomm\u00e9es dans le chapitre (slide 73), mais li\u00e9es \u00e0 l'usure ou \u00e0 l'inflammation de l'articulation, pas \u00e0 l'atteinte des ligaments et tendons. La luxation, elle, est plut\u00f4t associ\u00e9e par le cours \u00e0 l'exc\u00e8s de mobilisation (hyperlaxit\u00e9), pas \u00e0 l'atteinte des structures de maintien.", "slide": 104}, {"id": "q3-10", "q": "Selon quel crit\u00e8re les 7 types de diarthroses sont-ils class\u00e9s ?", "choix": ["La forme de leurs surfaces articulaires", "Le nombre d'axes de mouvement qu'elles autorisent", "Leur localisation anatomique (membre sup\u00e9rieur ou inf\u00e9rieur)", "La taille de leur cavit\u00e9 articulaire"], "bonne": 0, "expl": "Le cours l'\u00e9nonce explicitement : les 7 types de diarthroses sont class\u00e9s en fonction de la forme de leurs surfaces articulaires. Le nombre d'axes est une CONS\u00c9QUENCE de cette forme (une sph\u00e8re a 3 axes, une charni\u00e8re 1 axe), pas le crit\u00e8re de classement lui-m\u00eame. La localisation anatomique et la taille de la cavit\u00e9 ne sont jamais utilis\u00e9es comme crit\u00e8re de classification dans le cours.", "slide": 79}, {"id": "q3-11", "q": "Quelle structure agit \u00ab comme des roulements \u00e0 billes \u00bb pour r\u00e9duire le frottement au voisinage de l'articulation ?", "choix": ["La bourse s\u00e9reuse", "Le coussinet adipeux", "Le cartilage articulaire", "La membrane synoviale"], "bonne": 0, "expl": "Le cours emploie litt\u00e9ralement l'image des \u00ab roulements \u00e0 billes \u00bb pour la bourse s\u00e9reuse : ce petit sac fibreux contient une mince pellicule de liquide synovial et emp\u00eache l'articulation de frotter contre les structures qui l'entourent. Le coussinet adipeux est le distracteur le plus proche : sur le m\u00eame sch\u00e9ma, il amortit les CHOCS (compression), pas le frottement (glissement). Le cartilage articulaire r\u00e9duit lui aussi la friction, mais par sa propre lisset\u00e9, pas par un sac de liquide s\u00e9par\u00e9 ; la membrane synoviale S\u00c9CR\u00c8TE le liquide synovial, elle ne joue pas ce r\u00f4le de coussin roulant.", "slide": 109}], "pieges": [{"titre": "Le cartilage articulaire ne se r\u00e9g\u00e9n\u00e8re JAMAIS une fois d\u00e9truit", "texte": "Contrairement \u00e0 l'os, qui reste vivant et vascularis\u00e9, le cartilage articulaire n'a ni nerf ni vaisseau : il se nourrit seulement par imbibition du liquide synovial (un pompage favoris\u00e9 par le mouvement), mais une fois d\u00e9truit, il ne se r\u00e9g\u00e9n\u00e8re pas.", "slide": 99}, {"titre": "La synovie reste visqueuse \u00c0 FROID \u2014 c'est le mouvement qui stimule sa s\u00e9cr\u00e9tion", "texte": "Deux faits li\u00e9s, faciles \u00e0 inverser : \u00e0 froid ou \u00e0 l'immobilit\u00e9, la synovie reste tr\u00e8s visqueuse (elle lubrifie mal) ; c'est le mouvement qui stimule sa s\u00e9cr\u00e9tion. D'o\u00f9 l'importance de l'\u00e9chauffement avant l'effort, pour obtenir une synovie fluide au bon moment.", "slide": 99}, {"titre": "Absence de mouvement et exc\u00e8s de mouvement causent deux probl\u00e8mes OPPOS\u00c9S", "texte": "L'absence d'activit\u00e9 musculaire entra\u00eene le blocage progressif de l'articulation. \u00c0 l'inverse, une mobilisation pouss\u00e9e jusqu'aux limites physiologiques cr\u00e9e une hyperlaxit\u00e9 articulaire, voire une luxation. Ne pas confondre : ce n'est pas le m\u00eame m\u00e9canisme qui produit ces deux effets, ni la m\u00eame cons\u00e9quence.", "slide": 108}, {"titre": "Les entorses viennent de l'atteinte des structures de MAINTIEN, pas des structures de protection", "texte": "Les structures de maintien (membrane fibreuse de la capsule, ligaments, tendons musculaires) s'opposent \u00e0 la dislocation de l'articulation : ce sont leurs \u00e9longations et leurs ruptures qui sont responsables des entorses \u2014 pas l'usure du cartilage (structure d'amortissement) ni un d\u00e9faut de la membrane synoviale (structure de protection).", "slide": 104}], "muscles": []}, {"num": 4, "titre": "Le syst\u00e8me musculaire", "slides": [111, 134], "sections": [{"titre": "Myologie et les trois types de muscles", "slide": 112, "points": ["L'\u00e9tude des muscles est la myologie. Le syst\u00e8me musculaire forme l'\u00e9l\u00e9ment MOTEUR du mouvement.", "Les muscles squelettiques : muscles stri\u00e9s qui se contractent sous l'influence de la volont\u00e9 ; ils mobilisent en particulier le syst\u00e8me squelettique.", "Les muscles lisses : muscles non stri\u00e9s qui \u00e9chappent \u00e0 l'influence de la volont\u00e9 ; ils sont localis\u00e9s dans les visc\u00e8res, les vaisseaux sanguins et la peau.", "Les muscles mixtes : le muscle cardiaque est un muscle stri\u00e9, mais ind\u00e9pendant de l'influence de la volont\u00e9."]}, {"titre": "Nombre et forme du muscle", "slide": 114, "points": ["Le corps humain poss\u00e8de 600 muscles.", "Un muscle se compose d'1 corps charnu, rouge et contractile (le ventre) et de 2 extr\u00e9mit\u00e9s plus fines (les tendons)."]}, {"titre": "Les formes musculaires", "slide": 115, "points": ["Le cours illustre huit formes de muscles : fusiforme, biceps, triceps, quadriceps, puis unipenn\u00e9, bipenn\u00e9, segment\u00e9 et dentel\u00e9.", "Fusiforme, biceps, triceps, quadriceps se distinguent par le nombre de chefs charnus (1, 2, 3, 4) qui convergent vers un tendon commun.", "Unipenn\u00e9 et bipenn\u00e9 : les fibres rejoignent un tendon central en oblique, d'un seul c\u00f4t\u00e9 ou des deux c\u00f4t\u00e9s. Segment\u00e9 : plusieurs ventres en s\u00e9rie. Dentel\u00e9 : plusieurs languettes en \u00e9ventail."]}, {"titre": "Structure macroscopique : les enveloppes du muscle", "slide": 117, "points": ["\u00c9pimysium : enveloppe qui recouvre l'ensemble du muscle.", "P\u00e9rimysium : enveloppe qui recouvre un faisceau musculaire.", "Endomysium : enveloppe qui recouvre une fibre musculaire, elle-m\u00eame recouverte par une deuxi\u00e8me membrane, le sarcolemme."]}, {"titre": "Structure microscopique : myofibrille, sarcom\u00e8re, stries Z", "slide": 119, "points": ["La cellule musculaire, ou fibre musculaire, contient des myofibrilles. Une myofibrille est compos\u00e9e de sarcom\u00e8res, d\u00e9limit\u00e9s par des stries Z.", "La contraction musculaire se d\u00e9roule entre chaque strie Z par l'interm\u00e9diaire de 2 prot\u00e9ines contractiles (myofilaments) : la myosine (filament \u00e9pais) et l'actine (filament fin)."]}, {"titre": "Le sarcom\u00e8re en d\u00e9tail", "slide": 120, "points": ["Le sch\u00e9ma du cours nomme la fibre musculaire \u00ab myocyte \u00bb : c'est elle la cellule, elle contient plusieurs myofibrilles.", "Dans un sarcom\u00e8re, les filaments d'actine (fins) partent de chaque strie Z vers le centre ; les filaments de myosine (\u00e9pais) occupent la portion centrale, o\u00f9 ils chevauchent les filaments d'actine."]}, {"titre": "Le m\u00e9canisme du glissement des filaments", "slide": 121, "points": ["Sur l'actine, un complexe troponine-tropomyosine masque le site actif ; le calcium (Ca2+) permet sa lib\u00e9ration, rendant possible la fixation de la t\u00eate de myosine.", "L'ATP fournit l'\u00e9nergie qui permet \u00e0 la t\u00eate de myosine de se d\u00e9tacher puis de se replacer, faisant avancer le filament d'actine \u00e0 chaque cycle : c'est le moteur du glissement des filaments."]}, {"titre": "L'excitabilit\u00e9 et l'unit\u00e9 motrice", "slide": 123, "points": ["L'excitabilit\u00e9 est la propri\u00e9t\u00e9 que poss\u00e8de le muscle de r\u00e9agir par sa r\u00e9ponse naturelle, la contraction, \u00e0 toute excitation port\u00e9e sur lui.", "Suivant le message nerveux, les fibres d'un m\u00eame muscle ne sont pas toutes sollicit\u00e9es en m\u00eame temps.", "Unit\u00e9 motrice (UM) : fibres musculaires + motoneurone alpha. Les fibres musculaires d'une m\u00eame UM ont les m\u00eames caract\u00e9ristiques physiologiques et m\u00e9caniques."]}, {"titre": "La contractilit\u00e9", "slide": 126, "points": ["La contractilit\u00e9 est la facult\u00e9 que poss\u00e8de le muscle de se raccourcir, donc de rapprocher ses extr\u00e9mit\u00e9s, donc de g\u00e9n\u00e9rer le mouvement."]}, {"titre": "La secousse musculaire et la p\u00e9riode r\u00e9fractaire", "slide": 127, "points": ["La secousse musculaire (3 temps) : le temps de latence (le muscle ne se contracte pas imm\u00e9diatement apr\u00e8s le stimulus), le temps de contraction (raccourcissement du muscle), et le temps de rel\u00e2chement ou d\u00e9contraction (plus longue que la pr\u00e9c\u00e9dente, le muscle reprend sa longueur initiale).", "La p\u00e9riode r\u00e9fractaire : temps pendant lequel la fibre musculaire est inexcitable."]}, {"titre": "L'\u00e9lasticit\u00e9", "slide": 130, "points": ["L'\u00e9lasticit\u00e9 est la propri\u00e9t\u00e9 que poss\u00e8de le muscle de se laisser allonger par traction, et de revenir \u00e0 sa position initiale lorsque cesse l'allongement."]}, {"titre": "La tonicit\u00e9 et le tonus musculaire", "slide": 132, "points": ["La tonicit\u00e9 est la propri\u00e9t\u00e9 qu'a le muscle vivant, en dehors de tout mouvement actif, de demeurer dans un \u00e9tat de tension, de l\u00e9g\u00e8re contraction, permanente et involontaire : c'est le tonus musculaire."]}, {"titre": "La plasticit\u00e9", "slide": 134, "points": ["La plasticit\u00e9 est la capacit\u00e9 du muscle \u00e0 se modifier ou \u00e0 s'adapter \u00e0 certaines situations ou contraintes (entra\u00eenement ou d\u00e9sentra\u00eenement).", "Deux types d'adaptations : les adaptations nerveuses (coordination) et les adaptations p\u00e9riph\u00e9riques (hypertrophie)."]}], "cartes": [{"id": "c4-01", "q": "Qu'est-ce que la myologie, et quel r\u00f4le le cours attribue-t-il au syst\u00e8me musculaire dans le mouvement ?", "r": "La myologie est l'\u00e9tude des muscles. Le syst\u00e8me musculaire forme l'\u00e9l\u00e9ment MOTEUR du mouvement.", "slide": 112}, {"id": "c4-02", "q": "Sur quels deux crit\u00e8res le cours distingue-t-il les 3 types de muscles, et quels sont-ils ?", "r": "Sur le fait d'\u00eatre stri\u00e9 ou non, et volontaire ou non : les muscles squelettiques (stri\u00e9s, volontaires), les muscles lisses (non stri\u00e9s, involontaires), et les muscles mixtes (le muscle cardiaque).", "slide": 112}, {"id": "c4-03", "q": "Que sont les muscles squelettiques, et quel est leur r\u00f4le particulier ?", "r": "Des muscles stri\u00e9s qui se contractent sous l'influence de la volont\u00e9 ; ils mobilisent en particulier le syst\u00e8me squelettique.", "slide": 112}, {"id": "c4-04", "q": "Que sont les muscles lisses, et o\u00f9 le cours les localise-t-il ?", "r": "Des muscles non stri\u00e9s qui \u00e9chappent \u00e0 l'influence de la volont\u00e9, localis\u00e9s dans les visc\u00e8res, les vaisseaux sanguins et la peau.", "slide": 112}, {"id": "c4-05", "q": "Pourquoi le muscle cardiaque est-il qualifi\u00e9 de muscle mixte ?", "r": "Parce qu'il est stri\u00e9 comme un muscle squelettique, mais ind\u00e9pendant de l'influence de la volont\u00e9 comme un muscle lisse.", "slide": 112}, {"id": "c4-06", "q": "Combien de muscles le cours attribue-t-il au corps humain, et de quoi un muscle se compose-t-il en forme ?", "r": "600 muscles. Un muscle se compose d'1 corps charnu, rouge et contractile (le ventre) et de 2 extr\u00e9mit\u00e9s plus fines (les tendons).", "slide": 114}, {"id": "c4-07", "q": "Quelles sont les huit formes musculaires illustr\u00e9es par le cours ?", "r": "Fusiforme, biceps, triceps, quadriceps, puis unipenn\u00e9, bipenn\u00e9, segment\u00e9 et dentel\u00e9.", "slide": 115}, {"id": "c4-08", "q": "Qu'est-ce qui distingue les formes biceps, triceps et quadriceps entre elles ?", "r": "Le nombre de chefs charnus qui convergent vers un tendon commun : 2, 3 et 4 chefs respectivement.", "slide": 115}, {"id": "c4-09", "q": "Quelles sont, de l'ext\u00e9rieur vers l'int\u00e9rieur, les trois enveloppes conjonctives du muscle, et que recouvre chacune ?", "r": "L'\u00e9pimysium recouvre l'ensemble du muscle ; le p\u00e9rimysium recouvre un faisceau musculaire ; l'endomysium recouvre une fibre musculaire.", "slide": 117}, {"id": "c4-10", "q": "Qu'est-ce que le sarcolemme, et en quoi se distingue-t-il de l'endomysium ?", "r": "C'est la deuxi\u00e8me membrane qui recouvre la fibre musculaire, en plus de l'endomysium : l'endomysium est le tissu conjonctif qui l'entoure, le sarcolemme est la membrane propre de la fibre elle-m\u00eame.", "slide": 117}, {"id": "c4-11", "q": "Que contient une myofibrille, et par quoi ses sarcom\u00e8res sont-ils d\u00e9limit\u00e9s ?", "r": "Une myofibrille est compos\u00e9e de sarcom\u00e8res, d\u00e9limit\u00e9s par des stries Z (lignes Z).", "slide": 119}, {"id": "c4-12", "q": "Entre deux stries Z, par l'interm\u00e9diaire de quelles deux prot\u00e9ines contractiles la contraction se d\u00e9roule-t-elle ?", "r": "La myosine (filament \u00e9pais) et l'actine (filament fin).", "slide": 119}, {"id": "c4-13", "q": "Dans l'embo\u00eetement du muscle, \u00e0 quel niveau se situe la myofibrille par rapport \u00e0 la fibre musculaire ?", "r": "La myofibrille est un organite situ\u00e9 \u00c0 L'INT\u00c9RIEUR de la fibre musculaire (nomm\u00e9e \u00ab myocyte \u00bb sur le sch\u00e9ma du cours) ; le sarcom\u00e8re est lui-m\u00eame un segment de myofibrille.", "slide": 120}, {"id": "c4-14", "q": "Dans le sarcom\u00e8re, o\u00f9 se situent respectivement les filaments d'actine et les filaments de myosine ?", "r": "Les filaments d'actine (fins) partent de chaque strie Z vers le centre du sarcom\u00e8re ; les filaments de myosine (\u00e9pais) occupent la partie centrale, o\u00f9 ils chevauchent les filaments d'actine.", "slide": 120}, {"id": "c4-15", "q": "D'apr\u00e8s le sch\u00e9ma du glissement des filaments, quel est le r\u00f4le du calcium (Ca2+) dans la contraction ?", "r": "Le calcium permet la lib\u00e9ration du site actif de l'actine, normalement masqu\u00e9 par le complexe troponine-tropomyosine, rendant possible la fixation de la t\u00eate de myosine.", "slide": 121}, {"id": "c4-16", "q": "Quel est le r\u00f4le de l'ATP dans le glissement des filaments d'actine et de myosine ?", "r": "L'ATP fournit l'\u00e9nergie qui permet \u00e0 la t\u00eate de myosine de se d\u00e9tacher et de se replacer, faisant avancer le filament d'actine \u00e0 chaque cycle : c'est le moteur du mouvement du filament.", "slide": 121}, {"id": "c4-17", "q": "Qu'est-ce que l'excitabilit\u00e9 musculaire ?", "r": "La propri\u00e9t\u00e9 que poss\u00e8de le muscle de r\u00e9agir, par sa r\u00e9ponse naturelle la contraction, \u00e0 toute excitation port\u00e9e sur lui.", "slide": 123}, {"id": "c4-18", "q": "Qu'est-ce qu'une unit\u00e9 motrice (UM), et que partagent les fibres d'une m\u00eame UM ?", "r": "Une unit\u00e9 motrice, c'est un motoneurone alpha plus les fibres musculaires qu'il innerve. Les fibres d'une m\u00eame UM partagent les m\u00eames caract\u00e9ristiques physiologiques et m\u00e9caniques.", "slide": 124}, {"id": "c4-19", "q": "Pourquoi les fibres d'un m\u00eame muscle ne sont-elles pas toutes sollicit\u00e9es en m\u00eame temps ?", "r": "Parce que le recrutement d\u00e9pend du message nerveux : suivant ce message, seules certaines unit\u00e9s motrices (fibres + motoneurone alpha) sont activ\u00e9es.", "slide": 124}, {"id": "c4-20", "q": "Qu'est-ce que la contractilit\u00e9 musculaire ?", "r": "La facult\u00e9 que poss\u00e8de le muscle de se raccourcir, donc de rapprocher ses extr\u00e9mit\u00e9s, donc de g\u00e9n\u00e9rer le mouvement.", "slide": 126}, {"id": "c4-21", "q": "Quels sont les trois temps de la secousse musculaire, dans l'ordre ?", "r": "Le temps de latence (le muscle ne se contracte pas imm\u00e9diatement apr\u00e8s le stimulus), le temps de contraction (raccourcissement du muscle), puis le temps de rel\u00e2chement ou d\u00e9contraction (plus long que le pr\u00e9c\u00e9dent, le muscle reprend sa longueur initiale).", "slide": 127}, {"id": "c4-22", "q": "Qu'est-ce que la p\u00e9riode r\u00e9fractaire ?", "r": "Le temps pendant lequel la fibre musculaire est inexcitable.", "slide": 127}, {"id": "c4-23", "q": "Qu'est-ce que l'\u00e9lasticit\u00e9 musculaire ?", "r": "La propri\u00e9t\u00e9 que poss\u00e8de le muscle de se laisser allonger par traction, et de revenir \u00e0 sa position initiale lorsque cesse l'allongement.", "slide": 130}, {"id": "c4-24", "q": "Qu'est-ce que la tonicit\u00e9, et comment le cours nomme-t-il cet \u00e9tat permanent du muscle vivant ?", "r": "La propri\u00e9t\u00e9 qu'a le muscle vivant, en dehors de tout mouvement actif, de demeurer dans un \u00e9tat de tension, de l\u00e9g\u00e8re contraction, permanente et involontaire : c'est le tonus musculaire.", "slide": 132}, {"id": "c4-25", "q": "Qu'est-ce que la plasticit\u00e9 musculaire, et quelles sont ses deux types d'adaptations ?", "r": "La capacit\u00e9 du muscle \u00e0 se modifier ou \u00e0 s'adapter \u00e0 certaines situations ou contraintes (entra\u00eenement ou d\u00e9sentra\u00eenement) : les adaptations nerveuses (coordination) et les adaptations p\u00e9riph\u00e9riques (hypertrophie).", "slide": 134}], "quiz": [{"id": "q4-01", "q": "Quelle enveloppe conjonctive recouvre pr\u00e9cis\u00e9ment un FAISCEAU musculaire (un groupe de fibres) \u2014 ni le muscle entier, ni une fibre seule ?", "choix": ["\u00c9pimysium", "P\u00e9rimysium", "Endomysium", "Sarcolemme"], "bonne": 1, "expl": "Le p\u00e9rimysium recouvre un faisceau musculaire : c'est le niveau interm\u00e9diaire de l'embo\u00eetement. L'\u00e9pimysium est un niveau au-dessus (le muscle entier) ; l'endomysium est un niveau au-dessous (une fibre) ; le sarcolemme n'est m\u00eame pas une enveloppe conjonctive, mais la membrane propre de la fibre.", "slide": 117}, {"id": "q4-02", "q": "La fibre musculaire est recouverte de deux enveloppes distinctes. Lesquelles, et dans quel ordre (de l'ext\u00e9rieur vers l'int\u00e9rieur) ?", "choix": ["L'\u00e9pimysium puis le p\u00e9rimysium", "Le p\u00e9rimysium puis l'endomysium", "L'endomysium puis le sarcolemme", "Le sarcolemme puis l'\u00e9pimysium"], "bonne": 2, "expl": "Le cours le dit explicitement : l'endomysium recouvre la fibre musculaire, elle-m\u00eame recouverte par une deuxi\u00e8me membrane, le sarcolemme. Les deux autres distracteurs m\u00e9langent des niveaux : \u00e9pimysium et p\u00e9rimysium appartiennent au muscle entier et au faisceau, pas \u00e0 la fibre ; le troisi\u00e8me associe deux extr\u00eames de l'embo\u00eetement (fibre et muscle entier).", "slide": 117}, {"id": "q4-03", "q": "Dans l'embo\u00eetement du muscle, quel est l'ordre correct, du plus grand au plus petit ?", "choix": ["Muscle \u2192 faisceau \u2192 fibre \u2192 myofibrille \u2192 sarcom\u00e8re", "Muscle \u2192 fibre \u2192 faisceau \u2192 myofibrille \u2192 sarcom\u00e8re", "Muscle \u2192 faisceau \u2192 myofibrille \u2192 fibre \u2192 sarcom\u00e8re", "Faisceau \u2192 muscle \u2192 fibre \u2192 myofibrille \u2192 sarcom\u00e8re"], "bonne": 0, "expl": "L'ordre correct est muscle, puis faisceau (groupe de fibres), puis fibre, puis myofibrille (organite \u00e0 l'int\u00e9rieur de la fibre), puis sarcom\u00e8re (segment de myofibrille). Chaque distracteur inverse deux niveaux adjacents : fibre et faisceau \u00e9chang\u00e9s, myofibrille et fibre \u00e9chang\u00e9es, ou muscle et faisceau \u00e9chang\u00e9s.", "slide": 120}, {"id": "q4-04", "q": "Qu'est-ce qui d\u00e9limite un sarcom\u00e8re ?", "choix": ["Les stries Z", "Le sarcolemme", "L'endomysium", "Le p\u00e9rimysium"], "bonne": 0, "expl": "Un sarcom\u00e8re est d\u00e9limit\u00e9 par des stries Z (lignes Z), \u00e0 l'\u00e9chelle de la myofibrille. Les trois distracteurs sont tous vrais \u00e0 un autre niveau de l'embo\u00eetement, mais aucun ne d\u00e9limite un sarcom\u00e8re : le sarcolemme est la membrane de la fibre enti\u00e8re, l'endomysium l'enveloppe conjonctive de la fibre, le p\u00e9rimysium celle du faisceau.", "slide": 119}, {"id": "q4-05", "q": "Quelles sont les deux prot\u00e9ines contractiles (myofilaments) de la contraction musculaire, et laquelle est le filament \u00e9pais ?", "choix": ["Actine (\u00e9pais) et myosine (fin)", "Myosine (\u00e9pais) et actine (fin)", "Actine et tropomyosine, toutes deux \u00e9paisses", "Myosine et troponine, toutes deux fines"], "bonne": 1, "expl": "La myosine est le filament \u00e9pais, l'actine le filament fin : le cours le pr\u00e9cise explicitement entre parenth\u00e8ses. Le premier distracteur inverse les deux ; les deux derniers introduisent la tropomyosine et la troponine (vues sur le sch\u00e9ma du glissement des filaments), qui ne sont pas les deux myofilaments contractiles nomm\u00e9s par le cours.", "slide": 119}, {"id": "q4-06", "q": "Quelle propri\u00e9t\u00e9 permet au muscle de r\u00e9agir, PAR LA CONTRACTION, \u00e0 toute excitation qu'il re\u00e7oit ?", "choix": ["La contractilit\u00e9", "L'excitabilit\u00e9", "L'\u00e9lasticit\u00e9", "La tonicit\u00e9"], "bonne": 1, "expl": "C'est la d\u00e9finition m\u00eame de l'excitabilit\u00e9 donn\u00e9e par le cours. La contractilit\u00e9 d\u00e9crit ensuite le m\u00e9canisme de cette r\u00e9ponse (se raccourcir) plut\u00f4t que la capacit\u00e9 \u00e0 r\u00e9agir ; l'\u00e9lasticit\u00e9 concerne l'allongement par traction, la tonicit\u00e9 l'\u00e9tat permanent involontaire du muscle au repos.", "slide": 123}, {"id": "q4-07", "q": "Quelle propri\u00e9t\u00e9 correspond \u00e0 la capacit\u00e9 du muscle \u00e0 se raccourcir, donc \u00e0 g\u00e9n\u00e9rer le mouvement ?", "choix": ["L'excitabilit\u00e9", "La contractilit\u00e9", "L'\u00e9lasticit\u00e9", "La plasticit\u00e9"], "bonne": 1, "expl": "La contractilit\u00e9 est la facult\u00e9 du muscle \u00e0 se raccourcir, rapprochant ses extr\u00e9mit\u00e9s et g\u00e9n\u00e9rant le mouvement. L'excitabilit\u00e9 est la capacit\u00e9 \u00e0 r\u00e9agir \u00e0 une excitation (pas le raccourcissement lui-m\u00eame) ; l'\u00e9lasticit\u00e9 concerne le retour apr\u00e8s allongement ; la plasticit\u00e9 l'adaptation \u00e0 l'entra\u00eenement.", "slide": 126}, {"id": "q4-08", "q": "Quelle propri\u00e9t\u00e9 d\u00e9signe la capacit\u00e9 du muscle \u00e0 revenir \u00e0 sa longueur initiale apr\u00e8s un allongement par traction ?", "choix": ["La contractilit\u00e9", "L'\u00e9lasticit\u00e9", "La tonicit\u00e9", "La plasticit\u00e9"], "bonne": 1, "expl": "C'est la d\u00e9finition de l'\u00e9lasticit\u00e9. La contractilit\u00e9 est un raccourcissement actif (pas un simple retour apr\u00e8s traction passive) ; la tonicit\u00e9 est un \u00e9tat permanent, pas un retour apr\u00e8s allongement ; la plasticit\u00e9 est une adaptation \u00e0 long terme, pas une propri\u00e9t\u00e9 m\u00e9canique imm\u00e9diate.", "slide": 130}, {"id": "q4-09", "q": "Quelle propri\u00e9t\u00e9 d\u00e9signe l'\u00e9tat permanent de l\u00e9g\u00e8re tension involontaire du muscle vivant, en dehors de tout mouvement actif ?", "choix": ["L'excitabilit\u00e9", "La contractilit\u00e9", "La tonicit\u00e9", "La plasticit\u00e9"], "bonne": 2, "expl": "C'est la tonicit\u00e9, \u00e0 l'origine du tonus musculaire. L'excitabilit\u00e9 et la contractilit\u00e9 d\u00e9crivent une r\u00e9ponse \u00e0 une excitation, pas un \u00e9tat permanent au repos ; la plasticit\u00e9 d\u00e9crit une adaptation \u00e0 l'entra\u00eenement, pas une tension de fond.", "slide": 132}, {"id": "q4-10", "q": "Quelle propri\u00e9t\u00e9 d\u00e9signe la capacit\u00e9 du muscle \u00e0 s'adapter \u00e0 l'entra\u00eenement ou au d\u00e9sentra\u00eenement (par exemple l'hypertrophie) ?", "choix": ["L'\u00e9lasticit\u00e9", "La tonicit\u00e9", "La plasticit\u00e9", "La contractilit\u00e9"], "bonne": 2, "expl": "C'est la plasticit\u00e9, avec ses deux types d'adaptations (nerveuses et p\u00e9riph\u00e9riques). L'\u00e9lasticit\u00e9 et la tonicit\u00e9 sont des propri\u00e9t\u00e9s stables du muscle, pas des capacit\u00e9s d'adaptation ; la contractilit\u00e9 d\u00e9crit le raccourcissement, pas l'adaptation \u00e0 l'entra\u00eenement.", "slide": 134}, {"id": "q4-11", "q": "Parmi les trois temps de la secousse musculaire, lequel est le PLUS LONG ?", "choix": ["Le temps de latence", "Le temps de contraction", "Le temps de rel\u00e2chement", "La p\u00e9riode r\u00e9fractaire"], "bonne": 2, "expl": "Le cours le pr\u00e9cise : le temps de rel\u00e2chement (d\u00e9contraction) est plus long que le temps de contraction qui le pr\u00e9c\u00e8de. La p\u00e9riode r\u00e9fractaire n'est pas un des trois temps de la secousse, c'est une notion distincte (l'inexcitabilit\u00e9 temporaire de la fibre).", "slide": 127}, {"id": "q4-12", "q": "Qu'est-ce qu'une unit\u00e9 motrice ?", "choix": ["Un muscle entier et son tendon", "Un motoneurone alpha et les fibres musculaires qu'il innerve", "Un sarcom\u00e8re et ses deux stries Z", "Un faisceau musculaire et son p\u00e9rimysium"], "bonne": 1, "expl": "L'unit\u00e9 motrice, c'est fibres musculaires + motoneurone alpha. Les autres distracteurs recyclent des paires structure/enveloppe correctes \u00e0 d'autres niveaux (muscle/tendon, sarcom\u00e8re/strie Z, faisceau/p\u00e9rimysium), mais aucune n'est la d\u00e9finition de l'unit\u00e9 motrice.", "slide": 124}], "pieges": [{"titre": "La fibre musculaire (le \u00ab myocyte \u00bb) n'est pas la myofibrille", "texte": "Le sch\u00e9ma du cours (slide 120) nomme la fibre musculaire \u00ab myocyte \u00bb : c'est elle, la cellule, qui contient PLUSIEURS myofibrilles, elles-m\u00eames faites de sarcom\u00e8res. Une myofibrille n'est qu'un des organites contractiles \u00e0 l'int\u00e9rieur de cette cellule, pas la cellule elle-m\u00eame : ne pas confondre le contenant (la fibre) et son contenu (la myofibrille).", "slide": 120}, {"titre": "L'endomysium et le sarcolemme entourent tous deux la fibre, mais ne sont pas la m\u00eame chose", "texte": "L'endomysium est le tissu CONJONCTIF qui enveloppe une fibre musculaire, comme l'\u00e9pimysium enveloppe le muscle entier et le p\u00e9rimysium un faisceau. Le sarcolemme est une membrane DIFF\u00c9RENTE, propre \u00e0 la fibre elle-m\u00eame : le cours le pr\u00e9sente comme une DEUXI\u00c8ME membrane, en plus de l'endomysium.", "slide": 117}, {"titre": "Excitabilit\u00e9 et contractilit\u00e9 ne d\u00e9finissent pas la m\u00eame chose", "texte": "L'excitabilit\u00e9, c'est la capacit\u00e9 du muscle \u00e0 R\u00c9AGIR (par la contraction) \u00e0 une excitation port\u00e9e sur lui. La contractilit\u00e9, c'est la capacit\u00e9 du muscle \u00e0 SE RACCOURCIR, donc \u00e0 g\u00e9n\u00e9rer le mouvement. La premi\u00e8re d\u00e9crit une r\u00e9ponse \u00e0 un stimulus, la seconde le m\u00e9canisme m\u00e9canique de cette r\u00e9ponse : deux propri\u00e9t\u00e9s distinctes, faciles \u00e0 confondre.", "slide": 123}, {"titre": "Le temps de rel\u00e2chement est plus LONG que le temps de contraction, pas l'inverse", "texte": "Sur la secousse musculaire, l'intuition inverse souvent l'ordre : c'est le temps de REL\u00c2CHEMENT (d\u00e9contraction) qui est le plus long des deux, le muscle reprenant progressivement sa longueur initiale \u2014 contrairement au temps de contraction, plus bref.", "slide": 127}], "planches": [{"id": "enveloppes-muscle-coupe", "titre": "Les enveloppes du muscle, en coupe", "vb": "0 0 320 280", "dessin": "<circle cx='150' cy='140' r='115' fill='none' stroke='currentColor' stroke-width='3'/><circle cx='150' cy='140' r='78' fill='none' stroke='currentColor' stroke-width='2' stroke-dasharray='8 5'/><circle cx='150' cy='140' r='44' fill='none' stroke='currentColor' stroke-width='1.4' stroke-dasharray='3 3'/><circle cx='150' cy='140' r='36' fill='none' stroke='currentColor' stroke-width='1.6'/><g fill='currentColor' stroke='none'><circle cx='138' cy='128' r='1.6'/><circle cx='150' cy='122' r='1.6'/><circle cx='162' cy='128' r='1.6'/><circle cx='144' cy='140' r='1.6'/><circle cx='156' cy='140' r='1.6'/><circle cx='168' cy='138' r='1.6'/><circle cx='132' cy='148' r='1.6'/><circle cx='150' cy='152' r='1.6'/><circle cx='168' cy='150' r='1.6'/><circle cx='140' cy='162' r='1.6'/><circle cx='158' cy='164' r='1.6'/><circle cx='126' cy='138' r='1.6'/><circle cx='174' cy='144' r='1.6'/><circle cx='146' cy='116' r='1.6'/></g>", "pastilles": [{"n": 1, "x": 231, "y": 59, "t": "\u00c9pimysium", "ancre": "start", "indice": "gaine externe, autour du muscle entier"}, {"n": 2, "x": 205, "y": 195, "t": "P\u00e9rimysium", "ancre": "start", "indice": "autour d'un faisceau musculaire"}, {"n": 3, "x": 119, "y": 171, "t": "Endomysium", "ancre": "end", "indice": "autour d'une fibre musculaire"}, {"n": 4, "x": 125, "y": 115, "t": "Sarcolemme", "ancre": "end", "indice": "deuxi\u00e8me membrane, propre \u00e0 la fibre"}], "slide": 117}, {"id": "sarcomere-stries-z", "titre": "Le sarcom\u00e8re, entre deux stries Z", "vb": "0 0 300 180", "dessin": "<g fill='none' stroke='currentColor' stroke-linecap='round'><path d='M25,65 L140,65' stroke-width='1.6'/><path d='M110,65 L190,65' stroke-width='7'/><path d='M160,65 L275,65' stroke-width='1.6'/><path d='M25,90 L140,90' stroke-width='1.6'/><path d='M110,90 L190,90' stroke-width='7'/><path d='M160,90 L275,90' stroke-width='1.6'/><path d='M25,115 L140,115' stroke-width='1.6'/><path d='M110,115 L190,115' stroke-width='7'/><path d='M160,115 L275,115' stroke-width='1.6'/><path d='M25,140 L140,140' stroke-width='1.6'/><path d='M110,140 L190,140' stroke-width='7'/><path d='M160,140 L275,140' stroke-width='1.6'/></g><path d='M25,45 L25,155' stroke='currentColor' stroke-width='5' fill='none'/><path d='M275,45 L275,155' stroke='currentColor' stroke-width='5' fill='none'/><path d='M25,35 L25,45 M25,35 L275,35 M275,35 L275,45' stroke='currentColor' stroke-width='1.2' fill='none'/><g stroke='currentColor' stroke-width='1.2' fill='none'><path d='M70,66 L70,80'/><path d='M150,91 L150,102'/></g>", "pastilles": [{"n": 1, "x": 150, "y": 35, "t": "Sarcom\u00e8re", "ancre": "start", "indice": "segment de myofibrille entre deux stries Z"}, {"n": 2, "x": 25, "y": 50, "t": "Strie Z", "ancre": "start", "indice": "ligne qui d\u00e9limite chaque sarcom\u00e8re"}, {"n": 3, "x": 150, "y": 102, "t": "Myosine (\u00e9pais)", "ancre": "end", "indice": "au centre du sarcom\u00e8re"}, {"n": 4, "x": 70, "y": 80, "t": "Actine (filament fin)", "ancre": "start", "indice": "part de chaque strie Z vers le centre"}], "slide": 119}], "muscles": []}, {"num": 5, "titre": "Le tronc", "slides": [136, 189], "sections": [{"titre": "Organisation g\u00e9n\u00e9rale du rachis : colonne mobile et colonne fixe", "slide": 139, "points": ["Le rachis est le support de la bo\u00eete cr\u00e2nienne et s'\u00e9tend jusqu'au coccyx.", "Colonne vert\u00e9brale MOBILE (24 vert\u00e8bres) : 7 cervicales (C1 \u00e0 C7 ; C1 = Atlas, C2 = Axis), 12 thoraciques (T1 \u00e0 T12), 5 lombaires (L1 \u00e0 L5).", "Colonne vert\u00e9brale FIXE : le sacrum (5 vert\u00e8bres sacr\u00e9es soud\u00e9es) et le coccyx (4 vert\u00e8bres coccygiennes soud\u00e9es)."]}, {"titre": "R\u00f4le et croissance du rachis", "slide": 140, "points": ["Le rachis est le pilier du corps, \u00e0 la fois mobile et rigide ; de nombreux muscles s'y ins\u00e8rent pour des fonctions posturales et motrices.", "La colonne vert\u00e9brale fait partie du squelette axial, sur lequel se fixe le squelette appendiculaire.", "Le volume des vert\u00e8bres augmente progressivement de la r\u00e9gion cervicale \u00e0 la r\u00e9gion lombaire, en raison de l'augmentation des contraintes."]}, {"titre": "Les 4 courbures du rachis", "slide": 142, "points": ["Le rachis est rectiligne dans le plan frontal.", "Dans le plan sagittal, il pr\u00e9sente 4 courbures qui s'encha\u00eenent de haut en bas : lordose cervicale, cyphose dorsale, lordose lombaire, courbure sacro-coccygienne."]}, {"titre": "D\u00e9formations pathologiques du rachis", "slide": 143, "points": ["Dans le plan frontal : la scoliose est une d\u00e9formation lat\u00e9rale du rachis, en C ou en S.", "Dans le plan sagittal : la cypho-lordose associe une augmentation de la cyphose dorsale et de la lordose lombaire ; on parle aussi d'hypercyphose ou d'hyperlordose isol\u00e9es."]}, {"titre": "La vert\u00e8bre : corps et arc post\u00e9rieur", "slide": 145, "points": ["Une vert\u00e8bre est form\u00e9e de 2 parties principales : le corps vert\u00e9bral (partie ant\u00e9rieure) et l'arc post\u00e9rieur (partie post\u00e9rieure).", "Le canal rachidien, d\u00e9limit\u00e9 par ces deux parties, est le passage de la moelle \u00e9pini\u00e8re."]}, {"titre": "Le corps vert\u00e9bral", "slide": 146, "points": ["De forme cylindrique, il pr\u00e9sente deux faces (sup\u00e9rieure et inf\u00e9rieure) appel\u00e9es plateaux vert\u00e9braux, recouverts de cartilage hyalin (amphiarthrose).", "Ces plateaux vert\u00e9braux s'articulent entre eux par l'interm\u00e9diaire des disques intervert\u00e9braux (DIV)."]}, {"titre": "L'arc post\u00e9rieur et ses processus", "slide": 147, "points": ["L'arc post\u00e9rieur comprend : 2 p\u00e9dicules (passage des nerfs rachidiens), 4 processus (apophyses) articulaires (qui s'articulent avec les processus articulaires des vert\u00e8bres sus- et sous-jacentes), 2 processus transverses, 2 lames et 1 processus \u00e9pineux."]}, {"titre": "Ligaments vert\u00e9braux : syst\u00e8me ant\u00e9rieur", "slide": 148, "points": ["Les vert\u00e8bres sont maintenues entre elles par des ligaments vert\u00e9braux communs.", "Le ligament longitudinal ant\u00e9rieur commence au niveau de l'os occipital et de l'atlas (C1) ; il descend le long des faces ant\u00e9rieures des corps vert\u00e9braux jusqu'au sacrum.", "Le ligament longitudinal post\u00e9rieur d\u00e9bute au niveau de l'axis (C2) ; il descend le long des faces post\u00e9rieures des corps vert\u00e9braux et se termine au niveau du sacrum."]}, {"titre": "Ligaments vert\u00e9braux : syst\u00e8me post\u00e9rieur", "slide": 149, "points": ["Sur l'arc post\u00e9rieur : le ligament jaune (entre 2 lames), le ligament inter-\u00e9pineux (entre 2 processus \u00e9pineux), le ligament supra-\u00e9pineux (qui rejoint le sommet de tous les processus \u00e9pineux), le ligament inter-transverse (entre 2 processus transverses) et le ligament capsulaire (entre 2 processus articulaires)."]}, {"titre": "Composition du disque intervert\u00e9bral", "slide": 151, "points": ["Une partie p\u00e9riph\u00e9rique dure, l'anneau fibreux, compos\u00e9e de lamelles concentriques de fibrocartilage.", "Une partie centrale molle, le nucleus pulposus (noyau pulpeux) : une zone hydrat\u00e9e form\u00e9e de liquide g\u00e9latineux."]}, {"titre": "\u00c9paisseur et nombre des disques intervert\u00e9braux", "slide": 152, "points": ["L'\u00e9paisseur des DIV augmente \u00e0 mesure que l'on descend le long du rachis : environ 3 mm au niveau cervical, 5 mm au niveau dorsal, 9 mm au niveau lombaire.", "La colonne vert\u00e9brale comporte 23 DIV (il n'y en a pas entre l'occiput et l'atlas)."]}, {"titre": "Fonctions et contraintes du disque intervert\u00e9bral", "slide": 153, "points": ["Le DIV a un r\u00f4le articulaire (mobilit\u00e9) et un r\u00f4le d'amortisseur de pression.", "En statique ou en mouvement, le DIV est en permanence soumis \u00e0 des contraintes de pression : les pincements et les cisaillements le traumatisent."]}, {"titre": "Le m\u00e9canisme de la hernie discale", "slide": 154, "points": ["Le DIV est un amortisseur fibro-hydraulique qui ne fonctionne parfaitement que s'il est \u00e9tanche ; de mauvaises conditions m\u00e9caniques (mauvais placement du dos) le font vieillir pr\u00e9matur\u00e9ment.", "Des contraintes r\u00e9p\u00e9t\u00e9es et inappropri\u00e9es engendrent progressivement une rupture de l'anneau fibreux, puis un glissement du liquide contenu dans le noyau : c'est la hernie discale.", "Ce glissement g\u00e9n\u00e8re une compression des \u00e9l\u00e9ments nerveux contenus dans le canal rachidien, d'o\u00f9 des douleurs invalidantes."]}, {"titre": "Les mouvements du rachis", "slide": 156, "points": ["Le rachis permet l'inclinaison lat\u00e9rale, la rotation, la flexion et l'extension."]}, {"titre": "Les c\u00f4tes : vraies c\u00f4tes et c\u00f4tes flottantes", "slide": 161, "points": ["La cage thoracique se compose de 12 paires de c\u00f4tes, qui partent toutes des bords lat\u00e9raux des corps vert\u00e9braux.", "Les 10 premi\u00e8res paires s'unissent au sternum par l'interm\u00e9diaire des cartilages costaux : ce sont les vraies c\u00f4tes.", "Les paires 11 et 12 se terminent avant d'arriver au sternum : ce sont les c\u00f4tes flottantes."]}, {"titre": "Le sternum", "slide": 164, "points": ["Os plat, situ\u00e9 \u00e0 la face ant\u00e9rieure du thorax.", "Il comprend 3 parties : le manubrium, le corps, le processus xipho\u00efde."]}, {"titre": "R\u00f4les des muscles du tronc", "slide": 168, "points": ["Les muscles du tronc ont \u00e0 la fois un r\u00f4le moteur et un r\u00f4le stabilisateur du rachis.", "Les muscles dorsaux sont extenseurs, et les muscles ventraux sont fl\u00e9chisseurs : s'ils se contractent en synergie, leurs actions s'annulent en renfor\u00e7ant consid\u00e9rablement la rigidit\u00e9 rachidienne."]}, {"titre": "Les muscles profonds du dos", "slide": 171, "points": ["Le dentel\u00e9 post\u00e9rieur (sup\u00e9rieur et inf\u00e9rieur), les spl\u00e9nius (de la t\u00eate et du cou), les \u00e9recteurs du rachis (iliocostal, longissimus, \u00e9pineux), les transverso-\u00e9pineux (semi-\u00e9pineux, multifides, rotateurs du rachis), les inter\u00e9pineux et intertransversaires, les \u00e9l\u00e9vateurs des c\u00f4tes."]}, {"titre": "Actions des muscles profonds du dos", "slide": 173, "points": ["Par leur tonus, les muscles profonds du dos assurent l'\u00e9quilibre de la t\u00eate et du tronc pendant la station \u00e9rig\u00e9e et la marche.", "Contraction bilat\u00e9rale : extension de la colonne vert\u00e9brale (et de la t\u00eate). Contraction unilat\u00e9rale : inclinaison lat\u00e9rale et rotation du rachis (et de la t\u00eate).", "Les \u00e9l\u00e9vateurs des c\u00f4tes sont inspirateurs."]}, {"titre": "Les muscles superficiels du dos", "slide": 175, "points": ["Trap\u00e8ze, grand dorsal, \u00e9l\u00e9vateur de la scapula, petit rhombo\u00efde, grand rhombo\u00efde.", "D\u00e9taill\u00e9s dans le cours du membre sup\u00e9rieur : le cours du tronc se contente ici de les nommer, sans donner leur origine ni leur terminaison."]}, {"titre": "Le carr\u00e9 des lombes", "slide": 179, "points": ["Origine : la derni\u00e8re c\u00f4te.", "Terminaison : la cr\u00eate iliaque et les processus transverses de L1 \u00e0 L5.", "Action : inclinateur du tronc."]}, {"titre": "L'ilio-psoas", "slide": 180, "points": ["Compos\u00e9 de 2 faisceaux : le grand psoas (muscle lat\u00e9ral du tronc) et l'iliaque (muscle de la hanche).", "Origine (grand psoas) : processus transverses de L1 \u00e0 L5, corps vert\u00e9braux de T12 \u00e0 L5. Terminaison : le petit trochanter du f\u00e9mur.", "Il est fl\u00e9chisseur de la cuisse."]}, {"titre": "Rep\u00e8res de la paroi abdominale", "slide": 184, "points": ["La ligne blanche relie le processus xipho\u00efde du sternum au pubis ; les intersections tendineuses segmentent le droit de l'abdomen.", "Le ligament inguinal est form\u00e9 par le bord inf\u00e9rieur libre de l'apon\u00e9vrose de l'oblique externe."]}, {"titre": "Le transverse de l'abdomen", "slide": 185, "points": ["Muscle le plus profond de la paroi abdominale.", "Origine : face profonde des c\u00f4tes 7 \u00e0 12, processus transverses de L1 \u00e0 L5, cr\u00eate iliaque. Terminaison : par une apon\u00e9vrose jusqu'\u00e0 la ligne blanche (du processus xipho\u00efde du sternum jusqu'au pubis).", "Orientation des fibres : transversale (horizontale). Action : expirateur (permet de rentrer le ventre)."]}, {"titre": "L'oblique interne (petit oblique)", "slide": 186, "points": ["Origine : cr\u00eate iliaque, apon\u00e9vrose lombale. Terminaison : c\u00f4tes 9 \u00e0 12, et par une apon\u00e9vrose jusqu'\u00e0 la ligne blanche.", "Orientation des fibres : en \u00e9ventail vers le haut.", "Action : rotateur et inclinateur du tronc, du c\u00f4t\u00e9 contract\u00e9."]}, {"titre": "L'oblique externe (grand oblique)", "slide": 187, "points": ["Origine : c\u00f4tes 6 \u00e0 12. Terminaison : cr\u00eate iliaque, et par une apon\u00e9vrose jusqu'\u00e0 la ligne blanche.", "Orientation des fibres : oblique vers le bas.", "Contraction bilat\u00e9rale : flexion du tronc. Contraction unilat\u00e9rale : rotateur du tronc, du c\u00f4t\u00e9 oppos\u00e9 \u00e0 la contraction."]}, {"titre": "Le droit de l'abdomen (grand droit)", "slide": 188, "points": ["S'\u00e9tend verticalement de part et d'autre de la ligne blanche.", "Origine : c\u00f4tes 5 \u00e0 7, processus xipho\u00efde. Terminaison : le pubis.", "Orientation des fibres : verticale vers le bas. Action : fl\u00e9chisseur du tronc."]}], "cartes": [{"id": "c5-01", "q": "Combien de vert\u00e8bres composent la colonne vert\u00e9brale MOBILE, comment se r\u00e9partissent-elles, et quels noms particuliers portent C1 et C2 ?", "r": "24 vert\u00e8bres : 7 cervicales (C1 \u00e0 C7), 12 thoraciques (T1 \u00e0 T12), 5 lombaires (L1 \u00e0 L5) ; C1 est l'Atlas, C2 est l'Axis.", "slide": 139}, {"id": "c5-02", "q": "Qu'est-ce que la colonne vert\u00e9brale FIXE, et de combien de vert\u00e8bres soud\u00e9es se compose-t-elle ?", "r": "Le sacrum (5 vert\u00e8bres sacr\u00e9es soud\u00e9es) et le coccyx (4 vert\u00e8bres coccygiennes soud\u00e9es).", "slide": 139}, {"id": "c5-03", "q": "\u00c0 quel ensemble squelettique le rachis appartient-il, et comment son volume \u00e9volue-t-il le long de la colonne ?", "r": "Il fait partie du squelette axial, sur lequel se fixe le squelette appendiculaire ; le volume des vert\u00e8bres augmente progressivement de la r\u00e9gion cervicale \u00e0 la r\u00e9gion lombaire, avec l'augmentation des contraintes.", "slide": 140}, {"id": "c5-04", "q": "Dans quel plan le rachis est-il rectiligne, et quelles sont ses 4 courbures dans le plan sagittal, de haut en bas ?", "r": "Rectiligne dans le plan frontal. Dans le plan sagittal, de haut en bas : lordose cervicale, cyphose dorsale, lordose lombaire, courbure sacro-coccygienne.", "slide": 142}, {"id": "c5-05", "q": "Qu'est-ce qu'une scoliose ?", "r": "Une d\u00e9formation lat\u00e9rale du rachis, en C ou en S, observ\u00e9e dans le plan frontal.", "slide": 143, "plan": "frontal"}, {"id": "c5-06", "q": "Que d\u00e9signe une cypho-lordose ?", "r": "Une augmentation associ\u00e9e de la cyphose dorsale et de la lordose lombaire, dans le plan sagittal.", "slide": 143, "plan": "sagittal"}, {"id": "c5-07", "q": "Quelles sont les 2 parties principales d'une vert\u00e8bre, et qu'est-ce qu'elles d\u00e9limitent ensemble ?", "r": "Le corps vert\u00e9bral (partie ant\u00e9rieure) et l'arc post\u00e9rieur (partie post\u00e9rieure) ; ensemble, ils d\u00e9limitent le canal rachidien, passage de la moelle \u00e9pini\u00e8re.", "slide": 145}, {"id": "c5-08", "q": "Comment s'appellent les 2 faces du corps vert\u00e9bral, et par quoi sont-elles recouvertes ?", "r": "Les plateaux vert\u00e9braux, recouverts de cartilage hyalin (amphiarthrose) ; ils s'articulent entre eux par l'interm\u00e9diaire des disques intervert\u00e9braux.", "slide": 146}, {"id": "c5-09", "q": "Quels 5 \u00e9l\u00e9ments composent l'arc post\u00e9rieur d'une vert\u00e8bre ?", "r": "2 p\u00e9dicules, 4 processus articulaires, 2 processus transverses, 2 lames, 1 processus \u00e9pineux.", "slide": 147}, {"id": "c5-10", "q": "O\u00f9 commencent et se terminent les ligaments longitudinaux ant\u00e9rieur et post\u00e9rieur de la colonne ?", "r": "Le ligament longitudinal ant\u00e9rieur va de l'occiput / l'atlas (C1) jusqu'au sacrum ; le ligament longitudinal post\u00e9rieur va de l'axis (C2) jusqu'au sacrum.", "slide": 148}, {"id": "c5-11", "q": "Quelles sont les 2 parties du disque intervert\u00e9bral, et leur consistance respective ?", "r": "L'anneau fibreux : dur, p\u00e9riph\u00e9rique, fait de lamelles concentriques de fibrocartilage. Le nucleus pulposus (noyau pulpeux) : mou, central, liquide g\u00e9latineux hydrat\u00e9.", "slide": 151}, {"id": "c5-12", "q": "Combien de disques intervert\u00e9braux compte la colonne vert\u00e9brale, et \u00e0 quel niveau n'y en a-t-il pas ?", "r": "23 disques intervert\u00e9braux ; il n'y en a pas entre l'occiput et l'atlas.", "slide": 152}, {"id": "c5-13", "q": "Par quel m\u00e9canisme se forme une hernie discale, \u00e0 partir de quel r\u00f4le normal du disque intervert\u00e9bral ?", "r": "Le DIV amortit les pressions ; des contraintes r\u00e9p\u00e9t\u00e9es et inappropri\u00e9es rompent progressivement son anneau fibreux, ce qui provoque un glissement du liquide du noyau \u2014 ce glissement comprime les \u00e9l\u00e9ments nerveux du canal rachidien.", "slide": 154}, {"id": "c5-14", "q": "Quels sont les 4 mouvements possibles du rachis ?", "r": "L'inclinaison lat\u00e9rale, la rotation, la flexion et l'extension.", "slide": 156}, {"id": "c5-15", "q": "Que distingue-t-on entre les c\u00f4tes 1 \u00e0 10 et les c\u00f4tes 11 et 12 ?", "r": "Les c\u00f4tes 1 \u00e0 10 (vraies c\u00f4tes) s'unissent au sternum par l'interm\u00e9diaire des cartilages costaux ; les c\u00f4tes 11 et 12 (c\u00f4tes flottantes) se terminent avant d'atteindre le sternum.", "slide": 161}, {"id": "c5-16", "q": "Quelles sont les 3 parties du sternum ?", "r": "Le manubrium, le corps, le processus xipho\u00efde.", "slide": 164}, {"id": "c5-17", "q": "Que se passe-t-il quand les muscles dorsaux et les muscles ventraux du tronc se contractent en synergie ?", "r": "Leurs actions oppos\u00e9es (extension c\u00f4t\u00e9 dorsal, flexion c\u00f4t\u00e9 ventral) s'annulent, ce qui renforce consid\u00e9rablement la rigidit\u00e9 du rachis.", "slide": 168}, {"id": "c5-18", "q": "Nommez les 6 groupes de muscles profonds du dos.", "r": "Le dentel\u00e9 post\u00e9rieur, les spl\u00e9nius, les \u00e9recteurs du rachis, les transverso-\u00e9pineux, les inter\u00e9pineux et intertransversaires, les \u00e9l\u00e9vateurs des c\u00f4tes.", "slide": 171}, {"id": "c5-19", "q": "Quelle action produit une contraction bilat\u00e9rale des muscles profonds du dos, et quelle action produit une contraction unilat\u00e9rale ?", "r": "Bilat\u00e9rale : extension de la colonne vert\u00e9brale (et de la t\u00eate). Unilat\u00e9rale : inclinaison lat\u00e9rale et rotation du rachis (et de la t\u00eate).", "slide": 173}, {"id": "c5-20", "q": "Quels 2 faisceaux composent l'ilio-psoas, et lequel des deux est un muscle du tronc ?", "r": "Le grand psoas (muscle lat\u00e9ral du tronc) et l'iliaque (muscle de la hanche) ; seul le grand psoas est un muscle du tronc, l'iliaque est un muscle de la hanche.", "slide": 180}, {"id": "c5-21", "q": "Pourquoi le transverse de l'abdomen est-il qualifi\u00e9 de muscle 'le plus profond' de la paroi abdominale, et quelle est l'orientation de ses fibres ?", "r": "C'est la couche musculaire la plus interne de la paroi abdominale ; ses fibres sont orient\u00e9es transversalement (horizontalement).", "slide": 185}, {"id": "c5-22", "q": "Pourquoi une contraction unilat\u00e9rale de l'oblique interne tourne le tronc du c\u00f4t\u00e9 contract\u00e9, alors que l'oblique externe le tourne du c\u00f4t\u00e9 oppos\u00e9 ?", "r": "Leurs fibres ont des orientations oppos\u00e9es : en \u00e9ventail vers le haut pour l'oblique interne, oblique vers le bas pour l'oblique externe \u2014 cette diff\u00e9rence d'orientation inverse le sens de rotation produit par chaque muscle.", "slide": 187}, {"id": "c5-23", "q": "Quelle est l'orientation des fibres du droit de l'abdomen, et quelle est son action ?", "r": "Verticale, vers le bas ; il est fl\u00e9chisseur du tronc.", "slide": 188}], "quiz": [{"id": "q5-01", "q": "Combien de vert\u00e8bres composent la colonne vert\u00e9brale MOBILE ?", "choix": ["19", "22", "24", "29"], "bonne": 2, "expl": "24 vert\u00e8bres mobiles : 7 cervicales + 12 thoraciques + 5 lombaires. Le sacrum (5) et le coccyx (4) sont soud\u00e9s : ils forment la colonne FIXE, pas la colonne mobile.", "slide": 139}, {"id": "q5-02", "q": "C1 et C2 portent des noms particuliers. Dans quel ordre ?", "choix": ["Atlas puis Axis", "Axis puis Atlas", "Atlas puis Odonto\u00efde", "Axis puis Sacrum"], "bonne": 0, "expl": "C1 est l'Atlas (qui porte le cr\u00e2ne), C2 est l'Axis (autour duquel l'Atlas pivote). 'Odonto\u00efde' et 'Sacrum' ne sont pas des noms de vert\u00e8bres cervicales.", "slide": 139}, {"id": "q5-03", "q": "Quelle courbure occupe la r\u00e9gion thoracique (dorsale) du rachis ?", "choix": ["Cyphose dorsale", "Lordose dorsale", "Scoliose dorsale", "Courbure sacro-coccygienne"], "bonne": 0, "expl": "La r\u00e9gion dorsale porte une cyphose (convexit\u00e9 post\u00e9rieure). Les lordoses sont cervicale et lombaire ; la scoliose est une d\u00e9formation pathologique, pas une courbure normale ; la courbure sacro-coccygienne est plus bas.", "slide": 142, "plan": "sagittal"}, {"id": "q5-04", "q": "Dans le plan frontal, une d\u00e9viation lat\u00e9rale du rachis en C ou en S s'appelle...", "choix": ["une scoliose", "une cypho-lordose", "une hyperlordose", "une hypercyphose"], "bonne": 0, "expl": "La scoliose est la d\u00e9formation du plan frontal. La cypho-lordose, l'hyperlordose et l'hypercyphose sont des d\u00e9formations du plan SAGITTAL.", "slide": 143, "plan": "frontal"}, {"id": "q5-05", "q": "Combien de processus (apophyses) articulaires compte l'arc post\u00e9rieur d'une vert\u00e8bre ?", "choix": ["2", "4", "6", "1"], "bonne": 1, "expl": "4 processus articulaires (2 sup\u00e9rieurs, 2 inf\u00e9rieurs), qui s'articulent avec les vert\u00e8bres sus- et sous-jacentes. Il y a 2 p\u00e9dicules et 1 seul processus \u00e9pineux : ne pas confondre les comptes.", "slide": 147}, {"id": "q5-06", "q": "Quel ligament relie deux lames vert\u00e9brales cons\u00e9cutives ?", "choix": ["le ligament jaune", "le ligament inter-\u00e9pineux", "le ligament supra-\u00e9pineux", "le ligament inter-transverse"], "bonne": 0, "expl": "Le ligament jaune relie 2 lames. L'inter-\u00e9pineux relie 2 processus \u00e9pineux, le supra-\u00e9pineux rejoint le sommet de tous les processus \u00e9pineux, l'inter-transverse relie 2 processus transverses.", "slide": 149}, {"id": "q5-07", "q": "Quelle est la partie centrale et molle du disque intervert\u00e9bral ?", "choix": ["le nucleus pulposus (noyau pulpeux)", "l'anneau fibreux", "le plateau vert\u00e9bral", "le ligament capsulaire"], "bonne": 0, "expl": "Le nucleus pulposus est la zone hydrat\u00e9e centrale. L'anneau fibreux est la partie p\u00e9riph\u00e9rique et DURE ; le plateau vert\u00e9bral appartient au corps vert\u00e9bral ; le ligament capsulaire relie des processus articulaires.", "slide": 151}, {"id": "q5-08", "q": "Entre quels deux niveaux ne trouve-t-on PAS de disque intervert\u00e9bral ?", "choix": ["l'occiput et l'atlas", "l'atlas et l'axis", "L5 et le sacrum", "T12 et L1"], "bonne": 0, "expl": "Sur les 24 interlignes du rachis mobile, seul celui entre l'occiput et l'atlas (C1) n'a pas de DIV \u2014 d'o\u00f9 les 23 DIV compt\u00e9s par le cours.", "slide": 152}, {"id": "q5-09", "q": "Quelles c\u00f4tes sont dites 'flottantes' ?", "choix": ["les c\u00f4tes 11 et 12", "les c\u00f4tes 1 et 2", "les c\u00f4tes 8 \u00e0 10", "les c\u00f4tes 6 et 7"], "bonne": 0, "expl": "Les c\u00f4tes 11 et 12 se terminent avant d'atteindre le sternum : ce sont les c\u00f4tes flottantes. Les c\u00f4tes 1 \u00e0 10 sont les vraies c\u00f4tes, unies au sternum par un cartilage costal.", "slide": 161}, {"id": "q5-10", "q": "Quelle est l'orientation des fibres du transverse de l'abdomen ?", "choix": ["transversale (horizontale)", "verticale", "oblique vers le bas", "en \u00e9ventail vers le haut"], "bonne": 0, "expl": "Le transverse doit son nom \u00e0 ses fibres transversales (horizontales). Verticale = droit de l'abdomen ; oblique vers le bas = oblique externe ; \u00e9ventail vers le haut = oblique interne.", "slide": 185}, {"id": "q5-11", "q": "Une contraction UNILAT\u00c9RALE de l'oblique INTERNE fait tourner le tronc...", "choix": ["du c\u00f4t\u00e9 contract\u00e9", "du c\u00f4t\u00e9 oppos\u00e9 \u00e0 la contraction", "il n'y a pas de rotation, seulement une inclinaison", "dans les deux sens \u00e0 la fois"], "bonne": 0, "expl": "L'oblique interne (fibres en \u00e9ventail vers le haut) tourne le tronc du c\u00f4t\u00e9 CONTRACT\u00c9. C'est l'oblique externe qui tourne du c\u00f4t\u00e9 oppos\u00e9 : les deux muscles ont des effets de rotation oppos\u00e9s.", "slide": 186}, {"id": "q5-12", "q": "Une contraction UNILAT\u00c9RALE de l'oblique EXTERNE fait tourner le tronc...", "choix": ["du c\u00f4t\u00e9 oppos\u00e9 \u00e0 la contraction", "du c\u00f4t\u00e9 contract\u00e9", "il n'y a pas de rotation possible", "uniquement en extension"], "bonne": 0, "expl": "L'oblique externe (fibres obliques vers le bas) tourne le tronc du c\u00f4t\u00e9 OPPOS\u00c9 \u00e0 la contraction \u2014 l'inverse de l'oblique interne. En bilat\u00e9ral, il fl\u00e9chit le tronc.", "slide": 187}], "muscles": [{"nom": "Carr\u00e9 des lombes", "origine": ["derni\u00e8re c\u00f4te"], "terminaison": ["cr\u00eate iliaque", "processus transverses de L1 \u00e0 L5"], "actions": ["inclinateur du tronc"], "slide": 179}, {"nom": "Ilio-psoas", "origine": ["processus transverses de L1 \u00e0 L5", "corps vert\u00e9braux de T12 \u00e0 L5"], "terminaison": ["petit trochanter du f\u00e9mur"], "actions": ["fl\u00e9chisseur de la cuisse"], "slide": 180}, {"nom": "Transverse de l'abdomen", "origine": ["face profonde des c\u00f4tes 7 \u00e0 12", "processus transverses de L1 \u00e0 L5", "cr\u00eate iliaque"], "terminaison": ["ligne blanche, par une apon\u00e9vrose (du processus xipho\u00efde au pubis)"], "actions": ["expirateur (rentre le ventre)"], "slide": 185}, {"nom": "Oblique interne", "origine": ["cr\u00eate iliaque", "apon\u00e9vrose lombale"], "terminaison": ["c\u00f4tes 9 \u00e0 12", "ligne blanche, par une apon\u00e9vrose"], "actions": ["rotateur et inclinateur du tronc, du c\u00f4t\u00e9 contract\u00e9"], "slide": 186}, {"nom": "Oblique externe", "origine": ["c\u00f4tes 6 \u00e0 12"], "terminaison": ["cr\u00eate iliaque", "ligne blanche, par une apon\u00e9vrose"], "actions": ["flexion du tronc (contraction bilat\u00e9rale)", "rotateur du tronc, du c\u00f4t\u00e9 oppos\u00e9 \u00e0 la contraction (contraction unilat\u00e9rale)"], "slide": 187}, {"nom": "Droit de l'abdomen", "origine": ["c\u00f4tes 5 \u00e0 7", "processus xipho\u00efde"], "terminaison": ["pubis"], "actions": ["fl\u00e9chisseur du tronc"], "slide": 188}], "pieges": [{"titre": "L'oblique interne tourne du c\u00f4t\u00e9 contract\u00e9, l'oblique externe du c\u00f4t\u00e9 oppos\u00e9", "texte": "Les deux muscles obliques ont des actions de rotation OPPOS\u00c9ES en contraction unilat\u00e9rale, \u00e0 cause de l'orientation oppos\u00e9e de leurs fibres. L'oblique INTERNE (fibres en \u00e9ventail vers le haut) fait tourner le tronc du c\u00f4t\u00e9 CONTRACT\u00c9. L'oblique EXTERNE (fibres obliques vers le bas) le fait tourner du c\u00f4t\u00e9 OPPOS\u00c9 \u00e0 la contraction. C'est la confusion la plus fr\u00e9quente sur ce chapitre : v\u00e9rifier syst\u00e9matiquement lequel des deux muscles est en jeu avant de r\u00e9pondre.", "slide": 187}, {"titre": "L'ilio-psoas n'est pas un muscle unique", "texte": "Le cours pr\u00e9sente l'ilio-psoas comme compos\u00e9 de 2 faisceaux aux origines diff\u00e9rentes : le grand psoas (muscle lat\u00e9ral du TRONC, origine vert\u00e9brale : processus transverses L1-L5 et corps vert\u00e9braux T12-L5) et l'iliaque (muscle de la HANCHE, dont l'origine iliaque n'est pas d\u00e9taill\u00e9e sur cette diapositive). L'origine, la terminaison et l'action donn\u00e9es par le cours (petit trochanter du f\u00e9mur, fl\u00e9chisseur de la cuisse) concernent sp\u00e9cifiquement le grand psoas, pas le faisceau iliaque.", "slide": 180}, {"titre": "Ce cours ne distingue que 2 cat\u00e9gories de c\u00f4tes, pas 3", "texte": "Contrairement \u00e0 une classification plus d\u00e9taill\u00e9e (vraies / fausses / flottantes) parfois enseign\u00e9e ailleurs, ce cours ne retient que 2 cat\u00e9gories : les vraies c\u00f4tes (c\u00f4tes 1 \u00e0 10, unies au sternum par l'interm\u00e9diaire des cartilages costaux) et les c\u00f4tes flottantes (c\u00f4tes 11 et 12, qui ne rejoignent pas le sternum). Ne pas ajouter de cat\u00e9gorie interm\u00e9diaire absente de ce cours.", "slide": 161}, {"titre": "Il n'y a pas de disque intervert\u00e9bral \u00e0 chaque interligne", "texte": "La colonne vert\u00e9brale compte 23 disques intervert\u00e9braux, pas un \u00e0 chaque interligne du rachis mobile : il n'y en a PAS entre l'occiput et l'atlas (C1), le seul niveau qui en soit d\u00e9pourvu.", "slide": 152}], "planches": [{"id": "rachis-courbures-regions", "titre": "Les 4 courbures du rachis, de haut en bas", "vb": "0 0 280 560", "dessin": "<g fill='none' stroke='currentColor'><circle cx='140' cy='18' r='7' stroke-width='2'/><path d='M140,25 C180,55 180,120 140,150 C100,180 100,245 140,275 C180,305 180,370 140,400 C100,430 100,495 122,525 L127,543' stroke-width='5' stroke-linecap='round'/><path d='M40,150 L235,150 M40,275 L235,275 M40,400 L235,400' stroke-width='1' stroke-dasharray='4 4'/></g>", "pastilles": [{"n": 1, "x": 172, "y": 90, "t": "Lordose cervicale", "ancre": "middle", "indice": "1re bosse, convexit\u00e9 ant\u00e9rieure"}, {"n": 2, "x": 108, "y": 215, "t": "Cyphose dorsale", "ancre": "middle", "indice": "2e bosse, convexit\u00e9 post\u00e9rieure"}, {"n": 3, "x": 172, "y": 340, "t": "Lordose lombaire", "ancre": "middle", "indice": "3e bosse, convexit\u00e9 ant\u00e9rieure"}, {"n": 4, "x": 108, "y": 465, "t": "Courbure sacro-coccygienne", "ancre": "middle", "indice": "4e bosse ; sacrum et coccyx soud\u00e9s"}], "slide": 142}, {"id": "vertebre-vue-superieure", "titre": "La vert\u00e8bre type, vue de dessus", "vb": "0 0 320 330", "dessin": "<g fill='none' stroke='currentColor' stroke-width='2.4' stroke-linecap='round'><circle cx='160' cy='55' r='38'/><path d='M135,88 L110,145'/><path d='M185,88 L210,145'/><path d='M110,145 Q120,190 160,220'/><path d='M210,145 Q200,190 160,220'/><path d='M160,220 L160,270'/><path d='M112,142 L35,175'/><path d='M208,142 L285,175'/></g><circle cx='160' cy='180' r='32' fill='none' stroke='currentColor' stroke-width='1.2' stroke-dasharray='3 3'/>", "pastilles": [{"n": 1, "x": 160, "y": 55, "t": "Corps vert\u00e9bral", "ancre": "middle", "indice": "partie ant\u00e9rieure, cylindrique"}, {"n": 2, "x": 130, "y": 100, "t": "P\u00e9dicule", "ancre": "end", "indice": "\u00d72 ; passage des nerfs rachidiens"}, {"n": 3, "x": 35, "y": 175, "t": "Processus transverse", "ancre": "start", "indice": "\u00d72, lat\u00e9ral"}, {"n": 4, "x": 160, "y": 200, "t": "Canal rachidien", "ancre": "middle", "indice": "passage de la moelle \u00e9pini\u00e8re"}, {"n": 5, "x": 160, "y": 270, "t": "Processus \u00e9pineux", "ancre": "middle", "indice": "\u00d71, m\u00e9dian post\u00e9rieur"}], "slide": 147}, {"id": "fibres-abdominales-orientation", "titre": "Orientation des fibres des 4 muscles abdominaux", "vb": "0 0 300 700", "dessin": "<g fill='none' stroke='currentColor' stroke-width='2'><rect x='30' y='20' width='240' height='100' rx='6'/><path d='M45,35 L255,35'/><path d='M45,52 L255,52'/><path d='M45,69 L255,69'/><path d='M45,86 L255,86'/><path d='M45,103 L255,103'/></g><g fill='none' stroke='currentColor' stroke-width='2'><rect x='30' y='190' width='240' height='100' rx='6'/><path d='M150,290 L60,190'/><path d='M150,290 L90,190'/><path d='M150,290 L120,190'/><path d='M150,290 L150,190'/><path d='M150,290 L180,190'/><path d='M150,290 L210,190'/><path d='M150,290 L240,190'/></g><g fill='none' stroke='currentColor' stroke-width='2'><rect x='30' y='360' width='240' height='100' rx='6'/><path d='M70,360 L30,460'/><path d='M105,360 L65,460'/><path d='M140,360 L100,460'/><path d='M175,360 L135,460'/><path d='M210,360 L170,460'/><path d='M245,360 L205,460'/></g><g fill='none' stroke='currentColor' stroke-width='2'><rect x='30' y='530' width='240' height='100' rx='6'/><path d='M80,540 L80,620'/><path d='M100,540 L100,620'/><path d='M120,540 L120,620'/><path d='M180,540 L180,620'/><path d='M200,540 L200,620'/><path d='M220,540 L220,620'/><path d='M75,560 L125,560 M175,560 L225,560'/><path d='M75,590 L125,590 M175,590 L225,590'/><path d='M150,528 L150,632' stroke-dasharray='3 3'/></g>", "pastilles": [{"n": 1, "x": 150, "y": 138, "t": "Transverse de l'abdomen", "ancre": "middle", "indice": "le plus profond ; fibres transversales"}, {"n": 2, "x": 150, "y": 308, "t": "Oblique interne", "ancre": "middle", "indice": "sous l'oblique externe ; fibres en \u00e9ventail vers le haut"}, {"n": 3, "x": 150, "y": 478, "t": "Oblique externe", "ancre": "middle", "indice": "le plus superficiel ; fibres obliques vers le bas"}, {"n": 4, "x": 150, "y": 648, "t": "Droit de l'abdomen", "ancre": "middle", "indice": "de part et d'autre de la ligne blanche ; fibres verticales"}], "slide": 185}]}, {"num": 6, "titre": "Le membre sup\u00e9rieur", "slides": [191, 266], "sections": [{"titre": "Le squelette du membre sup\u00e9rieur : 4 segments", "slide": 193, "points": ["Le squelette du membre sup\u00e9rieur comprend 4 segments : la ceinture scapulaire, le bras, l'avant-bras et la main."]}, {"titre": "Vue d'ensemble : segments, os et articulations", "slide": 194, "points": ["Ceinture scapulaire : clavicule + scapula (omoplate) ; articulations sterno-claviculaire, acromio-claviculaire et scapulo-hum\u00e9rale (\u00e9paule).", "Bras : hum\u00e9rus. Coude : articulations hum\u00e9ro-ulnaire, hum\u00e9ro-radiale et radio-ulnaire proximale.", "Avant-bras : radius (lat\u00e9ral) et ulna/cubitus (m\u00e9dial). Poignet : articulation radio-carpienne ; articulation radio-ulnaire distale."]}, {"titre": "La ceinture scapulaire", "slide": 196, "points": ["Elle est constitu\u00e9e par : 2 clavicules, 2 scapula, le sternum."]}, {"titre": "La clavicule", "slide": 198, "points": ["Os long en forme de \u00ab S \u00bb, situ\u00e9 entre le sternum et la scapula.", "Elle s'articule m\u00e9dialement avec le sternum (manubrium) pour former l'articulation sterno-claviculaire, et lat\u00e9ralement avec la scapula pour former l'articulation acromio-claviculaire."]}, {"titre": "Les articulations sterno- et acromio-claviculaire : nom des extr\u00e9mit\u00e9s", "slide": 199, "points": ["Extr\u00e9mit\u00e9 lat\u00e9rale de la clavicule = extr\u00e9mit\u00e9 ACROMIALE (vers l'articulation acromio-claviculaire).", "Extr\u00e9mit\u00e9 m\u00e9diale de la clavicule = extr\u00e9mit\u00e9 STERNALE (vers l'articulation sterno-claviculaire)."]}, {"titre": "La scapula", "slide": 200, "points": ["Os plat et triangulaire situ\u00e9 sur la face post\u00e9rieure du thorax.", "Elle s'articule avec la clavicule (au niveau de l'acromion, articulation acromio-claviculaire) et avec l'hum\u00e9rus (au niveau de la cavit\u00e9 gl\u00e9no\u00efdale, articulation scapulo-hum\u00e9rale)."]}, {"titre": "La scapula : rep\u00e8res de la vue ant\u00e9rieure", "slide": 201, "points": ["Bord sup\u00e9rieur, bord m\u00e9dial, bord lat\u00e9ral.", "Processus coraco\u00efde (lieu d'insertions musculaires), acromion, cavit\u00e9 gl\u00e9no\u00efdale."]}, {"titre": "La scapula : rep\u00e8res de la vue post\u00e9rieure", "slide": 202, "points": ["L'\u00e9pine traverse la face post\u00e9rieure et se termine par l'acromion (articulation acromio-claviculaire).", "Processus coraco\u00efde \u00e0 l'avant, cavit\u00e9 gl\u00e9no\u00efdale (articulation scapulo-hum\u00e9rale), bord lat\u00e9ral."]}, {"titre": "La scapula : vue lat\u00e9rale", "slide": 203, "points": ["La cavit\u00e9 gl\u00e9no\u00efdale (articulation scapulo-hum\u00e9rale), le processus coraco\u00efde, l'acromion et le bord lat\u00e9ral s'y voient de profil."]}, {"titre": "Le bras : l'hum\u00e9rus", "slide": 205, "points": ["Un seul os : l'hum\u00e9rus. Os long qui s'articule en haut avec la scapula (cavit\u00e9 gl\u00e9no\u00efdale, articulation scapulo-hum\u00e9rale).", "En bas et lat\u00e9ralement avec le radius (t\u00eate du radius, articulation hum\u00e9ro-radiale) ; en bas et m\u00e9dialement avec l'ulna (incisure trochl\u00e9aire, articulation hum\u00e9ro-ulnaire)."]}, {"titre": "L'hum\u00e9rus : rep\u00e8res", "slide": 206, "points": ["Extr\u00e9mit\u00e9 proximale : t\u00eate hum\u00e9rale, tubercule majeur, tubercule mineur.", "Extr\u00e9mit\u00e9 distale : capitulum, trochl\u00e9e hum\u00e9rale, \u00e9picondyle m\u00e9dial, \u00e9picondyle lat\u00e9ral ; fosse ol\u00e9cranienne \u00e0 la face post\u00e9rieure."]}, {"titre": "Les 3 articulations du haut du membre, en aper\u00e7u", "slide": 207, "points": ["Articulation scapulo-hum\u00e9rale (\u00e9paule), articulation hum\u00e9ro-radiale et articulation hum\u00e9ro-ulnaire (coude)."]}, {"titre": "L'avant-bras : 2 os", "slide": 209, "points": ["Deux os : le radius et l'ulna."]}, {"titre": "Le radius", "slide": 210, "points": ["Os lat\u00e9ral de l'avant-bras. Os long qui s'articule : en haut avec l'hum\u00e9rus (capitulum, articulation hum\u00e9ro-radiale).", "M\u00e9dialement et en haut avec l'ulna (incisure radiale, articulation radio-ulnaire proximale).", "En bas avec le carpe (scapho\u00efde + lunatum, articulation radio-carpienne) ; m\u00e9dialement et en bas avec l'ulna (t\u00eate de l'ulna, articulation radio-ulnaire distale)."]}, {"titre": "Le radius : rep\u00e8res", "slide": 211, "points": ["T\u00eate radiale, tub\u00e9rosit\u00e9 radiale, incisure ulnaire, surface articulaire carpienne, processus stylo\u00efde (du radius)."]}, {"titre": "L'ulna (cubitus)", "slide": 212, "points": ["Os m\u00e9dial de l'avant-bras. Os long qui s'articule : en haut avec l'hum\u00e9rus (trochl\u00e9e, articulation hum\u00e9ro-ulnaire).", "Lat\u00e9ralement et en haut avec le radius (tub\u00e9rosit\u00e9 radiale, articulation radio-ulnaire proximale) ; lat\u00e9ralement et en bas avec le radius (articulation radio-ulnaire distale)."]}, {"titre": "L'ulna : rep\u00e8res", "slide": 213, "points": ["Incisure trochl\u00e9aire, ol\u00e9crane, incisure radiale, t\u00eate de l'ulna, processus stylo\u00efde (de l'ulna)."]}, {"titre": "L'articulation radio-ulnaire proximale", "slide": 214, "points": ["Form\u00e9e par l'ol\u00e9crane et l'incisure trochl\u00e9aire de l'ulna (\u00e9piphyse proximale) avec la t\u00eate radiale."]}, {"titre": "L'articulation du coude, vue d'ensemble", "slide": 217, "points": ["Articulation hum\u00e9ro-radiale, articulation hum\u00e9ro-ulnaire et articulation radio-ulnaire proximale."]}, {"titre": "L'articulation du coude : 3 articulations, 3 types, 2 mouvements", "slide": 218, "points": ["L'articulation du coude est compos\u00e9e de 3 articulations synoviales ayant la m\u00eame cavit\u00e9 articulaire (une seule capsule) : l'articulation hum\u00e9ro-ulnaire (ginglyme), l'articulation hum\u00e9ro-radiale (sph\u00e9ro\u00efde), et l'articulation radio-ulnaire proximale (trocho\u00efde).", "Les 2 premi\u00e8res (hum\u00e9ro-ulnaire, hum\u00e9ro-radiale) permettent des mouvements de flexion-extension de l'avant-bras sur le bras.", "La radio-ulnaire proximale permet des mouvements de prono-supination de l'avant-bras."]}, {"titre": "La main : 27 os en 3 groupes", "slide": 221, "points": ["La main est compos\u00e9e de 27 os r\u00e9partis en 3 groupes : le carpe (8 os), le m\u00e9tacarpe (5 m\u00e9tacarpiens), les phalanges (3 par doigt sauf le pouce qui n'en a que 2).", "Les phalanges sont proximales, interm\u00e9diaires, distales."]}, {"titre": "L'articulation du poignet", "slide": 222, "points": ["L'articulation radio-carpienne (le poignet) est form\u00e9e par 3 os : 1 os de l'avant-bras, le radius, + 2 os du carpe, le scapho\u00efde et le lunatum."]}, {"titre": "Les mouvements du poignet", "slide": 223, "points": ["Abduction, adduction, flexion, extension."]}, {"titre": "Rep\u00e8re clinique : la tabati\u00e8re anatomique", "slide": 224, "points": ["Le scapho\u00efde se palpe dans la tabati\u00e8re anatomique, un creux visible sur le bord lat\u00e9ral du poignet quand le pouce est \u00e9tendu en arri\u00e8re."]}, {"titre": "Muscles unissant le membre sup\u00e9rieur et la colonne vert\u00e9brale", "slide": 226, "points": ["Groupe superficiel : trap\u00e8ze, grand dorsal.", "Groupe profond : \u00e9l\u00e9vateur de la scapula, petit rhombo\u00efde, grand rhombo\u00efde."]}, {"titre": "Le petit et le grand rhombo\u00efde", "slide": 229, "points": ["Petit rhombo\u00efde \u2014 origine : processus \u00e9pineux C7 et T1. Terminaison : bord m\u00e9dial de la scapula (au niveau de l'\u00e9pine).", "Grand rhombo\u00efde \u2014 origine : processus \u00e9pineux T2 \u00e0 T5. Terminaison : bord m\u00e9dial de la scapula (sous l'\u00e9pine).", "Les deux sont adducteurs, \u00e9l\u00e9vateurs et fixateurs de la scapula."]}, {"titre": "Le trap\u00e8ze", "slide": 231, "points": ["Origine : occiput (os post\u00e9rieur de la base du cr\u00e2ne), processus \u00e9pineux C1 \u00e0 T12.", "Terminaison, en 3 faisceaux : clavicule (faisceau sup\u00e9rieur), acromion (faisceau interm\u00e9diaire), \u00e9pine de la scapula (faisceau inf\u00e9rieur).", "Actions : \u00e9l\u00e9vateur de la ceinture scapulaire ; adducteur et fixateur de la scapula ; extenseur de la t\u00eate (contraction bilat\u00e9rale) ; inclinateur lat\u00e9ral et rotateur de la t\u00eate."]}, {"titre": "Le grand dorsal", "slide": 234, "points": ["Origine : processus \u00e9pineux T7 \u00e0 L5, cr\u00eate sacrale, cr\u00eate iliaque, c\u00f4tes 9 \u00e0 12. Terminaison : cr\u00eate du tubercule mineur de l'hum\u00e9rus.", "Actions : adducteur, rotateur m\u00e9dial et agent de la r\u00e9tropulsion du bras ; adducteur et abaisseur de la scapula."]}, {"titre": "Muscles unissant le membre sup\u00e9rieur et le thorax", "slide": 237, "points": ["4 muscles : grand pectoral, dentel\u00e9 ant\u00e9rieur, petit pectoral, subclavier."]}, {"titre": "Le grand pectoral", "slide": 240, "points": ["Origine : clavicule, sternum, c\u00f4tes 2 \u00e0 6, apon\u00e9vrose du grand droit de l'abdomen. Terminaison : cr\u00eate du tubercule majeur de l'hum\u00e9rus.", "Action : adducteur, rotateur m\u00e9dial et agent de l'ant\u00e9pulsion du bras."]}, {"titre": "Le dentel\u00e9 ant\u00e9rieur", "slide": 242, "points": ["Origine : c\u00f4tes 1 \u00e0 9 (ou 10). Terminaison : bord m\u00e9dial de la scapula.", "Action : abducteur, abaisseur, rotateur m\u00e9dial et fixateur de la scapula."]}, {"titre": "Le petit pectoral et le subclavier", "slide": 243, "points": ["Nomm\u00e9s et illustr\u00e9s, sans origine ni terminaison d\u00e9taill\u00e9es dans ce cours."]}, {"titre": "Muscles de l'\u00e9paule", "slide": 245, "points": ["6 muscles : delto\u00efde, supra-\u00e9pineux, infra-\u00e9pineux, petit rond, grand rond, subscapulaire."]}, {"titre": "Le delto\u00efde : origine et terminaison", "slide": 246, "points": ["Rep\u00e8res de la vue lat\u00e9rale : \u00e9pine, bord lat\u00e9ral de l'hum\u00e9rus, acromion, clavicule."]}, {"titre": "Le delto\u00efde : 3 faisceaux, 3 actions oppos\u00e9es", "slide": 247, "points": ["Origine : clavicule (faisceau claviculaire ou ant\u00e9rieur), acromion (faisceau acromial ou interm\u00e9diaire), \u00e9pine (faisceau \u00e9pineux ou post\u00e9rieur). Terminaison commune : tub\u00e9rosit\u00e9 delto\u00efdienne de l'hum\u00e9rus.", "Faisceau claviculaire (ant\u00e9rieur) : fl\u00e9chisseur (ant\u00e9pulsion) et rotateur m\u00e9dial du bras.", "Faisceau acromial (interm\u00e9diaire) : abducteur du bras.", "Faisceau \u00e9pineux (post\u00e9rieur) : extenseur (r\u00e9tropulsion) et rotateur lat\u00e9ral du bras."]}, {"titre": "Muscles de l'\u00e9paule, vue post\u00e9rieure : actions du supra-\u00e9pineux au grand rond", "slide": 249, "points": ["Supra-\u00e9pineux : abducteur du bras + fixateur de l'\u00e9paule.", "Infra-\u00e9pineux : abducteur et rotateur lat\u00e9ral du bras.", "Petit rond : adducteur et rotateur lat\u00e9ral du bras.", "Grand rond : adducteur et rotateur m\u00e9dial du bras."]}, {"titre": "Le subscapulaire", "slide": 250, "points": ["Action : adducteur et rotateur m\u00e9dial du bras (le cours ne donne pas son origine ni sa terminaison)."]}, {"titre": "La coiffe des rotateurs", "slide": 251, "points": ["Form\u00e9e de 4 muscles : le supra-\u00e9pineux (le plus fragile), l'infra-\u00e9pineux, le petit rond, le subscapulaire.", "L'articulation scapulo-hum\u00e9rale est mobile, donc instable par nature. Ces muscles agissent donc comme des ligaments actifs qui maintiennent l'articulation."]}, {"titre": "Muscles du bras : 2 groupes", "slide": 254, "points": ["Groupe ant\u00e9rieur (fl\u00e9chisseur) : biceps brachial, coraco-brachial, brachial.", "Groupe post\u00e9rieur (extenseur) : triceps brachial, ancon\u00e9."]}, {"titre": "Le biceps brachial", "slide": 255, "points": ["Origine : chef long, tubercule supra-gl\u00e9no\u00efdal ; chef court, processus coraco\u00efde. Terminaison : tub\u00e9rosit\u00e9 radiale.", "Actions : fl\u00e9chisseur et supinateur de l'avant-bras (les 2 chefs) ; chef court, adducteur du bras ; chef long, agent de l'ant\u00e9pulsion du bras."]}, {"titre": "Le coraco-brachial et le brachial", "slide": 258, "points": ["Coraco-brachial \u2014 origine : processus coraco\u00efde. Terminaison : diaphyse de l'hum\u00e9rus. Action : adducteur et agent de l'ant\u00e9pulsion du bras.", "Brachial \u2014 origine : face ant\u00e9rieure de l'hum\u00e9rus. Terminaison : \u00e9piphyse proximale de l'ulna. Action : fl\u00e9chisseur de l'avant-bras."]}, {"titre": "Le triceps brachial", "slide": 261, "points": ["Origine : chef long, tubercule infra-gl\u00e9no\u00efdal ; chef m\u00e9dial, face post\u00e9rieure de l'hum\u00e9rus (moiti\u00e9 inf\u00e9rieure) ; chef lat\u00e9ral, face post\u00e9rieure de l'hum\u00e9rus (moiti\u00e9 sup\u00e9rieure). Terminaison : ol\u00e9crane.", "Actions : extenseur de l'avant-bras (les 3 chefs) ; chef long, adducteur et agent de la r\u00e9tropulsion du bras."]}, {"titre": "Muscles de l'avant-bras", "slide": 264, "points": ["3 muscles pronateurs : le rond pronateur, le carr\u00e9 pronateur, le brachio-radial. 1 muscle supinateur : le supinateur.", "3 muscles fl\u00e9chisseurs de la main : fl\u00e9chisseur radial du carpe (+ abduction), long palmaire, fl\u00e9chisseur ulnaire du carpe (+ adduction).", "5 muscles extenseurs de la main : extenseur ulnaire du carpe (+ adduction), extenseur des doigts, extenseur du petit doigt, court et long extenseur radial du carpe (+ abduction).", "7 muscles des doigts : fl\u00e9chisseur superficiel des doigts, fl\u00e9chisseur profond des doigts, long fl\u00e9chisseur du pouce, long et court extenseur du pouce, long abducteur du pouce, extenseur de l'index."]}, {"titre": "Les mouvements de l'avant-bras", "slide": 265, "points": ["Pronation, supination."]}], "cartes": [{"id": "c6-01", "q": "Quels sont les 4 segments du squelette du membre sup\u00e9rieur ?", "r": "La ceinture scapulaire, le bras, l'avant-bras et la main.", "slide": 193}, {"id": "c6-02", "q": "Quels 2 os composent la ceinture scapulaire, en plus du sternum ?", "r": "La clavicule et la scapula (omoplate).", "slide": 196}, {"id": "c6-03", "q": "Quelle est la forme de la clavicule, et avec quels 2 os s'articule-t-elle ?", "r": "Un os long en forme de \u00ab S \u00bb ; elle s'articule m\u00e9dialement avec le sternum (manubrium, articulation sterno-claviculaire) et lat\u00e9ralement avec la scapula (articulation acromio-claviculaire).", "slide": 198}, {"id": "c6-04", "q": "Sur la clavicule, quelle extr\u00e9mit\u00e9 est dite \u00ab acromiale \u00bb et laquelle est dite \u00ab sternale \u00bb ?", "r": "L'extr\u00e9mit\u00e9 lat\u00e9rale = extr\u00e9mit\u00e9 acromiale (vers l'articulation acromio-claviculaire) ; l'extr\u00e9mit\u00e9 m\u00e9diale = extr\u00e9mit\u00e9 sternale (vers l'articulation sterno-claviculaire).", "slide": 199}, {"id": "c6-05", "q": "O\u00f9 est situ\u00e9e la scapula, et avec quels 2 os s'articule-t-elle ?", "r": "Os plat et triangulaire situ\u00e9 sur la face post\u00e9rieure du thorax ; elle s'articule avec la clavicule (au niveau de l'acromion, articulation acromio-claviculaire) et avec l'hum\u00e9rus (au niveau de la cavit\u00e9 gl\u00e9no\u00efdale, articulation scapulo-hum\u00e9rale).", "slide": 200}, {"id": "c6-06", "q": "O\u00f9 se trouvent l'acromion, le processus coraco\u00efde, l'\u00e9pine et la cavit\u00e9 gl\u00e9no\u00efdale sur la scapula ?", "r": "L'\u00e9pine traverse la face post\u00e9rieure et se termine par l'acromion (qui forme l'articulation acromio-claviculaire) ; le processus coraco\u00efde est \u00e0 l'avant (insertions musculaires) ; la cavit\u00e9 gl\u00e9no\u00efdale re\u00e7oit la t\u00eate hum\u00e9rale (articulation scapulo-hum\u00e9rale).", "slide": 202}, {"id": "c6-07", "q": "Avec quels os l'hum\u00e9rus s'articule-t-il, et quels rep\u00e8res se trouvent \u00e0 ses 2 extr\u00e9mit\u00e9s ?", "r": "En haut avec la scapula (scapulo-hum\u00e9rale) ; en bas lat\u00e9ralement avec le radius (hum\u00e9ro-radiale) et m\u00e9dialement avec l'ulna (hum\u00e9ro-ulnaire). Extr\u00e9mit\u00e9 proximale : t\u00eate hum\u00e9rale, tubercules majeur et mineur. Extr\u00e9mit\u00e9 distale : capitulum, trochl\u00e9e, \u00e9picondyles m\u00e9dial et lat\u00e9ral, fosse ol\u00e9cranienne.", "slide": 205}, {"id": "c6-08", "q": "Le radius et l'ulna : lequel est lat\u00e9ral, lequel est m\u00e9dial, et avec quels os chacun s'articule-t-il ?", "r": "Le radius est LAT\u00c9RAL : il s'articule avec l'hum\u00e9rus (capitulum \u2192 hum\u00e9ro-radiale), avec le carpe (scapho\u00efde + lunatum \u2192 radio-carpienne), et avec l'ulna (\u2192 radio-ulnaire proximale en haut, radio-ulnaire distale en bas). L'ulna est M\u00c9DIALE : elle s'articule avec l'hum\u00e9rus (trochl\u00e9e \u2192 hum\u00e9ro-ulnaire) et avec le radius (radio-ulnaire proximale et distale).", "slide": 210}, {"id": "c6-09", "q": "L'articulation du coude comprend 3 articulations synoviales dans une m\u00eame capsule : lesquelles, de quel type chacune, et quels mouvements permettent-elles ?", "r": "Hum\u00e9ro-ulnaire (ginglyme) et hum\u00e9ro-radiale (sph\u00e9ro\u00efde) : flexion-extension de l'avant-bras sur le bras. Radio-ulnaire proximale (trocho\u00efde) : prono-supination de l'avant-bras.", "slide": 218}, {"id": "c6-10", "q": "Combien d'os compte la main, et comment se r\u00e9partissent-ils en 3 groupes ?", "r": "27 os : le carpe (8 os), le m\u00e9tacarpe (5 m\u00e9tacarpiens), les phalanges (3 par doigt, sauf le pouce qui n'en a que 2 : proximales, interm\u00e9diaires, distales).", "slide": 221}, {"id": "c6-11", "q": "Quels 3 os forment l'articulation radio-carpienne (le poignet) ?", "r": "1 os de l'avant-bras, le radius, + 2 os du carpe : le scapho\u00efde et le lunatum. L'ulna n'y participe PAS directement.", "slide": 222}, {"id": "c6-12", "q": "Quels sont les 4 mouvements du poignet ?", "r": "Abduction, adduction, flexion, extension.", "slide": 223}, {"id": "c6-13", "q": "O\u00f9 se palpe le scapho\u00efde ?", "r": "Dans la tabati\u00e8re anatomique, au niveau du poignet.", "slide": 224}, {"id": "c6-14", "q": "Quels muscles unissent le membre sup\u00e9rieur \u00e0 la colonne vert\u00e9brale, en groupe superficiel et en groupe profond ?", "r": "Groupe superficiel : trap\u00e8ze, grand dorsal. Groupe profond : \u00e9l\u00e9vateur de la scapula, petit rhombo\u00efde, grand rhombo\u00efde.", "slide": 226}, {"id": "c6-15", "q": "Quelle est la diff\u00e9rence d'origine et de terminaison entre le petit et le grand rhombo\u00efde ?", "r": "Petit rhombo\u00efde : origine processus \u00e9pineux C7 et T1, terminaison au bord m\u00e9dial de la scapula au niveau de l'\u00e9pine. Grand rhombo\u00efde : origine processus \u00e9pineux T2 \u00e0 T5, terminaison au bord m\u00e9dial de la scapula sous l'\u00e9pine.", "slide": 229}, {"id": "c6-16", "q": "Le trap\u00e8ze se termine par 3 faisceaux : lesquels, et sur quelle structure chacun s'ins\u00e8re-t-il ?", "r": "Faisceau sup\u00e9rieur \u2192 clavicule ; faisceau interm\u00e9diaire \u2192 acromion ; faisceau inf\u00e9rieur \u2192 \u00e9pine de la scapula.", "slide": 231}, {"id": "c6-17", "q": "Quelles sont les actions du grand dorsal sur le bras et sur la scapula ?", "r": "Sur le bras : adducteur, rotateur m\u00e9dial, agent de la r\u00e9tropulsion. Sur la scapula : adducteur, abaisseur.", "slide": 234}, {"id": "c6-18", "q": "Quels sont les 4 muscles qui unissent le membre sup\u00e9rieur au thorax ?", "r": "Le grand pectoral, le dentel\u00e9 ant\u00e9rieur, le petit pectoral et le subclavier.", "slide": 237}, {"id": "c6-19", "q": "Quelles sont l'origine, la terminaison et l'action du grand pectoral ?", "r": "Origine : clavicule, sternum, c\u00f4tes 2 \u00e0 6, apon\u00e9vrose du grand droit de l'abdomen. Terminaison : cr\u00eate du tubercule majeur de l'hum\u00e9rus. Action : adducteur, rotateur m\u00e9dial et agent de l'ant\u00e9pulsion du bras.", "slide": 240}, {"id": "c6-20", "q": "Quelle est l'action du dentel\u00e9 ant\u00e9rieur sur la scapula ?", "r": "Abducteur, abaisseur, rotateur m\u00e9dial et fixateur de la scapula.", "slide": 242}, {"id": "c6-21", "q": "Quels sont les 6 muscles de l'\u00e9paule ?", "r": "Le delto\u00efde, le supra-\u00e9pineux, l'infra-\u00e9pineux, le petit rond, le grand rond, le subscapulaire.", "slide": 245}, {"id": "c6-22", "q": "Le delto\u00efde a 3 faisceaux : quelle est l'origine de chacun, et o\u00f9 s'ins\u00e8rent-ils tous ?", "r": "Faisceau claviculaire (ant\u00e9rieur) : clavicule. Faisceau acromial (interm\u00e9diaire) : acromion. Faisceau \u00e9pineux (post\u00e9rieur) : \u00e9pine de la scapula. Les 3 s'ins\u00e8rent ensemble sur la tub\u00e9rosit\u00e9 delto\u00efdienne de l'hum\u00e9rus.", "slide": 247, "plan": "frontal"}, {"id": "c6-23", "q": "Le delto\u00efde n'a qu'une seule terminaison mais 3 actions diff\u00e9rentes selon le faisceau : lesquelles ?", "r": "Faisceau claviculaire : fl\u00e9chisseur (ant\u00e9pulsion) et rotateur m\u00e9dial du bras. Faisceau acromial : abducteur du bras. Faisceau \u00e9pineux : extenseur (r\u00e9tropulsion) et rotateur lat\u00e9ral du bras \u2014 l'exact oppos\u00e9 du faisceau claviculaire.", "slide": 247}, {"id": "c6-24", "q": "Quels 4 muscles forment la coiffe des rotateurs, et pourquoi le cours les compare-t-il \u00e0 des \u00ab ligaments actifs \u00bb ?", "r": "Le supra-\u00e9pineux (le plus fragile), l'infra-\u00e9pineux, le petit rond et le subscapulaire. L'articulation scapulo-hum\u00e9rale est mobile donc instable par nature : ces 4 muscles agissent comme des ligaments actifs qui la maintiennent.", "slide": 251}, {"id": "c6-25", "q": "Quels sont les 2 groupes de muscles du bras, et quels muscles chacun contient-il ?", "r": "Groupe ant\u00e9rieur (fl\u00e9chisseur) : biceps brachial, coraco-brachial, brachial. Groupe post\u00e9rieur (extenseur) : triceps brachial, ancon\u00e9.", "slide": 254}], "quiz": [{"id": "q6-01", "q": "L'articulation du coude comprend 3 articulations dans une seule capsule. Laquelle est de type trocho\u00efde et permet la prono-supination ?", "choix": ["l'articulation radio-ulnaire proximale", "l'articulation hum\u00e9ro-ulnaire", "l'articulation hum\u00e9ro-radiale", "l'articulation radio-ulnaire distale"], "bonne": 0, "expl": "La radio-ulnaire proximale (trocho\u00efde) permet la prono-supination. L'hum\u00e9ro-ulnaire (ginglyme) et l'hum\u00e9ro-radiale (sph\u00e9ro\u00efde) permettent la flexion-extension. La radio-ulnaire distale n'appartient pas \u00e0 la capsule du coude.", "slide": 218}, {"id": "q6-02", "q": "Sur la clavicule, l'extr\u00e9mit\u00e9 lat\u00e9rale (celle qui forme l'articulation acromio-claviculaire) se nomme extr\u00e9mit\u00e9...", "choix": ["acromiale", "sternale", "coraco\u00efde", "gl\u00e9no\u00efdale"], "bonne": 0, "expl": "Extr\u00e9mit\u00e9 lat\u00e9rale = acromiale (vers l'acromion de la scapula). Extr\u00e9mit\u00e9 m\u00e9diale = sternale (vers le sternum). Coraco\u00efde et gl\u00e9no\u00efdale ne sont pas des extr\u00e9mit\u00e9s de la clavicule.", "slide": 199}, {"id": "q6-03", "q": "Le radius est l'os ... de l'avant-bras.", "choix": ["lat\u00e9ral", "m\u00e9dial", "post\u00e9rieur", "ant\u00e9rieur"], "bonne": 0, "expl": "Le radius est lat\u00e9ral, l'ulna est m\u00e9dial. C'est la confusion la plus fr\u00e9quente sur l'avant-bras.", "slide": 210}, {"id": "q6-04", "q": "L'articulation radio-carpienne (le poignet) est form\u00e9e par le radius et 2 os du carpe. Lesquels ?", "choix": ["le scapho\u00efde et le lunatum", "le scapho\u00efde et l'ulna", "l'ulna et le lunatum", "le scapho\u00efde, le lunatum et l'ulna"], "bonne": 0, "expl": "Radius + scapho\u00efde + lunatum. L'ulna ne participe PAS directement \u00e0 l'articulation radio-carpienne \u2014 pi\u00e8ge fr\u00e9quent.", "slide": 222}, {"id": "q6-05", "q": "Le mouvement de prono-supination de l'avant-bras se fait gr\u00e2ce \u00e0 quelle articulation, de quel type ?", "choix": ["la radio-ulnaire proximale, trocho\u00efde", "la hum\u00e9ro-ulnaire, ginglyme", "la hum\u00e9ro-radiale, sph\u00e9ro\u00efde", "la scapulo-hum\u00e9rale, sph\u00e9ro\u00efde"], "bonne": 0, "expl": "Seule l'articulation radio-ulnaire proximale (trocho\u00efde) permet la prono-supination. Les articulations hum\u00e9ro-ulnaire et hum\u00e9ro-radiale ne permettent que la flexion-extension.", "slide": 218, "plan": "transversal"}, {"id": "q6-06", "q": "La main compte 27 os. Comment se r\u00e9partissent-ils ?", "choix": ["8 carpiens, 5 m\u00e9tacarpiens, 14 phalanges", "7 carpiens, 5 m\u00e9tacarpiens, 15 phalanges", "8 carpiens, 6 m\u00e9tacarpiens, 13 phalanges", "8 carpiens, 5 m\u00e9tacarpiens, 15 phalanges"], "bonne": 0, "expl": "8 (carpe) + 5 (m\u00e9tacarpe) + 14 (phalanges : 3 par doigt sauf le pouce qui n'en a que 2, soit 3\u00d74+2=14) = 27.", "slide": 221}, {"id": "q6-07", "q": "Le faisceau interm\u00e9diaire du trap\u00e8ze se termine sur...", "choix": ["l'acromion", "la clavicule", "l'\u00e9pine de la scapula", "le processus coraco\u00efde"], "bonne": 0, "expl": "Faisceau sup\u00e9rieur \u2192 clavicule ; faisceau interm\u00e9diaire \u2192 acromion ; faisceau inf\u00e9rieur \u2192 \u00e9pine de la scapula.", "slide": 231}, {"id": "q6-08", "q": "Le faisceau acromial (interm\u00e9diaire) du delto\u00efde est...", "choix": ["abducteur du bras", "fl\u00e9chisseur et rotateur m\u00e9dial du bras", "extenseur et rotateur lat\u00e9ral du bras", "adducteur du bras"], "bonne": 0, "expl": "Le faisceau acromial est abducteur du bras \u2014 c'est ce mouvement, dans le plan frontal, qui donne au delto\u00efde son r\u00f4le le plus connu. Le faisceau claviculaire est fl\u00e9chisseur/rotateur m\u00e9dial, le faisceau \u00e9pineux est extenseur/rotateur lat\u00e9ral.", "slide": 247, "plan": "frontal"}, {"id": "q6-09", "q": "Le faisceau \u00e9pineux (post\u00e9rieur) du delto\u00efde est...", "choix": ["extenseur (r\u00e9tropulsion) et rotateur lat\u00e9ral du bras", "fl\u00e9chisseur (ant\u00e9pulsion) et rotateur m\u00e9dial du bras", "abducteur du bras", "adducteur du bras"], "bonne": 0, "expl": "Le faisceau \u00e9pineux est extenseur et rotateur lat\u00e9ral : l'exact oppos\u00e9 du faisceau claviculaire (fl\u00e9chisseur et rotateur m\u00e9dial). Un seul muscle, trois faisceaux, des actions contradictoires.", "slide": 247}, {"id": "q6-10", "q": "Quels sont les 4 muscles de la coiffe des rotateurs ?", "choix": ["supra-\u00e9pineux, infra-\u00e9pineux, petit rond, subscapulaire", "supra-\u00e9pineux, infra-\u00e9pineux, delto\u00efde, subscapulaire", "supra-\u00e9pineux, infra-\u00e9pineux, grand rond, subscapulaire", "delto\u00efde, infra-\u00e9pineux, petit rond, grand rond"], "bonne": 0, "expl": "La coiffe des rotateurs, ce sont le supra-\u00e9pineux, l'infra-\u00e9pineux, le petit rond et le subscapulaire. Le delto\u00efde et le grand rond n'en font PAS partie : c'est le pi\u00e8ge le plus fr\u00e9quent sur cette notion.", "slide": 251}, {"id": "q6-11", "q": "Le biceps brachial a 2 chefs. O\u00f9 est l'origine de chacun ?", "choix": ["chef long : tubercule supra-gl\u00e9no\u00efdal ; chef court : processus coraco\u00efde", "chef long : processus coraco\u00efde ; chef court : tubercule supra-gl\u00e9no\u00efdal", "chef long : tubercule infra-gl\u00e9no\u00efdal ; chef court : processus coraco\u00efde", "chef long et chef court : tubercule supra-gl\u00e9no\u00efdal"], "bonne": 0, "expl": "Chef long \u2192 tubercule supra-gl\u00e9no\u00efdal ; chef court \u2192 processus coraco\u00efde. Les deux se terminent sur la tub\u00e9rosit\u00e9 radiale.", "slide": 255}, {"id": "q6-12", "q": "Parmi les 3 chefs du triceps brachial, lequel est aussi adducteur et agent de la r\u00e9tropulsion du bras (en plus d'\u00eatre extenseur de l'avant-bras) ?", "choix": ["le chef long", "le chef m\u00e9dial", "le chef lat\u00e9ral", "les 3 chefs \u00e0 \u00e9galit\u00e9"], "bonne": 0, "expl": "Le chef long, seul, part du tubercule infra-gl\u00e9no\u00efdal (donc de la scapula) : il agit aussi sur le bras (adducteur, r\u00e9tropulsion). Les chefs m\u00e9dial et lat\u00e9ral partent de l'hum\u00e9rus et n'agissent que sur l'avant-bras.", "slide": 261}], "muscles": [{"nom": "Petit rhombo\u00efde", "origine": ["processus \u00e9pineux C7 et T1"], "terminaison": ["bord m\u00e9dial de la scapula (au niveau de l'\u00e9pine)"], "actions": ["adducteur de la scapula", "\u00e9l\u00e9vateur de la scapula", "fixateur de la scapula"], "slide": 229}, {"nom": "Grand rhombo\u00efde", "origine": ["processus \u00e9pineux T2 \u00e0 T5"], "terminaison": ["bord m\u00e9dial de la scapula (sous l'\u00e9pine)"], "actions": ["adducteur de la scapula", "\u00e9l\u00e9vateur de la scapula", "fixateur de la scapula"], "slide": 229}, {"nom": "Trap\u00e8ze", "origine": ["occiput", "processus \u00e9pineux C1 \u00e0 T12"], "terminaison": ["clavicule (faisceau sup\u00e9rieur)", "acromion (faisceau interm\u00e9diaire)", "\u00e9pine de la scapula (faisceau inf\u00e9rieur)"], "actions": ["\u00e9l\u00e9vateur de la ceinture scapulaire", "adducteur de la scapula", "fixateur de la scapula", "extenseur de la t\u00eate (contraction bilat\u00e9rale)", "inclinateur lat\u00e9ral de la t\u00eate", "rotateur de la t\u00eate"], "slide": 231}, {"nom": "Grand dorsal", "origine": ["processus \u00e9pineux T7 \u00e0 L5", "cr\u00eate sacrale", "cr\u00eate iliaque", "c\u00f4tes 9 \u00e0 12"], "terminaison": ["cr\u00eate du tubercule mineur de l'hum\u00e9rus"], "actions": ["adducteur du bras", "rotateur m\u00e9dial du bras", "r\u00e9tropulsion du bras", "adducteur de la scapula", "abaisseur de la scapula"], "slide": 234}, {"nom": "Grand pectoral", "origine": ["clavicule", "sternum", "c\u00f4tes 2 \u00e0 6", "apon\u00e9vrose du grand droit de l'abdomen"], "terminaison": ["cr\u00eate du tubercule majeur de l'hum\u00e9rus"], "actions": ["adducteur du bras", "rotateur m\u00e9dial du bras", "ant\u00e9pulsion du bras"], "slide": 240}, {"nom": "Dentel\u00e9 ant\u00e9rieur", "origine": ["c\u00f4tes 1 \u00e0 9 (ou 10)"], "terminaison": ["bord m\u00e9dial de la scapula"], "actions": ["abducteur de la scapula", "abaisseur de la scapula", "rotateur m\u00e9dial de la scapula", "fixateur de la scapula"], "slide": 242}, {"nom": "Delto\u00efde", "origine": ["clavicule (faisceau claviculaire ou ant\u00e9rieur)", "acromion (faisceau acromial ou interm\u00e9diaire)", "\u00e9pine de la scapula (faisceau \u00e9pineux ou post\u00e9rieur)"], "terminaison": ["tub\u00e9rosit\u00e9 delto\u00efdienne de l'hum\u00e9rus"], "actions": ["faisceau claviculaire : fl\u00e9chisseur (ant\u00e9pulsion) et rotateur m\u00e9dial du bras", "faisceau acromial : abducteur du bras", "faisceau \u00e9pineux : extenseur (r\u00e9tropulsion) et rotateur lat\u00e9ral du bras"], "slide": 247}, {"nom": "Biceps brachial", "origine": ["chef long : tubercule supra-gl\u00e9no\u00efdal", "chef court : processus coraco\u00efde"], "terminaison": ["tub\u00e9rosit\u00e9 radiale"], "actions": ["fl\u00e9chisseur de l'avant-bras (les 2 chefs)", "supinateur de l'avant-bras (les 2 chefs)", "chef court : adducteur du bras", "chef long : ant\u00e9pulsion du bras"], "slide": 255}, {"nom": "Coraco-brachial", "origine": ["processus coraco\u00efde"], "terminaison": ["diaphyse de l'hum\u00e9rus"], "actions": ["adducteur du bras", "ant\u00e9pulsion du bras"], "slide": 258}, {"nom": "Brachial", "origine": ["face ant\u00e9rieure de l'hum\u00e9rus"], "terminaison": ["\u00e9piphyse proximale de l'ulna"], "actions": ["fl\u00e9chisseur de l'avant-bras"], "slide": 258}, {"nom": "Triceps brachial", "origine": ["chef long : tubercule infra-gl\u00e9no\u00efdal", "chef m\u00e9dial : face post\u00e9rieure de l'hum\u00e9rus (moiti\u00e9 inf\u00e9rieure)", "chef lat\u00e9ral : face post\u00e9rieure de l'hum\u00e9rus (moiti\u00e9 sup\u00e9rieure)"], "terminaison": ["ol\u00e9crane"], "actions": ["extenseur de l'avant-bras (les 3 chefs)", "chef long : adducteur du bras", "chef long : r\u00e9tropulsion du bras"], "slide": 261}], "pieges": [{"titre": "La coiffe des rotateurs ne compte QUE 4 muscles pr\u00e9cis", "texte": "Supra-\u00e9pineux, infra-\u00e9pineux, petit rond, subscapulaire \u2014 pas un de plus. Le pi\u00e8ge le plus fr\u00e9quent est d'y ajouter le DELTO\u00cfDE (qui coiffe l'\u00e9paule mais n'est PAS un muscle profond stabilisateur) ou le GRAND ROND (voisin du petit rond, mais absent de la coiffe). L'articulation scapulo-hum\u00e9rale est mobile donc instable par nature : ces 4 muscles, et eux seuls, agissent comme des ligaments actifs qui la maintiennent.", "slide": 251}, {"titre": "Le delto\u00efde : un seul muscle, trois faisceaux, trois actions contradictoires", "texte": "Le delto\u00efde a une terminaison UNIQUE (tub\u00e9rosit\u00e9 delto\u00efdienne) mais 3 faisceaux d'origine diff\u00e9rente dont les actions s'opposent selon celui qui se contracte. Faisceau claviculaire (ant\u00e9rieur) : fl\u00e9chisseur et rotateur M\u00c9DIAL du bras. Faisceau \u00e9pineux (post\u00e9rieur) : extenseur et rotateur LAT\u00c9RAL du bras \u2014 l'exact oppos\u00e9. Faisceau acromial (interm\u00e9diaire) : abducteur. Ne jamais r\u00e9pondre \u00ab le delto\u00efde fait X \u00bb sans pr\u00e9ciser le faisceau.", "slide": 247}, {"titre": "Le coude : 3 articulations, 3 types, mais 1 seule capsule", "texte": "L'articulation du coude n'est pas une seule articulation synoviale : elle en r\u00e9unit 3, de 3 types diff\u00e9rents, dans une m\u00eame cavit\u00e9 articulaire (une seule capsule). Hum\u00e9ro-ulnaire (ginglyme) et hum\u00e9ro-radiale (sph\u00e9ro\u00efde) font la flexion-extension. Radio-ulnaire proximale (trocho\u00efde) fait la prono-supination \u2014 un type et un mouvement compl\u00e8tement diff\u00e9rents, dans la m\u00eame capsule que les deux premi\u00e8res.", "slide": 218}, {"titre": "Le poignet (radio-carpienne) : radius + scapho\u00efde + lunatum \u2014 PAS l'ulna", "texte": "L'articulation radio-carpienne (le poignet) est form\u00e9e par 3 os : le radius (seul os de l'avant-bras impliqu\u00e9) + 2 os du carpe, le scapho\u00efde et le lunatum. L'ulna, pourtant pr\u00e9sent dans l'avant-bras jusqu'au poignet, n'entre PAS directement dans cette articulation : c'est un pi\u00e8ge fr\u00e9quent de l'y inclure.", "slide": 222}, {"titre": "L'ulna (slide 212) dit \u00ab tub\u00e9rosit\u00e9 radiale \u00bb \u2014 le cours se trompe lui-m\u00eame", "texte": "La slide 212 \u00e9crit que l'ulna s'articule avec le radius \u00ab lat\u00e9ralement et en haut, au niveau de la tub\u00e9rosit\u00e9 radiale \u00bb pour former l'articulation radio-ulnaire proximale. C'est une erreur du cours : le rep\u00e8re qui forme r\u00e9ellement cette articulation est la T\u00caTE RADIALE (elle tourne dans l'incisure radiale de l'ulna) \u2014 la tub\u00e9rosit\u00e9 radiale est un rep\u00e8re distinct et plus distal, l'insertion du biceps, que la slide 211 liste s\u00e9par\u00e9ment, juste \u00e0 c\u00f4t\u00e9 de la t\u00eate radiale sur le m\u00eame os. Si l'\u00e9valuation reprend la formulation exacte de la slide 212, \u00ab tub\u00e9rosit\u00e9 radiale \u00bb est la r\u00e9ponse attendue \u00e0 l'examen ; anatomiquement, c'est la t\u00eate radiale. Deux mots voisins, deux rep\u00e8res diff\u00e9rents du m\u00eame os : ne pas les confondre est justement ce que ce pi\u00e8ge teste.", "slide": 212}], "planches": [{"id": "squelette-membre-superieur-articulations", "titre": "Le squelette du membre sup\u00e9rieur et ses articulations", "vb": "0 0 300 640", "dessin": "<g class='os' fill='none' stroke='currentColor' stroke-width='2'><path d='M70,45 Q105,32 150,58' stroke-width='6' stroke-linecap='round'/><path d='M150,58 L150,140'/><path d='M150,145 L150,325' stroke-width='11' stroke-linecap='round'/><path d='M150,325 L70,345'/><path d='M150,325 L230,345'/><path d='M70,350 L92,515' stroke-width='8' stroke-linecap='round'/><path d='M230,350 L198,540' stroke-width='8' stroke-linecap='round'/><path d='M78,522 L142,540 L128,600 Q108,612 88,598 Z' stroke-width='2'/></g>", "pastilles": [{"n": 1, "x": 70, "y": 45, "t": "Sterno-claviculaire", "ancre": "middle", "indice": "extr\u00e9mit\u00e9 m\u00e9diale (sternale) de la clavicule"}, {"n": 2, "x": 150, "y": 58, "t": "Acromio-claviculaire", "ancre": "middle", "indice": "extr\u00e9mit\u00e9 lat\u00e9rale (acromiale) de la clavicule"}, {"n": 3, "x": 150, "y": 143, "t": "Scapulo-hum\u00e9rale", "ancre": "middle", "indice": "cavit\u00e9 gl\u00e9no\u00efdale + t\u00eate hum\u00e9rale"}, {"n": 4, "x": 70, "y": 345, "t": "Hum\u00e9ro-ulnaire", "ancre": "middle", "indice": "coude, c\u00f4t\u00e9 m\u00e9dial (ulna)"}, {"n": 5, "x": 230, "y": 345, "t": "Hum\u00e9ro-radiale", "ancre": "middle", "indice": "coude, c\u00f4t\u00e9 lat\u00e9ral (radius)"}, {"n": 6, "x": 150, "y": 395, "t": "Radio-ulnaire proximale", "ancre": "middle", "indice": "entre radius et ulna, juste sous le coude"}, {"n": 7, "x": 198, "y": 545, "t": "Radio-carpienne", "ancre": "middle", "indice": "poignet ; radius + scapho\u00efde + lunatum"}, {"n": 8, "x": 92, "y": 515, "t": "Radio-ulnaire distale", "ancre": "middle", "indice": "entre radius et ulna, c\u00f4t\u00e9 m\u00e9dial du poignet"}], "slide": 194}, {"id": "scapula-reperes", "titre": "La scapula, vue post\u00e9rieure : ses rep\u00e8res", "vb": "0 0 300 320", "dessin": "<g class='os' fill='none' stroke='currentColor' stroke-width='2'><path d='M75,55 L215,92 L108,300 Z'/><path d='M92,92 L202,113' stroke-width='4'/><path d='M202,113 Q223,100 228,78' stroke-width='4' stroke-linecap='round'/><path d='M192,78 Q183,50 206,44' stroke-width='4' stroke-linecap='round'/><ellipse cx='207' cy='122' rx='15' ry='11'/></g>", "pastilles": [{"n": 1, "x": 202, "y": 47, "t": "Processus coraco\u00efde", "ancre": "middle", "indice": "crochet \u00e0 l'avant, lieu d'insertions musculaires"}, {"n": 2, "x": 140, "y": 100, "t": "\u00c9pine", "ancre": "middle", "indice": "cr\u00eate qui traverse la face post\u00e9rieure"}, {"n": 3, "x": 228, "y": 78, "t": "Acromion", "ancre": "middle", "indice": "extr\u00e9mit\u00e9 lat\u00e9rale de l'\u00e9pine ; articulation acromio-claviculaire"}, {"n": 4, "x": 207, "y": 122, "t": "Cavit\u00e9 gl\u00e9no\u00efdale", "ancre": "middle", "indice": "re\u00e7oit la t\u00eate hum\u00e9rale"}], "slide": 202}, {"id": "deltoide-trois-faisceaux", "titre": "Le delto\u00efde, vue lat\u00e9rale : ses 3 faisceaux", "vb": "0 0 300 300", "dessin": "<g class='os' fill='none' stroke='currentColor' stroke-width='2'><path d='M65,40 Q105,26 148,46'/><path d='M152,46 Q195,42 235,58'/><circle cx='150' cy='46' r='4' fill='currentColor' stroke='none'/><path d='M150,88 L150,335' stroke-width='11' stroke-linecap='round'/></g><g class='faisceau' fill='none' stroke='currentColor' stroke-width='1.4'><path d='M65,40 L128,180'/><path d='M65,40 L140,196'/><path d='M65,40 L150,212'/><path d='M150,46 L144,180'/><path d='M150,46 L150,196'/><path d='M150,46 L156,212'/><path d='M235,58 L172,180'/><path d='M235,58 L160,196'/><path d='M235,58 L150,212'/></g>", "pastilles": [{"n": 1, "x": 78, "y": 100, "t": "Claviculaire", "ancre": "middle", "indice": "faisceau ant\u00e9rieur, origine sur la clavicule"}, {"n": 2, "x": 150, "y": 132, "t": "Acromial", "ancre": "middle", "indice": "faisceau interm\u00e9diaire, origine sur l'acromion"}, {"n": 3, "x": 222, "y": 100, "t": "\u00c9pineux", "ancre": "middle", "indice": "faisceau post\u00e9rieur, origine sur l'\u00e9pine de la scapula"}, {"n": 4, "x": 150, "y": 228, "t": "Tub\u00e9rosit\u00e9 delto\u00efdienne", "ancre": "middle", "indice": "insertion commune des 3 faisceaux, sur l'hum\u00e9rus"}], "slide": 247}, {"id": "coiffe-rotateurs-vue-postero-laterale", "titre": "La coiffe des rotateurs, vue post\u00e9ro-lat\u00e9rale", "vb": "0 0 300 340", "dessin": "<g class='os' fill='none' stroke='currentColor' stroke-width='2'><path d='M100,40 L240,90 L130,340 Z'/><path d='M115,95 L225,115' stroke-width='3'/><path d='M225,115 Q245,100 250,80' stroke-width='3' stroke-linecap='round'/><circle cx='255' cy='150' r='26'/></g><g class='muscle' fill='none' stroke='currentColor' stroke-width='1.3'><path d='M130,60 L235,128'/><path d='M150,70 L238,138'/><path d='M170,80 L236,148'/><path d='M130,150 L232,158'/><path d='M140,190 L228,165'/><path d='M150,230 L224,172'/><path d='M150,260 L220,180'/><path d='M155,285 L216,186'/><path d='M150,300 L214,192' stroke-dasharray='3 3'/><path d='M155,320 L212,198' stroke-dasharray='3 3'/></g>", "pastilles": [{"n": 1, "x": 150, "y": 68, "t": "Supra-\u00e9pineux", "ancre": "middle", "indice": "au-dessus de l'\u00e9pine ; le plus fragile de la coiffe"}, {"n": 2, "x": 165, "y": 180, "t": "Infra-\u00e9pineux", "ancre": "middle", "indice": "sous l'\u00e9pine ; la plus grande surface"}, {"n": 3, "x": 158, "y": 268, "t": "Petit rond", "ancre": "middle", "indice": "bande \u00e9troite, bord lat\u00e9ral, sous l'infra-\u00e9pineux"}, {"n": 4, "x": 152, "y": 308, "t": "Subscapulaire", "ancre": "middle", "indice": "face ant\u00e9rieure (costale) ; non visible de dos, figur\u00e9 en pointill\u00e9"}], "slide": 251}]}, {"num": 7, "titre": "Le membre inf\u00e9rieur", "slides": [268, 328], "sections": [{"titre": "Le squelette du membre inf\u00e9rieur : 4 segments", "slide": 270, "points": ["Le squelette du membre inf\u00e9rieur comprend 4 segments : la ceinture pelvienne, la cuisse, la jambe et le pied."]}, {"titre": "Vue d'ensemble : segments, os et articulations", "slide": 271, "points": ["Ceinture pelvienne : sacrum + os coxal ; articulation sacro-iliaque et articulation coxo-f\u00e9morale (hanche).", "Cuisse : f\u00e9mur. Jambe : tibia (m\u00e9dial) + fibula (lat\u00e9rale) ; articulation f\u00e9moro-patellaire et articulation tibio-f\u00e9morale (genou) entre les deux.", "Pied : articulation talo-crurale (cheville). La cuisse, la jambe et le pied forment ensemble la \u00ab partie libre du membre inf\u00e9rieur \u00bb."]}, {"titre": "A. La ceinture pelvienne", "slide": 273, "points": ["Elle est constitu\u00e9e par 2 os coxaux + le sacrum et le coccyx.", "\u00c9galement appel\u00e9e bassin ou pelvis."]}, {"titre": "Les 4 articulations de la ceinture pelvienne", "slide": 275, "points": ["La symphyse pubienne.", "2 articulations sacro-iliaques (une de chaque c\u00f4t\u00e9).", "L'articulation sacro-coccygienne."]}, {"titre": "L'os coxal : 3 parties", "slide": 277, "points": ["C'est l'os de la hanche, compos\u00e9 de 3 parties : l'ilium (partie sup\u00e9rieure), l'ischium (partie post\u00e9ro-inf\u00e9rieure), le pubis (partie ant\u00e9ro-inf\u00e9rieure).", "Os plat qui s'articule m\u00e9dialement avec le sacrum (articulation sacro-iliaque) et lat\u00e9ralement avec le f\u00e9mur, au niveau de la t\u00eate f\u00e9morale (articulation coxo-f\u00e9morale)."]}, {"titre": "L'os coxal : ancienne et nouvelle nomenclature", "slide": 278, "points": ["Nomenclature actuelle : ilium, ischium, pubis.", "Ancienne nomenclature : ilion, ischion, pubis \u2014 seul le nom du pubis est rest\u00e9 identique."]}, {"titre": "L'os coxal : rep\u00e8res", "slide": 279, "points": ["Vue ant\u00e9rieure : cr\u00eate iliaque, fosse iliaque, \u00e9pine iliaque ant\u00e9ro-sup\u00e9rieure, \u00e9pine iliaque ant\u00e9ro-inf\u00e9rieure, pubis.", "Vue lat\u00e9rale : ac\u00e9tabulum, foramen obtur\u00e9, \u00e9pine ischiatique, tub\u00e9rosit\u00e9 ischiatique."]}, {"titre": "B. La cuisse : un seul os, le f\u00e9mur", "slide": 282, "points": ["Os long qui s'articule en haut avec l'os coxal, au niveau de l'ac\u00e9tabulum, pour former l'articulation coxo-f\u00e9morale.", "En bas avec le tibia, au niveau du plateau tibial, pour former l'articulation tibio-f\u00e9morale ; et avec la patella (rotule) pour former l'articulation f\u00e9moro-patellaire."]}, {"titre": "Le f\u00e9mur : rep\u00e8res", "slide": 284, "points": ["Extr\u00e9mit\u00e9 proximale : t\u00eate f\u00e9morale, grand trochanter, petit trochanter.", "Extr\u00e9mit\u00e9 distale : \u00e9picondyle m\u00e9dial, condyle m\u00e9dial, condyle lat\u00e9ral, surface patellaire."]}, {"titre": "C. La jambe : 2 os", "slide": 288, "points": ["Le tibia, os m\u00e9dial de la jambe : s'articule en haut avec le f\u00e9mur (condyles f\u00e9moraux \u2192 tibio-f\u00e9morale), en bas avec le talus (\u2192 talo-crurale m\u00e9diale), lat\u00e9ralement avec la fibula (\u2192 tibio-fibulaires proximale et distale).", "La fibula, os lat\u00e9ral de la jambe : s'articule en haut et m\u00e9dialement avec le tibia (\u2192 tibio-fibulaire proximale), en bas avec le talus (\u2192 talo-crurale lat\u00e9rale), en bas et m\u00e9dialement avec le tibia (\u2192 tibio-fibulaire distale)."]}, {"titre": "Le tibia et la fibula : rep\u00e8res", "slide": 289, "points": ["Tibia : condyles m\u00e9dial et lat\u00e9ral, plateau tibial, tub\u00e9rosit\u00e9 du tibia, mall\u00e9ole m\u00e9diale (tibiale).", "Fibula : t\u00eate de la fibula, mall\u00e9ole lat\u00e9rale (fibulaire)."]}, {"titre": "La patella", "slide": 290, "points": ["Os court, situ\u00e9 en avant de la base du f\u00e9mur, sur le trajet du tendon du quadriceps.", "Elle s'articule avec le f\u00e9mur pour former l'articulation f\u00e9moro-patellaire."]}, {"titre": "Le genou (articulation tibio-f\u00e9morale)", "slide": 291, "points": ["Ligament patellaire \u00e0 l'avant ; ligament crois\u00e9 ant\u00e9rieur (LCA) et ligament crois\u00e9 post\u00e9rieur (LCP) au centre de l'articulation.", "M\u00e9nisque m\u00e9dial et m\u00e9nisque lat\u00e9ral, sur le plateau tibial."]}, {"titre": "D. Le pied : 26 os en 3 groupes", "slide": 294, "points": ["Le tarse (7 os, dont le talus/astragale et le calcaneus).", "Le m\u00e9tatarse (5 m\u00e9tatarsiens).", "Les phalanges du pied (3 par orteil, sauf le gros orteil qui n'en a que 2)."]}, {"titre": "L'articulation de la cheville", "slide": 295, "points": ["L'articulation talo-crurale unit le tibia et la fibula au talus.", "Elle joue un r\u00f4le primordial dans la marche ; c'est l'articulation la plus sujette aux entorses."]}, {"titre": "II-A. Muscles de la ceinture pelvienne", "slide": 298, "points": ["Muscles principaux : ilio-psoas (iliaque), grand/moyen/petit glut\u00e9al, tenseur du fascia lata.", "Muscles profonds, rotateurs lat\u00e9raux de la cuisse : piriforme, obturateur interne et externe, jumeau sup\u00e9rieur et inf\u00e9rieur, carr\u00e9 f\u00e9moral."]}, {"titre": "L'ilio-psoas", "slide": 299, "points": ["Compos\u00e9 de 2 muscles : le grand psoas (muscle lat\u00e9ral du tronc) et l'iliaque (muscle de la hanche).", "Origine : face ant\u00e9rieure de l'os coxal (fosse iliaque). Terminaison : petit trochanter du f\u00e9mur.", "Il est fl\u00e9chisseur de la cuisse."]}, {"titre": "Le petit glut\u00e9al", "slide": 300, "points": ["Origine : face externe de l'ilium. Terminaison : grand trochanter du f\u00e9mur.", "Abducteur et rotateur m\u00e9dial de la cuisse."]}, {"titre": "Le moyen glut\u00e9al", "slide": 301, "points": ["Origine : face externe de l'ilium. Terminaison : grand trochanter du f\u00e9mur.", "Abducteur de la cuisse et stabilisateur du bassin."]}, {"titre": "Le grand glut\u00e9al", "slide": 302, "points": ["Origine : face externe de l'ilium, cr\u00eate iliaque, cr\u00eate sacrale. Terminaison : face post\u00e9rieure du f\u00e9mur.", "Extenseur et rotateur lat\u00e9ral de la cuisse. Stabilisateur du bassin."]}, {"titre": "Le tenseur du fascia lata", "slide": 303, "points": ["Origine : \u00e9pine iliaque ant\u00e9ro-sup\u00e9rieure. Terminaison : tractus ilio-tibial (qui se termine sur le plateau tibial lat\u00e9ral).", "Abducteur, rotateur m\u00e9dial et fl\u00e9chisseur de la cuisse ; extenseur de la jambe."]}, {"titre": "Muscles de la cuisse : 3 groupes", "slide": 306, "points": ["Groupe ant\u00e9rieur : extenseur du genou.", "Groupe m\u00e9dial : adducteur de la cuisse.", "Groupe post\u00e9rieur : fl\u00e9chisseur du genou."]}, {"titre": "Groupe ant\u00e9rieur : 2 muscles", "slide": 308, "points": ["Sartorius.", "Quadriceps (f\u00e9moral)."]}, {"titre": "Le sartorius (couturier)", "slide": 309, "points": ["Origine : \u00e9pine iliaque ant\u00e9ro-sup\u00e9rieure. Terminaison : patte d'oie.", "Fl\u00e9chisseur de la cuisse et de la jambe ; rotateur lat\u00e9ral et abducteur de la cuisse."]}, {"titre": "Le quadriceps f\u00e9moral : 4 chefs", "slide": 310, "points": ["4 chefs/faisceaux : le droit f\u00e9moral, le vaste lat\u00e9ral, le vaste interm\u00e9diaire, le vaste m\u00e9dial.", "Le tendon du droit f\u00e9moral passe par-dessus la patella pour rejoindre le ligament patellaire."]}, {"titre": "Le quadriceps f\u00e9moral : origines, terminaison commune, actions", "slide": 311, "points": ["Droit f\u00e9moral : origine \u00e9pine iliaque ant\u00e9ro-inf\u00e9rieure. Vaste m\u00e9dial : bord m\u00e9dial du f\u00e9mur. Vaste lat\u00e9ral : bord lat\u00e9ral du f\u00e9mur. Vaste interm\u00e9diaire : face ant\u00e9rieure du f\u00e9mur.", "Terminaison commune des 4 chefs : tendon commun de la patella, puis tub\u00e9rosit\u00e9 tibiale (ligament patellaire).", "Tous les 4 sont extenseurs du genou ; le droit f\u00e9moral est en plus fl\u00e9chisseur de la cuisse."]}, {"titre": "Groupe m\u00e9dial : 5 muscles", "slide": 312, "points": ["Pectin\u00e9.", "Court, long et grand adducteur.", "Gracile."]}, {"titre": "Le court adducteur", "slide": 313, "points": ["Origine : pubis. Terminaison : ligne \u00e2pre du f\u00e9mur.", "Adducteur de la cuisse."]}, {"titre": "Le long adducteur", "slide": 314, "points": ["Origine : pubis. Terminaison : ligne \u00e2pre du f\u00e9mur.", "Adducteur, fl\u00e9chisseur et rotateur m\u00e9dial de la cuisse."]}, {"titre": "Le grand adducteur", "slide": 315, "points": ["3 faisceaux. Origines : pubis, tub\u00e9rosit\u00e9 ischiatique. Terminaisons : ligne \u00e2pre du f\u00e9mur, \u00e9picondyle m\u00e9dial du f\u00e9mur.", "Adducteur de la cuisse."]}, {"titre": "Le gracile", "slide": 316, "points": ["Origine : pubis. Terminaison : patte d'oie.", "Fl\u00e9chisseur et rotateur m\u00e9dial de la jambe ; adducteur de la cuisse."]}, {"titre": "Groupe post\u00e9rieur : les ischio-jambiers", "slide": 318, "points": ["3 muscles : biceps f\u00e9moral, semi-tendineux, semi-membraneux.", "Ils forment les ischio-jambiers."]}, {"titre": "Le biceps f\u00e9moral", "slide": 319, "points": ["2 faisceaux. Origines : chef long, tub\u00e9rosit\u00e9 ischiatique ; chef court, ligne \u00e2pre du f\u00e9mur. Terminaison : t\u00eate de la fibula.", "Fl\u00e9chisseur de la jambe ; extenseur de la cuisse (chef long)."]}, {"titre": "Le semi-tendineux et le semi-membraneux", "slide": 320, "points": ["Origine (les 2) : tub\u00e9rosit\u00e9 ischiatique.", "Terminaison : semi-tendineux \u2192 patte d'oie ; semi-membraneux \u2192 plateau tibial.", "Fl\u00e9chisseurs de la jambe ; extenseurs de la cuisse."]}, {"titre": "Muscles de la jambe : groupe ant\u00e9rieur", "slide": 324, "points": ["Tibial ant\u00e9rieur.", "Long extenseur de l'hallux.", "Court, long et troisi\u00e8me fibulaire.", "Long extenseur des orteils."]}, {"titre": "Le tibial ant\u00e9rieur", "slide": 325, "points": ["Origine : bord lat\u00e9ral du tibia. Terminaison : bord m\u00e9dial du gros orteil.", "Fl\u00e9chisseur dorsal du pied."]}, {"titre": "Muscles de la jambe : groupe post\u00e9rieur", "slide": 326, "points": ["Groupe superficiel : triceps sural, plantaire.", "Groupe profond : poplit\u00e9, tibial post\u00e9rieur, long fl\u00e9chisseur des orteils, long fl\u00e9chisseur de l'hallux."]}, {"titre": "Le triceps sural", "slide": 327, "points": ["Compos\u00e9 du gastrocn\u00e9mien et du sol\u00e9aire (et du plantaire)."]}, {"titre": "Gastrocn\u00e9mien et sol\u00e9aire", "slide": 328, "points": ["Gastrocn\u00e9mien : 2 chefs (m\u00e9dial + lat\u00e9ral). Origine : condyles m\u00e9dial et lat\u00e9ral du f\u00e9mur. Terminaison : calcan\u00e9us (tendon calcan\u00e9en).", "Sol\u00e9aire : origine, \u00e9piphyses proximales du tibia et de la fibula. Terminaison : calcan\u00e9us (tendon calcan\u00e9en).", "Gastrocn\u00e9mien : fl\u00e9chisseur de la jambe et fl\u00e9chisseur plantaire du pied. Sol\u00e9aire : fl\u00e9chisseur plantaire du pied seulement."]}], "cartes": [{"id": "c7-01", "q": "Quels sont les 4 segments du squelette du membre inf\u00e9rieur ?", "r": "La ceinture pelvienne, la cuisse, la jambe et le pied.", "slide": 270}, {"id": "c7-02", "q": "Pour chaque segment du membre inf\u00e9rieur, quel(s) os le compose(nt) et quelles articulations apparaissent ?", "r": "Ceinture pelvienne : sacrum + os coxal ; articulations sacro-iliaque et coxo-f\u00e9morale (hanche). Cuisse : f\u00e9mur ; articulations f\u00e9moro-patellaire et tibio-f\u00e9morale (genou). Jambe : tibia + fibula ; articulation talo-crurale (cheville). Pied : partie distale, en aval de la cheville.", "slide": 271}, {"id": "c7-03", "q": "Comment est constitu\u00e9e la ceinture pelvienne, et quelles sont ses 4 articulations ?", "r": "Elle est constitu\u00e9e de 2 os coxaux + le sacrum + le coccyx (autres noms : bassin, pelvis). Ses 4 articulations : la symphyse pubienne, les 2 sacro-iliaques (une par c\u00f4t\u00e9), et la sacro-coccygienne.", "slide": 273}, {"id": "c7-04", "q": "L'os coxal est compos\u00e9 de 3 parties : lesquelles, et avec quels 2 os s'articule-t-il ?", "r": "Ilium (partie sup\u00e9rieure), ischium (partie post\u00e9ro-inf\u00e9rieure), pubis (partie ant\u00e9ro-inf\u00e9rieure). Il s'articule m\u00e9dialement avec le sacrum (articulation sacro-iliaque) et lat\u00e9ralement avec le f\u00e9mur, au niveau de la t\u00eate f\u00e9morale (articulation coxo-f\u00e9morale).", "slide": 277}, {"id": "c7-05", "q": "Quels sont les noms actuels des 3 parties de l'os coxal, et quels \u00e9taient leurs noms dans l'ancienne nomenclature ?", "r": "Ilium, ischium et pubis (nomenclature actuelle) correspondent \u00e0 ilion, ischion et pubis dans l'ancienne nomenclature \u2014 seul le nom du pubis n'a pas chang\u00e9.", "slide": 278}, {"id": "c7-06", "q": "Sur l'os coxal, o\u00f9 se trouvent la cr\u00eate iliaque, la fosse iliaque, l'ac\u00e9tabulum et le foramen obtur\u00e9 ?", "r": "La cr\u00eate iliaque borde le sommet de l'ilium, la fosse iliaque en occupe la face interne. L'ac\u00e9tabulum et le foramen obtur\u00e9 sont \u00e0 la jonction des 3 parties (l'ac\u00e9tabulum re\u00e7oit la t\u00eate f\u00e9morale).", "slide": 279}, {"id": "c7-07", "q": "Avec quels os le f\u00e9mur s'articule-t-il, et quels rep\u00e8res porte-t-il \u00e0 ses 2 extr\u00e9mit\u00e9s ?", "r": "Il s'articule en haut avec l'os coxal (ac\u00e9tabulum \u2192 coxo-f\u00e9morale), en bas avec le tibia (plateau tibial \u2192 tibio-f\u00e9morale) et avec la patella (\u2192 f\u00e9moro-patellaire). Extr\u00e9mit\u00e9 proximale : t\u00eate f\u00e9morale, grand trochanter, petit trochanter. Extr\u00e9mit\u00e9 distale : \u00e9picondyle m\u00e9dial, condyle m\u00e9dial, condyle lat\u00e9ral, surface patellaire.", "slide": 282}, {"id": "c7-08", "q": "Le tibia et la fibula : lequel est m\u00e9dial, lequel est lat\u00e9ral, avec quels os s'articulent-ils, et quels rep\u00e8res portent-ils ?", "r": "Le tibia est M\u00c9DIAL (plateau tibial, tub\u00e9rosit\u00e9 du tibia, mall\u00e9ole m\u00e9diale) ; il s'articule avec le f\u00e9mur (tibio-f\u00e9morale), le talus (talo-crurale m\u00e9diale) et la fibula (tibio-fibulaire proximale et distale). La fibula est LAT\u00c9RALE (t\u00eate de la fibula, mall\u00e9ole lat\u00e9rale) ; elle s'articule avec le tibia (tibio-fibulaire proximale et distale) et le talus (talo-crurale lat\u00e9rale).", "slide": 288}, {"id": "c7-09", "q": "O\u00f9 est situ\u00e9e la patella, et quelle articulation forme-t-elle ?", "r": "Os court, situ\u00e9 en avant de la base du f\u00e9mur, sur le trajet du tendon du quadriceps. Elle s'articule avec le f\u00e9mur pour former l'articulation f\u00e9moro-patellaire.", "slide": 290}, {"id": "c7-10", "q": "Le genou (articulation tibio-f\u00e9morale) comporte quels ligaments et quels m\u00e9nisques ?", "r": "Ligament crois\u00e9 ant\u00e9rieur (LCA) et ligament crois\u00e9 post\u00e9rieur (LCP) ; m\u00e9nisque m\u00e9dial et m\u00e9nisque lat\u00e9ral, sur le plateau tibial. Le ligament patellaire y arrive c\u00f4t\u00e9 ant\u00e9rieur.", "slide": 291}, {"id": "c7-11", "q": "Combien d'os compte le pied, comment se r\u00e9partissent-ils, et quelle particularit\u00e9 pr\u00e9sente l'articulation de la cheville ?", "r": "26 os en 3 groupes : le tarse (7 os, dont le talus et le calcan\u00e9us), le m\u00e9tatarse (5 m\u00e9tatarsiens), les phalanges (3 par orteil sauf le gros orteil qui n'en a que 2). La cheville (articulation talo-crurale) unit le tibia et la fibula au talus : c'est l'articulation la plus sujette aux entorses.", "slide": 294}, {"id": "c7-12", "q": "Quels sont les muscles principaux et les muscles profonds de la ceinture pelvienne ?", "r": "Principaux : ilio-psoas, petit/moyen/grand glut\u00e9al, tenseur du fascia lata. Profonds, rotateurs lat\u00e9raux de la cuisse : piriforme, obturateur interne et externe, jumeau sup\u00e9rieur et inf\u00e9rieur, carr\u00e9 f\u00e9moral.", "slide": 298}, {"id": "c7-13", "q": "L'ilio-psoas est compos\u00e9 de 2 muscles : lesquels, et quelle est son action ?", "r": "Le grand psoas (muscle lat\u00e9ral du tronc) et l'iliaque (muscle de la hanche). Origine : face ant\u00e9rieure de l'os coxal (fosse iliaque). Terminaison : petit trochanter du f\u00e9mur. Il est fl\u00e9chisseur de la cuisse.", "slide": 299}, {"id": "c7-14", "q": "Petit glut\u00e9al et moyen glut\u00e9al partagent origine et terminaison : quelle est la diff\u00e9rence de leurs actions ?", "r": "Les 2 s'originent sur la face externe de l'ilium et se terminent sur le grand trochanter du f\u00e9mur. Le petit glut\u00e9al est abducteur ET rotateur m\u00e9dial de la cuisse ; le moyen glut\u00e9al est abducteur de la cuisse et stabilisateur du bassin (pas rotateur).", "slide": 300}, {"id": "c7-15", "q": "Quelles sont l'origine, la terminaison et l'action du grand glut\u00e9al ?", "r": "Origine : face externe de l'ilium, cr\u00eate iliaque, cr\u00eate sacrale. Terminaison : face post\u00e9rieure du f\u00e9mur. Actions : extenseur et rotateur lat\u00e9ral de la cuisse, stabilisateur du bassin.", "slide": 302}, {"id": "c7-16", "q": "Sur quelle structure se termine le tenseur du fascia lata, et quelles sont ses actions ?", "r": "Il se termine sur le tractus ilio-tibial, qui rejoint le plateau tibial lat\u00e9ral. Actions : abducteur, rotateur m\u00e9dial et fl\u00e9chisseur de la cuisse ; extenseur de la jambe.", "slide": 303}, {"id": "c7-17", "q": "Quels sont les 3 groupes de muscles de la cuisse, et l'action caract\u00e9ristique de chacun ?", "r": "Groupe ant\u00e9rieur : extenseur du genou. Groupe m\u00e9dial : adducteur de la cuisse. Groupe post\u00e9rieur : fl\u00e9chisseur du genou.", "slide": 306}, {"id": "c7-18", "q": "Quelles sont l'origine, la terminaison et les actions du sartorius ?", "r": "Origine : \u00e9pine iliaque ant\u00e9ro-sup\u00e9rieure. Terminaison : patte d'oie. Actions : fl\u00e9chisseur de la cuisse et de la jambe, rotateur lat\u00e9ral et abducteur de la cuisse.", "slide": 309, "plan": "transversal"}, {"id": "c7-19", "q": "Le quadriceps f\u00e9moral a 4 chefs : lesquels, et par quelle structure se termine-t-il ?", "r": "Droit f\u00e9moral, vaste lat\u00e9ral, vaste interm\u00e9diaire, vaste m\u00e9dial. Le tendon du droit f\u00e9moral passe par-dessus la patella pour rejoindre le ligament patellaire : c'est la terminaison commune des 4 chefs.", "slide": 310, "plan": "sagittal"}, {"id": "c7-20", "q": "Pourquoi le droit f\u00e9moral est-il le seul chef du quadriceps \u00e0 \u00eatre aussi fl\u00e9chisseur de la cuisse ?", "r": "Parce qu'il est le seul des 4 chefs \u00e0 s'originer au-del\u00e0 du f\u00e9mur, sur l'\u00e9pine iliaque ant\u00e9ro-inf\u00e9rieure (os coxal) : il franchit donc l'articulation coxo-f\u00e9morale (la hanche). Les 3 vastes s'originent directement sur le f\u00e9mur (bord m\u00e9dial, bord lat\u00e9ral, face ant\u00e9rieure) : ils ne franchissent que le genou, et ne sont donc extenseurs du genou que.", "slide": 311, "plan": "sagittal"}, {"id": "c7-21", "q": "Quels sont les 5 muscles du groupe m\u00e9dial (adducteurs) de la cuisse, et qu'est-ce qui distingue le long adducteur des 2 autres adducteurs ?", "r": "Pectin\u00e9, court adducteur, long adducteur, grand adducteur, gracile. Le court et le grand adducteur ne sont qu'adducteurs de la cuisse ; le long adducteur est en plus fl\u00e9chisseur et rotateur m\u00e9dial de la cuisse.", "slide": 312, "plan": "frontal"}, {"id": "c7-22", "q": "Les 3 ischio-jambiers partagent origine et actions : quelle est la terminaison propre \u00e0 chacun, et quelle nuance porte le biceps f\u00e9moral ?", "r": "Tous les 3 s'originent (au moins en partie) sur la tub\u00e9rosit\u00e9 ischiatique et sont fl\u00e9chisseurs de la jambe, extenseurs de la cuisse. Terminaisons diff\u00e9rentes : biceps f\u00e9moral \u2192 t\u00eate de la fibula ; semi-tendineux \u2192 patte d'oie ; semi-membraneux \u2192 plateau tibial. Nuance : seul le chef long du biceps f\u00e9moral (origine tub\u00e9rosit\u00e9 ischiatique) est extenseur de la cuisse \u2014 son chef court s'origine sur la ligne \u00e2pre du f\u00e9mur et ne franchit donc pas la hanche.", "slide": 320}, {"id": "c7-23", "q": "Quels 3 muscles convergent \u00e0 la patte d'oie, et en quoi cette convergence est-elle remarquable ?", "r": "Le sartorius (groupe ant\u00e9rieur), le gracile (groupe m\u00e9dial, adducteurs) et le semi-tendineux (groupe post\u00e9rieur, ischio-jambiers) : 3 muscles de 3 groupes diff\u00e9rents, d'origines et de fonctions diff\u00e9rentes, qui se terminent tous au m\u00eame endroit, sur le bord m\u00e9dial du tibia.", "slide": 320}, {"id": "c7-24", "q": "Quels muscles composent le groupe ant\u00e9rieur de la jambe, et quelles sont l'origine, la terminaison et l'action du tibial ant\u00e9rieur ?", "r": "Tibial ant\u00e9rieur, long extenseur de l'hallux, court/long/troisi\u00e8me fibulaire, long extenseur des orteils. Le tibial ant\u00e9rieur : origine bord lat\u00e9ral du tibia, terminaison bord m\u00e9dial du gros orteil, action fl\u00e9chisseur dorsal du pied.", "slide": 324}, {"id": "c7-25", "q": "Le triceps sural est compos\u00e9 de quels muscles, et pourquoi seul l'un d'eux est aussi fl\u00e9chisseur de la jambe ?", "r": "Du gastrocn\u00e9mien et du sol\u00e9aire (et du plantaire). Le gastrocn\u00e9mien s'origine sur les condyles m\u00e9dial et lat\u00e9ral du F\u00c9MUR : il franchit le genou, donc il est fl\u00e9chisseur de la jambe ET fl\u00e9chisseur plantaire du pied. Le sol\u00e9aire s'origine sur le tibia et la fibula : il ne franchit que la cheville, donc seulement fl\u00e9chisseur plantaire du pied. Les deux se terminent ensemble sur le calcan\u00e9us par le tendon calcan\u00e9en.", "slide": 327}], "quiz": [{"id": "q7-01", "q": "Parmi les 4 chefs du quadriceps, lequel est aussi fl\u00e9chisseur de la cuisse, en plus d'\u00eatre extenseur du genou ?", "choix": ["le droit f\u00e9moral", "le vaste lat\u00e9ral", "le vaste m\u00e9dial", "le vaste interm\u00e9diaire"], "bonne": 0, "expl": "Seul le droit f\u00e9moral s'origine sur l'os coxal (\u00e9pine iliaque ant\u00e9ro-inf\u00e9rieure) : il franchit la hanche, donc il la fl\u00e9chit aussi. Les 3 vastes s'originent directement sur le f\u00e9mur et n'agissent que sur le genou.", "slide": 311, "plan": "sagittal"}, {"id": "q7-02", "q": "Quelle est la terminaison du biceps f\u00e9moral, diff\u00e9rente de celle du semi-tendineux et du semi-membraneux ?", "choix": ["la t\u00eate de la fibula", "la patte d'oie", "le plateau tibial", "le calcan\u00e9us"], "bonne": 0, "expl": "Le biceps f\u00e9moral se termine sur la t\u00eate de la fibula (c\u00f4t\u00e9 lat\u00e9ral) ; le semi-tendineux \u00e0 la patte d'oie, le semi-membraneux sur le plateau tibial (tous deux m\u00e9diaux).", "slide": 320}, {"id": "q7-03", "q": "Parmi les ischio-jambiers, quel est le seul qui se termine \u00e0 la patte d'oie ?", "choix": ["le semi-tendineux", "le semi-membraneux", "le biceps f\u00e9moral", "aucun : ils se terminent tous \u00e0 la t\u00eate de la fibula"], "bonne": 0, "expl": "Semi-tendineux \u2192 patte d'oie. Semi-membraneux \u2192 plateau tibial. Biceps f\u00e9moral \u2192 t\u00eate de la fibula. Trois terminaisons diff\u00e9rentes pour une m\u00eame origine et les m\u00eames actions.", "slide": 320}, {"id": "q7-04", "q": "La patte d'oie est le point de terminaison commun de 3 muscles. Lesquels ?", "choix": ["sartorius, gracile, semi-tendineux", "sartorius, gracile, semi-membraneux", "sartorius, long adducteur, semi-tendineux", "gracile, semi-tendineux, biceps f\u00e9moral"], "bonne": 0, "expl": "Sartorius (groupe ant\u00e9rieur), gracile (groupe m\u00e9dial) et semi-tendineux (groupe post\u00e9rieur) convergent tous \u00e0 la patte d'oie \u2014 trois groupes diff\u00e9rents, un seul point d'arriv\u00e9e. Le semi-membraneux (souvent confondu) se termine plus profond\u00e9ment sur le plateau tibial.", "slide": 320}, {"id": "q7-05", "q": "Pourquoi le gastrocn\u00e9mien est-il fl\u00e9chisseur de la jambe, alors que le sol\u00e9aire ne l'est pas ?", "choix": ["il s'origine sur le f\u00e9mur et franchit donc le genou", "il s'origine sur le tibia et la fibula", "il se termine plus haut que le sol\u00e9aire", "il a 2 chefs alors que le sol\u00e9aire n'en a qu'un"], "bonne": 0, "expl": "Le gastrocn\u00e9mien s'origine sur les condyles m\u00e9dial et lat\u00e9ral du f\u00e9mur : il franchit le genou, donc il le fl\u00e9chit. Le sol\u00e9aire s'origine sur le tibia et la fibula, sous le genou : il ne peut agir que sur la cheville.", "slide": 328}, {"id": "q7-06", "q": "La ceinture pelvienne compte 4 articulations. Lesquelles ?", "choix": ["symphyse pubienne + 2 sacro-iliaques + sacro-coccygienne", "symphyse pubienne + 2 sacro-iliaques + coxo-f\u00e9morale", "2 sacro-iliaques + 2 coxo-f\u00e9morales", "symphyse pubienne + sacro-coccygienne + coxo-f\u00e9morale"], "bonne": 0, "expl": "La symphyse pubienne (1), les 2 articulations sacro-iliaques (2), et la sacro-coccygienne (1) = 4. La coxo-f\u00e9morale (hanche) n'appartient PAS \u00e0 la ceinture pelvienne : c'est l'articulation qui unit le membre inf\u00e9rieur libre \u00e0 cette ceinture.", "slide": 275}, {"id": "q7-07", "q": "Quelles sont les 3 parties de l'os coxal, dans la nomenclature actuelle ?", "choix": ["ilium, ischium, pubis", "ilion, ischion, pubis", "ilium, ischion, pubis", "ilium, ischium, sacrum"], "bonne": 0, "expl": "Ilium, ischium et pubis (nomenclature actuelle). Ilion et ischion sont les anciens noms d'ilium et ischium \u2014 seul pubis n'a pas chang\u00e9. Le sacrum n'est pas une partie de l'os coxal.", "slide": 278}, {"id": "q7-08", "q": "Le pied compte 26 os. Comment se r\u00e9partissent-ils ?", "choix": ["7 tarsiens, 5 m\u00e9tatarsiens, 14 phalanges", "8 tarsiens, 5 m\u00e9tatarsiens, 13 phalanges", "7 tarsiens, 6 m\u00e9tatarsiens, 13 phalanges", "7 tarsiens, 5 m\u00e9tatarsiens, 15 phalanges"], "bonne": 0, "expl": "7 (tarse) + 5 (m\u00e9tatarse) + 14 (phalanges : 3 par orteil sauf le gros orteil qui n'en a que 2, soit 3\u00d74+2=14) = 26.", "slide": 294}, {"id": "q7-09", "q": "Quelle articulation du membre inf\u00e9rieur est la plus sujette aux entorses ?", "choix": ["l'articulation talo-crurale (la cheville)", "l'articulation tibio-f\u00e9morale (le genou)", "l'articulation coxo-f\u00e9morale (la hanche)", "l'articulation sacro-iliaque"], "bonne": 0, "expl": "L'articulation de la cheville (talo-crurale), qui unit le tibia et la fibula au talus, est la plus sujette aux entorses du membre inf\u00e9rieur.", "slide": 295}, {"id": "q7-10", "q": "Sur quelle structure se termine le tenseur du fascia lata ?", "choix": ["le tractus ilio-tibial (jusqu'au plateau tibial lat\u00e9ral)", "la patte d'oie", "la t\u00eate de la fibula", "le grand trochanter du f\u00e9mur"], "bonne": 0, "expl": "Le tenseur du fascia lata se termine sur le tractus ilio-tibial, qui rejoint le plateau tibial lat\u00e9ral \u2014 \u00e0 ne pas confondre avec la patte d'oie (sartorius, gracile, semi-tendineux), un point de terminaison diff\u00e9rent et m\u00e9dial.", "slide": 303}, {"id": "q7-11", "q": "Parmi les adducteurs de la cuisse, lequel est aussi fl\u00e9chisseur et rotateur m\u00e9dial de la cuisse, en plus d'\u00eatre adducteur ?", "choix": ["le long adducteur", "le court adducteur", "le grand adducteur", "le pectin\u00e9"], "bonne": 0, "expl": "Le long adducteur est adducteur, fl\u00e9chisseur ET rotateur m\u00e9dial de la cuisse. Le court et le grand adducteur ne sont qu'adducteurs. Le pectin\u00e9 est cit\u00e9 dans ce groupe mais le cours ne d\u00e9taille pas ses actions.", "slide": 314, "plan": "frontal"}, {"id": "q7-12", "q": "L'articulation coxo-f\u00e9morale (la hanche) est form\u00e9e par quels 2 \u00e9l\u00e9ments ?", "choix": ["l'ac\u00e9tabulum de l'os coxal et la t\u00eate f\u00e9morale", "l'ac\u00e9tabulum de l'os coxal et le grand trochanter", "la fosse iliaque et la t\u00eate f\u00e9morale", "le foramen obtur\u00e9 et la t\u00eate f\u00e9morale"], "bonne": 0, "expl": "L'os coxal s'articule lat\u00e9ralement avec le f\u00e9mur au niveau de l'ac\u00e9tabulum, qui re\u00e7oit la t\u00eate f\u00e9morale.", "slide": 277}], "muscles": [{"nom": "Ilio-psoas", "origine": ["face ant\u00e9rieure de l'os coxal (fosse iliaque)"], "terminaison": ["petit trochanter du f\u00e9mur"], "actions": ["fl\u00e9chisseur de la cuisse"], "slide": 299}, {"nom": "Petit glut\u00e9al", "origine": ["face externe de l'ilium"], "terminaison": ["grand trochanter du f\u00e9mur"], "actions": ["abducteur de la cuisse", "rotateur m\u00e9dial de la cuisse"], "slide": 300}, {"nom": "Moyen glut\u00e9al", "origine": ["face externe de l'ilium"], "terminaison": ["grand trochanter du f\u00e9mur"], "actions": ["abducteur de la cuisse", "stabilisateur du bassin"], "slide": 301}, {"nom": "Grand glut\u00e9al", "origine": ["face externe de l'ilium", "cr\u00eate iliaque", "cr\u00eate sacrale"], "terminaison": ["face post\u00e9rieure du f\u00e9mur"], "actions": ["extenseur de la cuisse", "rotateur lat\u00e9ral de la cuisse", "stabilisateur du bassin"], "slide": 302}, {"nom": "Tenseur du fascia lata", "origine": ["\u00e9pine iliaque ant\u00e9ro-sup\u00e9rieure"], "terminaison": ["tractus ilio-tibial (qui se termine sur le plateau tibial lat\u00e9ral)"], "actions": ["abducteur de la cuisse", "rotateur m\u00e9dial de la cuisse", "fl\u00e9chisseur de la cuisse", "extenseur de la jambe"], "slide": 303}, {"nom": "Sartorius", "origine": ["\u00e9pine iliaque ant\u00e9ro-sup\u00e9rieure"], "terminaison": ["patte d'oie"], "actions": ["fl\u00e9chisseur de la cuisse", "fl\u00e9chisseur de la jambe", "rotateur lat\u00e9ral de la cuisse", "abducteur de la cuisse"], "slide": 309}, {"nom": "Quadriceps f\u00e9moral", "origine": ["droit f\u00e9moral : \u00e9pine iliaque ant\u00e9ro-inf\u00e9rieure", "vaste m\u00e9dial : bord m\u00e9dial du f\u00e9mur", "vaste lat\u00e9ral : bord lat\u00e9ral du f\u00e9mur", "vaste interm\u00e9diaire : face ant\u00e9rieure du f\u00e9mur"], "terminaison": ["tendon commun de la patella, puis tub\u00e9rosit\u00e9 tibiale (ligament patellaire)"], "actions": ["extenseur du genou (les 4 chefs)", "droit f\u00e9moral : fl\u00e9chisseur de la cuisse"], "slide": 311}, {"nom": "Court adducteur", "origine": ["pubis"], "terminaison": ["ligne \u00e2pre du f\u00e9mur"], "actions": ["adducteur de la cuisse"], "slide": 313}, {"nom": "Long adducteur", "origine": ["pubis"], "terminaison": ["ligne \u00e2pre du f\u00e9mur"], "actions": ["adducteur de la cuisse", "fl\u00e9chisseur de la cuisse", "rotateur m\u00e9dial de la cuisse"], "slide": 314}, {"nom": "Grand adducteur", "origine": ["pubis", "tub\u00e9rosit\u00e9 ischiatique"], "terminaison": ["ligne \u00e2pre du f\u00e9mur", "\u00e9picondyle m\u00e9dial du f\u00e9mur"], "actions": ["adducteur de la cuisse"], "slide": 315}, {"nom": "Gracile", "origine": ["pubis"], "terminaison": ["patte d'oie"], "actions": ["fl\u00e9chisseur de la jambe", "rotateur m\u00e9dial de la jambe", "adducteur de la cuisse"], "slide": 316}, {"nom": "Biceps f\u00e9moral", "origine": ["chef long : tub\u00e9rosit\u00e9 ischiatique", "chef court : ligne \u00e2pre du f\u00e9mur"], "terminaison": ["t\u00eate de la fibula"], "actions": ["fl\u00e9chisseur de la jambe", "chef long : extenseur de la cuisse"], "slide": 319}, {"nom": "Semi-tendineux", "origine": ["tub\u00e9rosit\u00e9 ischiatique"], "terminaison": ["patte d'oie"], "actions": ["fl\u00e9chisseur de la jambe", "extenseur de la cuisse"], "slide": 320}, {"nom": "Semi-membraneux", "origine": ["tub\u00e9rosit\u00e9 ischiatique"], "terminaison": ["plateau tibial"], "actions": ["fl\u00e9chisseur de la jambe", "extenseur de la cuisse"], "slide": 320}, {"nom": "Tibial ant\u00e9rieur", "origine": ["bord lat\u00e9ral du tibia"], "terminaison": ["bord m\u00e9dial du gros orteil"], "actions": ["fl\u00e9chisseur dorsal du pied"], "slide": 325}, {"nom": "Gastrocn\u00e9mien", "origine": ["condyles m\u00e9dial et lat\u00e9ral du f\u00e9mur"], "terminaison": ["calcan\u00e9us (par le tendon calcan\u00e9en)"], "actions": ["fl\u00e9chisseur de la jambe", "fl\u00e9chisseur plantaire du pied"], "slide": 328}, {"nom": "Sol\u00e9aire", "origine": ["\u00e9piphyses proximales du tibia et de la fibula"], "terminaison": ["calcan\u00e9us (par le tendon calcan\u00e9en)"], "actions": ["fl\u00e9chisseur plantaire du pied"], "slide": 328}], "pieges": [{"titre": "Le quadriceps : seul le droit f\u00e9moral franchit la hanche", "texte": "Les 4 chefs du quadriceps se terminent ensemble par le tendon commun de la patella puis le ligament patellaire, et sont TOUS extenseurs du genou. Mais un seul, le DROIT F\u00c9MORAL, est aussi fl\u00e9chisseur de la cuisse : son origine (\u00e9pine iliaque ant\u00e9ro-inf\u00e9rieure) est sur l'os coxal, donc il franchit l'articulation coxo-f\u00e9morale (la hanche). Les 3 vastes (m\u00e9dial, lat\u00e9ral, interm\u00e9diaire) s'originent directement sur le f\u00e9mur : ils ne franchissent que le genou, jamais la hanche, et ne peuvent donc agir que sur la jambe.", "slide": 311}, {"titre": "Les ischio-jambiers ont 3 terminaisons diff\u00e9rentes, pas une", "texte": "Biceps f\u00e9moral, semi-tendineux et semi-membraneux partagent la m\u00eame origine (tub\u00e9rosit\u00e9 ischiatique) et les m\u00eames actions (fl\u00e9chisseurs de la jambe, extenseurs de la cuisse), mais PAS la m\u00eame terminaison : le biceps f\u00e9moral se termine sur la t\u00eate de la FIBULA (c\u00f4t\u00e9 lat\u00e9ral), le semi-tendineux \u00e0 la PATTE D'OIE (m\u00e9dial, superficiel), le semi-membraneux sur le PLATEAU TIBIAL (m\u00e9dial, profond). Confondre leurs terminaisons est le pi\u00e8ge le plus fr\u00e9quent sur ce groupe.", "slide": 320}, {"titre": "La patte d'oie r\u00e9unit 3 muscles de 3 groupes diff\u00e9rents", "texte": "Sartorius (groupe ant\u00e9rieur de la cuisse), gracile (groupe m\u00e9dial, les adducteurs) et semi-tendineux (groupe post\u00e9rieur, les ischio-jambiers) se terminent TOUS les 3 \u00e0 la patte d'oie, sur le bord m\u00e9dial du tibia. Trois muscles d'origine et de fonction diff\u00e9rentes, un seul point d'arriv\u00e9e : ne pas confondre avec le semi-membraneux (voisin du semi-tendineux) qui, lui, se termine plus profond\u00e9ment sur le plateau tibial et n'appartient PAS \u00e0 la patte d'oie.", "slide": 320}, {"titre": "Triceps sural : seul le gastrocn\u00e9mien franchit le genou", "texte": "Gastrocn\u00e9mien et sol\u00e9aire se terminent ensemble sur le calcan\u00e9us par le tendon calcan\u00e9en (d'Achille), et sont tous les deux fl\u00e9chisseurs plantaires du pied. Mais seul le GASTROCN\u00c9MIEN est aussi fl\u00e9chisseur de la JAMBE : son origine (condyles m\u00e9dial et lat\u00e9ral du f\u00e9mur) est sur le f\u00e9mur, donc il franchit le genou. Le SOL\u00c9AIRE s'origine sur le tibia et la fibula (\u00e9piphyses proximales) : il ne franchit que la cheville, jamais le genou.", "slide": 328}], "planches": [{"id": "squelette-membre-inferieur-articulations", "titre": "Le squelette du membre inf\u00e9rieur et ses articulations", "vb": "0 0 260 620", "dessin": "<g class='os' fill='none' stroke='currentColor' stroke-width='2'><path d='M90,20 L190,20 L175,95 L105,95 Z'/><circle cx='140' cy='95' r='7'/><path d='M120,85 Q140,72 160,85' stroke-width='2'/><path d='M140,95 L128,380' stroke-width='11' stroke-linecap='round'/><circle cx='128' cy='390' r='9'/><path d='M128,400 L120,560' stroke-width='9' stroke-linecap='round'/><path d='M150,405 L145,555' stroke-width='5' stroke-linecap='round'/><path d='M120,560 L80,585 L135,598 Z'/></g>", "pastilles": [{"n": 1, "x": 150, "y": 30, "t": "Sacro-iliaque", "ancre": "middle", "indice": "o\u00f9 le sacrum rejoint l'ilium, en haut de la ceinture pelvienne"}, {"n": 2, "x": 140, "y": 95, "t": "Coxo-f\u00e9morale", "ancre": "middle", "indice": "hanche ; ac\u00e9tabulum + t\u00eate f\u00e9morale"}, {"n": 3, "x": 128, "y": 390, "t": "F\u00e9moro-patellaire", "ancre": "start", "indice": "la patella, en avant du genou"}, {"n": 4, "x": 110, "y": 398, "t": "Tibio-f\u00e9morale", "ancre": "end", "indice": "genou ; entre les 2 os longs"}, {"n": 5, "x": 150, "y": 408, "t": "Tibio-fibulaire proximale", "ancre": "start", "indice": "juste sous le genou, c\u00f4t\u00e9 fibula"}, {"n": 6, "x": 122, "y": 560, "t": "Talo-crurale", "ancre": "middle", "indice": "cheville ; tibia + fibula + talus"}], "slide": 271}, {"id": "os-coxal-trois-parties", "titre": "L'os coxal, vue lat\u00e9rale : ses 3 parties", "vb": "0 0 220 300", "dessin": "<g class='os' fill='none' stroke='currentColor' stroke-width='2'><path d='M115,130 Q60,40 90,15 Q160,5 175,55 Q170,100 145,132 Z'/><path d='M112,168 Q60,190 55,240 Q65,270 100,260 Q130,240 128,175 Z'/><path d='M148,168 Q195,185 200,225 Q195,255 160,250 Q132,235 132,175 Z'/><circle cx='130' cy='150' r='22'/></g>", "pastilles": [{"n": 1, "x": 120, "y": 40, "t": "Ilium", "ancre": "middle", "indice": "partie sup\u00e9rieure, la plus large"}, {"n": 2, "x": 130, "y": 150, "t": "Ac\u00e9tabulum", "ancre": "middle", "indice": "anneau central ; re\u00e7oit la t\u00eate f\u00e9morale (coxo-f\u00e9morale)"}, {"n": 3, "x": 80, "y": 245, "t": "Ischium", "ancre": "middle", "indice": "partie post\u00e9ro-inf\u00e9rieure"}, {"n": 4, "x": 175, "y": 235, "t": "Pubis", "ancre": "middle", "indice": "partie ant\u00e9ro-inf\u00e9rieure"}], "slide": 277}, {"id": "quadriceps-quatre-chefs", "titre": "Le quadriceps f\u00e9moral : ses 4 chefs, une terminaison commune", "vb": "0 0 220 400", "dessin": "<g class='os' fill='none' stroke='currentColor' stroke-width='2'><path d='M118,22 L118,300' stroke-width='9' stroke-linecap='round'/><circle cx='75' cy='16' r='6'/><circle cx='118' cy='308' r='10'/><path d='M118,318 L112,360' stroke-width='6' stroke-linecap='round'/><path d='M112,360 L108,390' stroke-width='8' stroke-linecap='round'/></g><g class='muscle' fill='none' stroke='currentColor' stroke-width='1.6'><path d='M75,18 L118,306'/><path d='M85,160 L118,306'/><path d='M155,190 L118,306'/><path d='M126,88 L126,298' stroke-dasharray='4 3'/></g>", "pastilles": [{"n": 1, "x": 96, "y": 162, "t": "Droit f\u00e9moral", "ancre": "end", "indice": "seul chef dont l'origine est d\u00e9tach\u00e9e du f\u00e9mur, plus haut (os coxal)"}, {"n": 2, "x": 101, "y": 233, "t": "Vaste lat\u00e9ral", "ancre": "end", "indice": "origine sur le bord lat\u00e9ral du f\u00e9mur, c\u00f4t\u00e9 gauche du sch\u00e9ma"}, {"n": 3, "x": 136, "y": 248, "t": "Vaste m\u00e9dial", "ancre": "start", "indice": "seul chef dont l'origine arrive du c\u00f4t\u00e9 droit du sch\u00e9ma"}, {"n": 4, "x": 126, "y": 88, "t": "Vaste interm\u00e9diaire", "ancre": "start", "indice": "trait pointill\u00e9, tout contre le f\u00e9mur : profond, cach\u00e9 sous le droit f\u00e9moral"}, {"n": 5, "x": 114, "y": 335, "t": "Ligament patellaire", "ancre": "middle", "indice": "terminaison commune des 4 chefs, sous la patella"}], "slide": 311}, {"id": "ischio-jambiers-trois-terminaisons", "titre": "Les ischio-jambiers : une origine commune, 3 terminaisons", "vb": "0 0 220 400", "dessin": "<g class='os' fill='none' stroke='currentColor' stroke-width='2'><path d='M130,28 L122,280' stroke-width='2' stroke-dasharray='2 3'/><circle cx='130' cy='20' r='8'/><circle cx='180' cy='320' r='7'/><circle cx='100' cy='345' r='7'/><path d='M65,280 L95,280' stroke-width='4' stroke-linecap='round'/></g><g class='muscle' fill='none' stroke='currentColor' stroke-width='1.6'><path d='M130,20 L180,320'/><path d='M130,20 L100,345'/><path d='M130,20 L80,280'/></g>", "pastilles": [{"n": 1, "x": 130, "y": 20, "t": "Tub\u00e9rosit\u00e9 ischiatique", "ancre": "middle", "indice": "origine commune des 3 muscles, en haut"}, {"n": 2, "x": 155, "y": 170, "t": "Biceps f\u00e9moral", "ancre": "start", "indice": "le trajet le plus lat\u00e9ral (vers la droite)"}, {"n": 3, "x": 115, "y": 182, "t": "Semi-tendineux", "ancre": "start", "indice": "trajet m\u00e9dial, le plus long (le plus bas)"}, {"n": 4, "x": 96, "y": 150, "t": "Semi-membraneux", "ancre": "end", "indice": "trajet m\u00e9dial, le plus court (s'arr\u00eate au niveau du genou)"}, {"n": 5, "x": 180, "y": 320, "t": "T\u00eate de la fibula", "ancre": "start", "indice": "terminaison lat\u00e9rale, du biceps f\u00e9moral"}, {"n": 6, "x": 100, "y": 345, "t": "Patte d'oie", "ancre": "middle", "indice": "terminaison m\u00e9diale superficielle, du semi-tendineux"}, {"n": 7, "x": 80, "y": 280, "t": "Plateau tibial", "ancre": "end", "indice": "terminaison m\u00e9diale profonde, du semi-membraneux, au niveau du genou"}], "slide": 320}]}]};
